# Vue 3 实现大文件分片上传 + 断点续传

本方案使用 `AbortController` 实现上传中断控制，`IndexedDB` 本地持久化分片状态（包括上传进度、文件名、chunkId、chunkSize、总大小、上传状态等），配合服务端 `Range` 请求支持断点续传。

---

## 一、项目依赖

```bash
npm install axios vue-router@next
```

---

## 二、核心组件结构

- `Upload.vue`：上传组件，支持拖拽、选择文件、上传进度、重传、取消
- `ChunkManager.js`：分片管理器，负责切片、上传、断点续传、合并
- `useUpload.js`：组合式 API，封装上传逻辑

---

## 三、代码实现

### 1. `ChunkManager.js`

```javascript
// ChunkManager.js
import { ref, onUnmounted } from 'vue';
import { createIdb } from './idb.js';

const CHUNK_SIZE = 2 * 1024 * 1024; // 2MB

export class ChunkManager {
  constructor(file, onProgress, onSuccess, onError, onChunkProgress) {
    this.file = file;
    this.onProgress = onProgress;
    this.onSuccess = onSuccess;
    this.onError = onError;
    this.onChunkProgress = onChunkProgress;
    this.idb = createIdb();
    this.abortController = null;
    this.chunks = [];
    this.uploadedBytes = 0;
    this.totalBytes = file.size;
    this.fileKey = this.getFileKey(file);
    this.init();
  }

  getFileKey(file) {
    return `${file.name}-${file.size}-${file.type}-${Date.now()}`;
  }

  async init() {
    await this.idb.open();
    const state = await this.idb.get(this.fileKey);
    if (state && state.chunks) {
      this.chunks = state.chunks;
      this.uploadedBytes = state.uploadedBytes || 0;
      this.totalBytes = state.totalBytes || file.size;
    } else {
      this.chunks = this.split();
    }
  }

  split() {
    const chunks = [];
    let offset = 0;
    while (offset < this.file.size) {
      const size = Math.min(CHUNK_SIZE, this.file.size - offset);
      chunks.push({
        id: this.generateChunkId(offset),
        offset,
        size,
        uploaded: false,
        blob: this.file.slice(offset, offset + size),
      });
      offset += size;
    }
    return chunks;
  }

  generateChunkId(offset) {
    return `${this.fileKey}-${offset}`;
  }

  async uploadAll() {
    this.abortController = new AbortController();
    const uploaders = this.chunks.map((chunk) => {
      if (chunk.uploaded) return Promise.resolve();
      return this.uploadChunk(chunk);
    });
    const results = await Promise.all(uploaders);
    const failed = results.filter((r) => r instanceof Error);
    if (failed.length > 0) {
      this.onError(failed[0]);
      return;
    }
    await this.idb.set(this.fileKey, {
      chunks: this.chunks,
      uploadedBytes: this.totalBytes,
      totalBytes: this.totalBytes,
    });
    this.onSuccess();
  }

  async uploadChunk(chunk) {
    const { id, offset, size, blob } = chunk;
    const url = `/api/upload`;
    const formData = new FormData();
    formData.append('file', blob);
    formData.append('chunkId', id);
    formData.append('chunkSize', size);
    formData.append('totalSize', this.totalBytes);
    formData.append('fileName', this.file.name);

    const onProgress = (ev) => {
      const loaded = ev.loaded;
      const total = ev.total || size;
      const pct = total ? (loaded / total) * 100 : 0;
      if (this.onChunkProgress) this.onChunkProgress(pct, chunk);
    };

    try {
      const res = await fetch(url, {
        method: 'POST',
        body: formData,
        signal: this.abortController.signal,
        onUploadProgress: onProgress,
      });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const data = await res.json();
      if (data.code !== 0) throw new Error(data.message || 'upload failed');
      chunk.uploaded = true;
      this.uploadedBytes += size;
      if (this.onProgress) {
        const pct = (this.uploadedBytes / this.totalBytes) * 100;
        this.onProgress(pct);
      }
      return null;
    } catch (err) {
      if (err.name === 'AbortError') {
        throw new Error('Upload aborted by user');
      }
      throw err;
    }
  }

  cancel() {
    if (this.abortController) {
      this.abortController.abort();
      this.abortController = null;
    }
    this.chunks.forEach((c) => (c.uploaded = false));
    this.uploadedBytes = 0;
    this.idb.delete(this.fileKey);
    if (this.onCancel) this.onCancel();
  }

  pause() {
    if (this.abortController) {
      this.abortController.abort();
      this.abortController = null;
    }
  }

  resume() {
    if (!this.abortController) {
      this.abortController = new AbortController();
      this.uploadAll();
    }
  }
}
```

