### 3. `useUpload.js` — 组合式 API

```javascript
// useUpload.js
import { ref, onUnmounted } from 'vue';
import { ChunkManager } from './ChunkManager.js';

export function useUpload() {
  const isUploading = ref(false);
  const progress = ref(0);
  const chunkProgress = ref(0);
  const currentFile = ref(null);
  const status = ref('idle'); // idle | uploading | paused | success | failed
  const chunks = ref([]);
  const cancelToken = ref(null);

  const startUpload = async (file) => {
    if (!file || file.size === 0) {
      throw new Error('请选择文件');
    }
    if (status.value !== 'idle') throw new Error('已有上传任务进行中');
    status.value = 'uploading';
    isUploading.value = true;
    progress.value = 0;
    chunkProgress.value = 0;
    currentFile.value = file;

    const manager = new ChunkManager(
      file,
      (p) => {
        progress.value = p;
      },
      () => {
        status.value = 'success';
        isUploading.value = false;
        currentFile.value = null;
      },
      (err) => {
        status.value = 'failed';
        isUploading.value = false;
        currentFile.value = null;
        throw err;
      },
      (p) => {
        chunkProgress.value = p;
      }
    );

    cancelToken.value = {
      cancel: () => manager.cancel(),
      pause: () => manager.pause(),
      resume: () => manager.resume(),
    };

    try {
      await manager.uploadAll();
    } catch (err) {
      if (err.message !== 'Upload aborted by user') {
        console.error(err);
      }
    } finally {
      cancelToken.value = null;
    }
  };

  const pause = () => {
    if (cancelToken.value && cancelToken.value.pause) {
      cancelToken.value.pause();
      status.value = 'paused';
    }
  };

  const resume = () => {
    if (cancelToken.value && cancelToken.value.resume) {
      cancelToken.value.resume();
      status.value = 'uploading';
    }
  };

  const cancel = () => {
    if (cancelToken.value && cancelToken.value.cancel) {
      cancelToken.value.cancel();
    }
  };

  onUnmounted(() => {
    if (cancelToken.value) {
      cancelToken.value.cancel();
    }
  });

  return {
    isUploading,
    progress,
    chunkProgress,
    currentFile,
    status,
    startUpload,
    pause,
    resume,
    cancel,
    cancelToken,
  };
}
```

