### 5. 服务端示例（Node.js + Express）

```javascript
// server.js
const express = require('express');
const fs = require('fs').promises;
const path = require('path');
const app = express();

app.use(express.json());
app.use(express.raw({ type: 'application/octet-stream' }));

const UPLOAD_DIR = './uploads';
const CHUNK_DIR = './chunks';

async function ensureDir(dir) {
  try {
    await fs.access(dir);
  } catch {
    await fs.mkdir(dir, { recursive: true });
  }
}

app.post('/api/upload', async (req, res) => {
  const { chunkId, chunkSize, totalSize, fileName } = req.body;
  const chunk = req.body.file || req.body;

  const chunkPath = path.join(CHUNK_DIR, chunkId);
  await ensureDir(CHUNK_DIR);
  await fs.writeFile(chunkPath, chunk);

  const finalPath = path.join(UPLOAD_DIR, fileName);
  await ensureDir(UPLOAD_DIR);

  // 合并（服务端合并）
  try {
    const existing = await fs.readFile(finalPath);
    const newChunk = await fs.readFile(chunkPath);
    await fs.writeFile(finalPath, Buffer.concat([existing, newChunk]));
    await fs.unlink(chunkPath);
    res.json({ code: 0, message: 'ok' });
  } catch (e) {
    // 断点续传：只追加新块
    await fs.writeFile(finalPath, newChunk, { flag: 'a' });
    await fs.unlink(chunkPath);
    res.json({ code: 0, message: 'ok' });
  }
});

app.listen(3000, () => {
  console.log('Server running on http://localhost:3000');
});
```

