        <div class="f-card-name">${f.name}</div>
        <div class="f-card-desc">${f.desc}</div>
        <div class="f-card-price">$${f.price}</div>
      </div>
    `;
    card.addEventListener('dragstart', (e) => {
      e.dataTransfer.setData('text/plain', f.id);
      card.classList.add('dragging');
    });
    card.addEventListener('dragend', () => card.classList.remove('dragging'));
    card.addEventListener('click', () => addToCart(f.id));
    list.appendChild(card);
  });
  document.getElementById('shopCount').textContent = `Showing ${items.length} item${items.length !== 1 ? 's' : ''}`;
}

function renderCart() {
  const list = document.getElementById('cartList');
  list.innerHTML = '';
  if (state.cart.length === 0) {
    list.innerHTML = '<p class="text-center text-gray-500 py-4">Your cart is empty.</p>';
    document.getElementById('cartTotal').textContent = '$0';
    return;
  }
  state.cart.forEach(item => {
    const el = document.createElement('div');
    el.className = 'cart-item';
    el.innerHTML = `
      <span>${FURNITURE.find(f => f.id === item.id).name}</span>
      <span class="price">$${item.price}</span>
    `;
    list.appendChild(el);
  });
  const total = state.cart.reduce((s, i) => s + i.price, 0);
  document.getElementById('cartTotal').textContent = `$${total}`;
  document.getElementById('cartCount').textContent = state.cart.length;
}

function renderPlan() {
  const list = document.getElementById('planSummary');
  list.innerHTML = '';
  if (state.currentPlan) {
    const items = state.currentPlan.items;
    items.forEach(id => {
      const el = document.createElement('div');
      el.className = 'flex justify-between items-center';
      el.innerHTML = `<span>${FURNITURE.find(f => f.id === id).name}</span><span>$${FURNITURE.find(f => f.id === id).price}</span>`;
      list.appendChild(el);
    });
    const total = items.reduce((s, id) => s + FURNITURE.find(f => f.id === id).price, 0);
    document.getElementById('planCount').textContent = items.length;
    document.getElementById('planTotal').textContent = `$${total}`;
  } else {
    document.getElementById('planCount').textContent = '0';
    document.getElementById('planTotal').textContent = '$0';
  }
}

function renderRoom() {
  const room = document.getElementById('room');
  const layer = document.getElementById('furnitureLayer');
  layer.innerHTML = '';
  if (state.currentTemplate) {
    const t = TEMPLATES[state.currentTemplate];
    room.style.backgroundImage = `url('${t.bg}')`;
  } else {
    room.style.backgroundImage = 'none';
  }

  state.currentPlan?.items.forEach(id => {
    const f = FURNITURE.find(x => x.id === id);
    if (!f) return;
    const el = document.createElement('div');
    el.className = 'furniture-item';
    el.style.left = `${Math.random() * 80}%`;
    el.style.top = `${Math.random() * 80}%`;
    el.style.width = `${f.w}px`;
    el.style.height = `${f.h}px`;
    el.style.backgroundImage = `url('${f.img}')`;
    el.dataset.id = f.id;
    el.setAttribute('draggable', 'false');
    layer.appendChild(el);
  });
}

/* ---------- ACTIONS ---------- */
function addToCart(id) {
  const f = FURNITURE.find(x => x.id === id);
  if (!f) return;
  state.cart.push({ id, price: f.price });
  renderCart();
  toast(`Added ${f.name} to cart`);
}

function removeFromCart(id) {
  state.cart = state.cart.filter(i => i.id !== id);
  renderCart();
}

function savePlan() {
  if (!state.currentPlan) {
    state.currentPlan = { id: Date.now(), items: [] };
    state.plans.push(state.currentPlan);
  }
  state.currentPlan.items = state.currentPlan.items.filter(i => i !== id);
  renderPlan();
  toast('Plan saved');
}

function openLogin() {
  document.getElementById('loginModal').classList.remove('hidden');
}
function closeLogin() {
  document.getElementById('loginModal').classList.add('hidden');
}
document.getElementById('loginForm').addEventListener('submit', (e) => {
  e.preventDefault();
  const email = document.getElementById('loginEmail').value;
  state.user = { email };
  localStorage.setItem('homestyle_user', JSON.stringify(state.user));
  closeLogin();
  toast('Welcome, ' + email.split('@')[0] + '!');
});

/* ---------- DRAG & DROP ---------- */
function handleDragOver(e) {
  e.preventDefault();
  e.dataTransfer.dropEffect = 'copy';
}
function handleDrop(e) {
  e.preventDefault();
  const id = parseInt(e.dataTransfer.getData('text/plain'));
  if (!id) return;
  const f = FURNITURE.find(x => x.id === id);
  if (!f) return;
  state.currentPlan = state.currentPlan || { id: Date.now(), items: [] };
  state.currentPlan.items.push(id);
  renderRoom();
  renderPlan();
  toast(`Placed ${f.name} in your plan`);
}

/* ---------- EVENT BINDINGS ---------- */
document.getElementById('categoryList').addEventListener('click', (e) => {
  const btn = e.target.closest('button[data-cat]');
  if (!btn) return;
  state.currentCategory = btn.dataset.cat;
  renderShop();
});

document.getElementById('savePlanBtn').addEventListener('click', () => {
  if (!state.currentPlan) {
    state.currentPlan = { id: Date.now(), items: [] };
    state.plans.push(state.currentPlan);
  }
  state.currentPlan.items = state.currentPlan.items.filter(i => i !== id);
  renderPlan();
  toast('Plan saved');
});

document.getElementById('checkoutBtn').addEventListener('click', () => {
  if (state.cart.length === 0) return;
  toast('Checkout: ' + state.cart.length + ' items');
});

document.getElementById('openCartBtn').addEventListener('click', () => {
  toast('Cart: ' + state.cart.length + ' items');
});

document.getElementById('userBtn').addEventListener('click', () => {
  if (!state.user) openLogin();
  else toast('Signed in as ' + state.user.email.split('@')[0]);
});

document.getElementById('mobileMenuBtn').addEventListener('click', () => {
  document.getElementById('mobileMenu').classList.toggle('hidden');
});

/* Room drag events */
document.getElementById('room').addEventListener('dragover', handleDragOver);
document.getElementById('room').addEventListener('drop', handleDrop);

/* Template buttons */
document.querySelectorAll('[data-template]').forEach(btn => {
  btn.addEventListener('click', () => {
    state.currentTemplate = btn.dataset.template;
    state.currentPlan = { id: Date.now(), items: TEMPLATES[state.currentTemplate].items };
    state.plans.push(state.currentPlan);
    renderRoom();
    renderPlan();
    toast('Applied ' + btn.dataset.template + ' template');
  });
});

/* ---------- TOAST ---------- */
function toast(msg) {
  const t = document.getElementById('toast');
  document.getElementById('toastMsg').textContent = msg;
  t.classList.remove('hidden');
  clearTimeout(toast._t);
  toast._t = setTimeout(() => t.classList.add('hidden'), 2500);
}

/* ---------- INIT ---------- */
load();
renderShop();
renderCart();
renderPlan();
renderRoom();
save();
```

Creating a complete online music theory learning website is a substantial project, but I can provide you with a **fully functional, production-ready demo** using modern web technologies (HTML, CSS, JavaScript, Web Audio API, and a few libraries). This demo covers:

- Introduction pages on **scales** and **chords**
- **Audio examples** (synthesized via Web Audio)
- A **practice module** where users build chords and get instant feedback
- Responsive, accessible UI

---

## ✅ Features

- **Intro Pages**: Scales, Chords, Intervals, Keys
- **Audio Player**: Play any scale or chord with a single click
- **Practice Mode**: Build chords from notes, auto-check correctness
- **Progress Tracking**: Score per practice session
- **Dark/Light theme toggle**

---

