```javascript
// ---------- Audio Synthesis (Web Audio API) ----------
const audioCtx = (() => {
  let ctx = null;
  try { ctx = new (window.AudioContext || window.webkitAudioContext)(); }
  catch (e) { return null; }
  return ctx;
})();

function playNote(freq, duration = 0.5, type = 'triangle', volume = 0.25) {
  if (!audioCtx) return;
  const osc = audioCtx.createOscillator();
  const gain = audioCtx.createGain();
  osc.type = type;
  osc.frequency.value = freq;
  gain.gain.setValueAtTime(volume, audioCtx.currentTime);
  gain.gain.exponentialRampToValueAtTime(0.0001, audioCtx.currentTime + duration);
  osc.connect(gain).connect(audioCtx.destination);
  osc.start();
  osc.stop(audioCtx.currentTime + duration);
}

function playChord(frequencies, duration = 1.2, type = 'triangle', volume = 0.25) {
  if (!audioCtx) return;
  frequencies.forEach(f => playNote(f, duration, type, volume));
}

function playScale(root, scaleName, duration = 0.5, type = 'triangle', volume = 0.2) {
  const notes = getScale(root, scaleName);
  notes.forEach(n => playNote(n, duration, type, volume));
}

function getScale(root, scaleName) {
  const rootFreq = getFreq(root);
  const intervals = {
    'major': [0, 2, 4, 5, 7, 9, 11],
    'minor': [0, 2, 3, 5, 7, 8, 10],
    'dorian': [0, 2, 3, 5, 7, 9, 10],
    'phrygian': [0, 1, 3, 5, 7, 8, 10],
    'lydian': [0, 2, 4, 6, 7, 9, 11],
    'mixolydian': [0, 2, 4, 5, 7, 9, 10],
    'aeolian': [0, 2, 3, 5, 7, 8, 10],
    'locrian': [0, 1, 3, 5, 6, 8, 10],
    'majorPentatonic': [0, 2, 4, 7, 9],
    'minorPentatonic': [0, 3, 5, 7, 10]
  };
  const semitones = intervals[scaleName] || intervals.major;
  return semitones.map(s => rootFreq + s * 100);
}

function getFreq(note) {
  const [letter, accidental] = note.match(/([A-G])(?:[b#]?)/i) || [];
  const acc = (accidental || '').replace(/[^b#]/g, '');
  const semitones = {
    'A': 0, 'B': 2, 'C': 3, 'D': 5, 'E': 7, 'F': 8, 'G': 10
  }[letter.toUpperCase()] || 0;
  const sharp = acc.includes('#') ? 1 : 0;
  const flat = acc.includes('b') ? -1 : 0;
  return Math.pow(2, (semitones + sharp + flat + 12) / 12) * 440;
}

// ---------- Chord Theory ----------
const CHORDS = {
  'C major triad': { root: 'C', type: 'major', notes: ['C', 'E', 'G'] },
  'Am minor triad': { root: 'A', type: 'minor', notes: ['A', 'C', 'E'] },
  'G minor triad': { root: 'G', type: 'minor', notes: ['G', 'B♭', 'D'] },
  'E diminished': { root: 'E', type: 'diminished', notes: ['E', 'G', 'B♭'] },
  'C major 7': { root: 'C', type: 'maj7', notes: ['C', 'E', 'G', 'B'] },
  'C7': { root: 'C', type: '7', notes: ['C', 'E', 'G', 'B♭'] },
  'Cm7': { root: 'C', type: 'm7', notes: ['C', 'E♭', 'G', 'B♭'] },
  'Cm7♭5': { root: 'C', type: 'm7♭5', notes: ['C', 'E♭', 'G♭', 'B♭'] }
};

// ---------- Practice Logic ----------
const ROOTS = ['C', 'D', 'E', 'F', 'G', 'A', 'B'];
const TYPES = ['Major', 'Minor', 'Diminished', 'Maj7', '7', 'm7', 'm7♭5'];
const CORRECT_CHORDS = [
  { root: 'C', type: 'Major', notes: ['C', 'E', 'G'] },
  { root: 'C', type: 'Minor', notes: ['C', 'E♭', 'G'] },
  { root: 'C', type: 'Diminished', notes: ['C', 'E♭', 'G♭'] },
  { root: 'C', type: 'Maj7', notes: ['C', 'E', 'G', 'B'] },
  { root: 'C', type: '7', notes: ['C', 'E', 'G', 'B♭'] },
  { root: 'C', type: 'm7', notes: ['C', 'E♭', 'G', 'B♭'] },
  { root: 'C', type: 'm7♭5', notes: ['C', 'E♭', 'G♭', 'B♭'] }
];

let currentChord = null;
let selectedNotes = [];
let score = 0;

function pickRandomChord() {
  const pool = [...CORRECT_CHORDS];
  const idx = Math.floor(Math.random() * pool.length);
  const c = pool[idx];
  currentChord = c;
  selectedNotes = [];
  document.getElementById('rootValue').textContent = c.root;
  document.getElementById('typeValue').textContent = c.type;
  document.querySelectorAll('.note-card').forEach(card => {
    card.classList.remove('selected');
    card.dataset.selected = 'false';
  });
  document.getElementById('feedback').innerHTML = '';
}

function toggleNote(card) {
  const idx = card.dataset.note;
  if (selectedNotes.includes(idx)) {
    selectedNotes = selectedNotes.filter(n => n !== idx);
    card.classList.remove('selected');
    card.dataset.selected = 'false';
  } else {
    selectedNotes.push(idx);
    card.classList.add('selected');
    card.dataset.selected = 'true';
  }
}

function checkChord() {
  if (!currentChord) return;
  const userNotes = [];
  selectedNotes.forEach(idx => {
    userNotes.push(currentChord.notes[idx]);
  });
  const expected = currentChord.notes;
  const correct = userNotes.length === expected.length && userNotes.every((n, i) => n === expected[i]);
  const feedbackEl = document.getElementById('feedback');
  if (correct) {
    score++;
    feedbackEl.className = 'feedback success';
    feedbackEl.innerHTML = '<span class="check">✓</span> Perfect chord! ' + currentChord.root + ' ' + currentChord.type;
    playChord(expected.map(getFreq), 1.2, 'triangle', 0.25);
  } else {
    feedbackEl.className = 'feedback error';
    feedbackEl.innerHTML = '<span class="x">✕</span> Try again — ' + currentChord.root + ' ' + currentChord.type;
    playScale(currentChord.root, 'major', 0.8, 'triangle', 0.15);
  }
}

// ---------- Audio Events ----------
document.addEventListener('click', (e) => {
  const btn = e.target.closest('.audio-btn');
  if (!btn) return;
  const text = btn.dataset.scale || btn.dataset.chord || btn.dataset.interval;
  if (btn.dataset.scale) {
    playScale(btn.dataset.scale.split(' ')[0], btn.dataset.scale.split(' ')[1], 1.2, 'triangle', 0.2);
  } else if (btn.dataset.chord) {
    const chord = CHORDS[btn.dataset.chord];
    if (chord) playChord(chord.notes.map(getFreq), 1.5, 'triangle', 0.25);
  } else if (btn.dataset.interval) {
    const interval = btn.dataset.interval;
    const root = getFreq('C');
    const intervalsMap = {
      'Unison': 0, 'Minor 2nd': 1, 'Major 2nd': 2, 'Minor 3rd': 3, 'Major 3rd': 4,
      'Perfect 4th': 5, 'Perfect 5th': 7, 'Major 6th': 9, 'Major 7th': 11
    };
    const semitones = intervalsMap[interval] || 0;
    playNote(root + semitones * 100, 1, 'triangle', 0.2);
  }
});

// ---------- Practice Events ----------
document.getElementById('rootChip').addEventListener('click', () => {
  pickRandomChord();
});
document.querySelectorAll('.note-card').forEach(card => {
  card.addEventListener('click', () => toggleNote(card));
});
document.getElementById('checkBtn').addEventListener('click', checkChord);
document.getElementById('resetBtn').addEventListener('click', () => {
  selectedNotes = [];
  document.querySelectorAll('.note-card').forEach(card => {
    card.classList.remove('selected');
    card.dataset.selected = 'false';
  });
  document.getElementById('feedback').innerHTML = '';
});

// ---------- Theme ----------
document.getElementById('themeToggle').addEventListener('click', () => {
  const root = document.documentElement;
  const current = root.getAttribute('data-theme') || 'light';
  const next = current === 'dark' ? 'light' : 'dark';
  root.setAttribute('data-theme', next);
  try { localStorage.setItem('theme', next); } catch (e) {}
});

// ---------- Init ----------
(function init() {
  const saved = (() => {
    try { return localStorage.getItem('theme'); } catch (e) { return null; }
  })();
  if (saved) document.documentElement.setAttribute('data-theme', saved);
  pickRandomChord();
})();
