## 📜 bubble-shooter.js

```javascript
(() => {
  'use strict';

  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const hudScore = document.getElementById('score');
  const hudLives = document.getElementById('lives');
  const hudPause = document.getElementById('pauseText');

  const GRID_W = 10, GRID_H = 10;
  const COLORS = ['#FF3B30', '#3B5BFF', '#3BFF6A', '#FFC800', '#B53BFF', '#FF8C00'];
  const GRAVITY = 0.15;
  const DAMP = 0.985;
  const ADHESION = 18; // max distance to merge
  const SHOT_SPEED = 7.5;
  const BUBBLE_R = 14;
  const ROW_HEIGHT = 100;
  const COL_WIDTH = 100;
  const MARGIN_X = 40;
  const MARGIN_Y = 60;
  const CANON_W = 60;
  const CANON_H = 24;
  const CANON_OFFSET = 20;

  let W = 0, H = 0, DPR = 1;
  let bubbles = [];
  let cannon = { x: 0, y: 0, angle: 0, r: 0, shootCooldown: 0 };
  let mouse = { x: 0, y: 0, down: false };
  let score = 0;
  let lives = 3;
  let paused = false;
  let lastTime = 0;
  let particles = [];
  let shake = 0;

  // Hex grid: (col, row) -> bubble index
  const grid = new Array(GRID_W).fill(null).map(() => new Array(GRID_H).fill(null));

  function resize() {
    DPR = Math.min(window.devicePixelRatio || 1, 2);
    W = window.innerWidth;
    H = window.innerHeight;
    canvas.width = W * DPR;
    canvas.height = H * DPR;
    canvas.style.width = W + 'px';
    canvas.style.height = H + 'px';
    ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
  }
  window.addEventListener('resize', resize);

  function initGrid() {
    bubbles.length = 0;
    grid.forEach(row => row.fill(null));
    const cx = MARGIN_X + (GRID_W - 1) * COL_WIDTH / 2;
    const cy = MARGIN_Y + ROW_HEIGHT * (GRID_H - 1) / 2;
    for (let r = 0; r < GRID_H; r++) {
      for (let c = 0; c < GRID_W; c++) {
        const x = cx + c * COL_WIDTH;
        const y = cy - r * ROW_HEIGHT;
        const colorIdx = (c + r) % COLORS.length;
        const b = new Bubble(x, y, colorIdx);
        bubbles.push(b);
        grid[c][r] = b;
      }
    }
  }

  function spawnShot() {
    const angle = cannon.angle;
    const speed = SHOT_SPEED;
    const vx = Math.cos(angle) * speed;
    const vy = Math.sin(angle) * speed;
    const b = new Bubble(cannon.x + CANON_OFFSET, cannon.y + CANON_H / 2, 0, vx, vy, true);
    bubbles.push(b);
    return b;
  }

  function findConnected(color, startIdx) {
    const visited = new Set([startIdx]);
    const stack = [startIdx];
    const neighbors = [];
    while (stack.length) {
      const idx = stack.pop();
      const b = bubbles[idx];
      for (let i = 0; i < bubbles.length; i++) {
        if (visited.has(i)) continue;
        const nb = bubbles[i];
        if (nb.color !== b.color) continue;
        const dx = nb.x - b.x, dy = nb.y - b.y;
        if (dx * dx + dy * dy < ADHESION * ADHESION) {
          visited.add(i);
          stack.push(i);
          neighbors.push(i);
        }
      }
    }
    return neighbors;
  }

  function findChain(bubblesOnScreen) {
    const groups = [];
    const visited = new Set();
    for (const b of bubblesOnScreen) {
      if (visited.has(b.idx)) continue;
      const group = [b.idx];
      visited.add(b.idx);
      for (let i = 0; i < bubblesOnScreen.length; i++) {
        const nb = bubblesOnScreen[i];
        if (visited.has(nb.idx)) continue;
        if (nb.color === b.color) {
          const dx = nb.x - b.x, dy = nb.y - b.y;
          if (dx * dx + dy * dy < ADHESION * ADHESION) {
            visited.add(nb.idx);
            group.push(nb.idx);
          }
        }
      }
      if (group.length >= 3) groups.push(group);
    }
    return groups;
  }

  function explode(group) {
    const count = group.length;
    score += count * 10;
    hudScore.textContent = score;
    particles.length = 0;
    for (const idx of group) {
      const b = bubbles[idx];
      bubbles.splice(idx, 1);
      grid[b.col][b.row] = null;
      const spawners = 6;
      for (let k = 0; k < spawners; k++) {
        const ang = (Math.random() * Math.PI * 2);
        const sp = Math.random() * 4 + 1;
        particles.push({
          x: b.x, y: b.y,
          vx: Math.cos(ang) * sp,
          vy: Math.sin(ang) * sp,
          life: 1, maxLife: 0.45 + Math.random() * 0.3,
          size: 3 + Math.random() * 4,
          color: COLORS[b.color]
        });
      }
      shake += 2;
    }
    // Play sound
    try {
      const ctx = new (window.AudioContext || window.webkitAudioContext)();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(800 + Math.random() * 400, ctx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(200, ctx.currentTime + 0.15);
      gain.gain.setValueAtTime(0.15, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.15);
      osc.connect(gain).connect(ctx.destination);
      osc.start();
      osc.stop(ctx.currentTime + 0.15);
    } catch (e) {}
  }

  function update(dt) {
    if (paused) return;

    // Cannon
    if (mouse.down && cannon.shootCooldown <= 0) {
      spawnShot();
      cannon.shootCooldown = 0.35;
    }
    if (cannon.shootCooldown > 0) cannon.shootCooldown -= dt;

    // Update bubbles
    for (let i = 0; i < bubbles.length; i++) {
      const b = bubbles[i];
      if (b.dead) continue;
      b.vy += GRAVITY;
      b.x += b.vx;
      b.y += b.vy;
      b.vx *= DAMP;
      b.vy *= DAMP;

      // Wall collisions
      if (b.x - BUBBLE_R < MARGIN_X) { b.x = MARGIN_X + BUBBLE_R; b.vx = Math.abs(b.vx) * 0.7; }
      if (b.x + BUBBLE_R > W - MARGIN_X) { b.x = W - MARGIN_X - BUBBLE_R; b.vx = -Math.abs(b.vx) * 0.7; }
      if (b.y - BUBBLE_R < MARGIN_Y) { b.y = MARGIN_Y + BUBBLE_R; b.vy = Math.abs(b.vy) * 0.7; }

      // Bottom collision (if below matrix)
      if (b.y + BUBBLE_R > H - MARGIN_Y) {
        b.y = H - MARGIN_Y - BUBBLE_R;
        b.vy *= -0.5;
      }

      // Adhesion with other bubbles
      for (let j = i + 1; j < bubbles.length; j++) {
        const nb = bubbles[j];
        if (nb.dead) continue;
        const dx = nb.x - b.x, dy = nb.y - b.y;
        const d = Math.hypot(dx, dy);
        if (d < ADHESION * 2) {
          const nx = dx / d, ny = dy / d;
          const overlap = ADHESION * 2 - d;
          const push = overlap / 2;
          b.x += nx * push; b.y += ny * push;
          nb.x -= nx * push; nb.y -= ny * push;
          // Merge if same color
          if (b.color === nb.color) {
            // Merge physics: average velocity
            const totalM = 1;
            b.vx = (b.vx + nb.vx) / 2;
            b.vy = (b.vy + nb.vy) / 2;
            // Remove one
            bubbles.splice(j, 1);
            grid[nb.col][nb.row] = null;
            // Update grid reference
            if (b.col !== nb.col || b.row !== nb.row) {
              grid[b.col][b.row] = b;
              grid[nb.col][nb.row] = null;
            }
            j--; // recheck
          }
        }
      }

      // Remove off-screen
      if (b.x < -50 || b.x > W + 50 || b.y < -50) {
        b.dead = true;
      }
    }

    // Update particles
    for (let i = particles.length - 1; i >= 0; i--) {
      const p = particles[i];
      p.x += p.vx;
      p.y += p.vy;
      p.vy += 0.08;
      p.vx *= 0.97;
      p.life -= dt;
      if (p.life <= 0) particles.splice(i, 1);
    }

    // Chain detection
    const onScreen = bubbles.filter(b => !b.dead);
    const chains = findChain(onScreen);
    if (chains.length) {
      for (const chain of chains) {
        explode(chain);
      }
    }

    // Respawn grid if empty
    const empty = onScreen.length === 0;
    if (empty) {
      initGrid();
    }
  }

  function draw() {
    ctx.clearRect(0, 0, W, H);

    // Shake
    if (shake > 0) {
      const sx = (Math.random() - 0.5) * shake;
      const sy = (Math.random() - 0.5) * shake;
      ctx.save();
      ctx.translate(sx, sy);
      shake -= dt * 2;
      ctx.restore();
    }

    // Background
    const grd = ctx.createLinearGradient(0, 0, 0, H);
    grd.addColorStop(0, '#1a1a33');
    grd.addColorStop(1, '#0a0a1f');
    ctx.fillStyle = grd;
    ctx.fillRect(0, 0, W, H);

    // Hex grid
    drawHexGrid();

    // Bubbles
    for (const b of bubbles) {
      if (b.dead) continue;
      ctx.save();
      ctx.globalAlpha = 0.95;
      ctx.fillStyle = COLORS[b.color];
      ctx.beginPath();
      ctx.arc(b.x, b.y, BUBBLE_R, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }

    // Particles
    for (const p of particles) {
      const a = Math.min(1, p.life / p.maxLife);
      ctx.globalAlpha = a;
      ctx.fillStyle = p.color;
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.globalAlpha = 1;

    // Trajectory preview
    if (mouse.down && cannon.shootCooldown <= 0) {
      const angle = cannon.angle;
      const endX = cannon.x + CANON_OFFSET + Math.cos(angle) * 200;
      const endY = cannon.y + CANON_H / 2 + Math.sin(angle) * 200;
      ctx.strokeStyle = 'rgba(255,255,255,0.35)';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(cannon.x + CANON_OFFSET, cannon.y + CANON_H / 2);
      ctx.lineTo(endX, endY);
      ctx.stroke();
    }

    // Cannon
    ctx.save();
    ctx.translate(cannon.x, cannon.y);
    ctx.rotate(cannon.angle);
    ctx.fillStyle = '#3a3a66';
    ctx.fillRect(-CANON_W / 2, -CANON_H / 2, CANON_W, CANON_H);
    ctx.fillStyle = '#000';
    ctx.fillRect(-CANON_W / 2, -CANON_H / 2, CANON_W, 4);
    ctx.restore();

    // HUD
    hudPause.textContent = paused ? 'Paused' : 'Ready';
  }

  function drawHexGrid() {
    const cx = MARGIN_X + (GRID_W - 1) * COL_WIDTH / 2;
    const cy = MARGIN_Y + ROW_HEIGHT * (GRID_H - 1) / 2;
    ctx.strokeStyle = 'rgba(255,255,255,0.08)';
    ctx.lineWidth = 1;
    for (let r = 0; r < GRID_H; r++) {
      for (let c = 0; c < GRID_W; c++) {
        const b = grid[c][r];
        if (!b) continue;
        const x = cx + c * COL_WIDTH;
        const y = cy - r * ROW_HEIGHT;
        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(x + BUBBLE_R * 2, y);
        ctx.lineTo(x + BUBBLE_R, y - BUBBLE_R * 1.732);
        ctx.lineTo(x - BUBBLE_R, y - BUBBLE_R * 1.732);
        ctx.lineTo(x - BUBBLE_R * 2, y);
        ctx.closePath();
        ctx.fill();
        ctx.stroke();
      }
    }
  }

  class Bubble {
    constructor(x, y, color, vx = 0, vy = 0, isShot = false) {
      this.x = x;
      this.y = y;
      this.vx = vx;
      this.vy = vy;
      this.color = color;
      this.dead = false;
      this.idx = bubbles.length;
      this.col = -1;
      this.row = -1;
      if (isShot) {
        this.col = -1;
        this.row = -1;
      } else {
        // Place on grid
        for (let r = 0; r < GRID_H; r++) {
          for (let c = 0; c < GRID_W; c++) {
            if (grid[c][r] === null) {
              grid[c][r] = this;
              this.col = c; this.row = r;
              return;
            }
          }
        }
      }
    }
  }

  function loop(ts) {
    const dt = Math.min(0.05, (ts - lastTime) / 1000 || 0);
    lastTime = ts;
    update(dt);
    draw();
    requestAnimationFrame(loop);
  }

  // Input
  canvas.addEventListener('mousemove', e => {
    const rect = canvas.getBoundingClientRect();
    mouse.x = e.clientX - rect.left;
    mouse.y = e.clientY - rect.top;
    const cx = W / 2;
    const cy = H - 120;
    const dx = mouse.x - cx;
    const dy = mouse.y - cy;
    cannon.angle = Math.atan2(dy, dx);
  });

  canvas.addEventListener('mousedown', e => {
    mouse.down = true;
  });
  window.addEventListener('mouseup', () => {
    mouse.down = false;
  });

  window.addEventListener('keydown', e => {
    if (e.code === 'Space') {
      paused = !paused;
      hudPause.textContent = paused ? 'Paused' : 'Ready';
      e.preventDefault();
    } else if (e.code === 'KeyR') {
      initGrid();
      score = 0;
      lives = 3;
      hudScore.textContent = score;
      hudLives.textContent = lives;
      paused = false;
      hudPause.textContent = 'Ready';
    } else if (e.code === 'KeyP') {
      paused = !paused;
      hudPause.textContent = paused ? 'Paused' : 'Ready';
    }
  });

  // Touch support
  canvas.addEventListener('touchmove', e => {
    const t = e.touches[0];
    const rect = canvas.getBoundingClientRect();
    mouse.x = t.clientX - rect.left;
    mouse.y = t.clientY - rect.top;
    e.preventDefault();
  }, { passive: false });
  canvas.addEventListener('touchstart', e => {
    const t = e.touches[0];
    const rect = canvas.getBoundingClientRect();
    mouse.x = t.clientX - rect.left;
    mouse.y = t.clientY - rect.top;
    mouse.down = true;
    e.preventDefault();
  }, { passive: false });
  canvas.addEventListener('touchend', () => { mouse.down = false; });

  resize();
  initGrid();
  requestAnimationFrame(loop);
})();
```

