from flask_wtf import FlaskForm
from wtforms import StringField, TextAreaField, FloatField, FileField, SelectField, SubmitField
from wtforms.validators import DataRequired, Length, NumberRange, Optional
from flask_wtf.file import FileAllowed

class LoginForm(FlaskForm):
    username = StringField('Username', validators=[DataRequired()])
    password = StringField('Password', validators=[DataRequired()])
    submit = SubmitField('Login')

class UploadForm(FlaskForm):
    name = StringField('Dish Name', validators=[DataRequired(), Length(2, 100)])
    description = TextAreaField('Description', validators=[DataRequired(), Length(5, 500)])
    price = FloatField('Price (USD)', validators=[DataRequired(), NumberRange(min=0.01, message='Price must be > 0')])
    image = FileField('Dish Image', validators=[DataRequired(), FileAllowed(['jpg','jpeg','png','gif','webp'], 'Images only!')])
    category = SelectField('Category', coerce=int, validators=[DataRequired()])
    submit = SubmitField('Upload Dish')

class ReviewForm(FlaskForm):
    action = SelectField('Action', choices=[('approve','Approve'),('reject','Reject')], validators=[DataRequired()])
    comment = TextAreaField('Comment', validators=[Optional()])
    submit = SubmitField('Submit Review')
