def dashboard():
    if current_user.role == 'chef':
        return render_template('chef.html', uploads=Upload.query.filter_by(uploaded_by=current_user.id, status='pending').all())
    elif current_user.role == 'manager':
        return render_template('manager.html', uploads=Upload.query.filter_by(reviewed_by=None).all())
    else:
        return render_template('customer.html', categories=Category.query.all())

@app.route('/upload', methods=['GET', 'POST'])
@login_required
def upload():
    if current_user.role != 'chef':
        flash('Only chefs can upload dishes.', 'danger')
        return redirect(url_for('dashboard'))
    form = UploadForm()
    categories = Category.query.all()
    if request.method == 'POST' and form.validate_on_submit():
        file = request.files.get('image')
        if not file:
            flash('Please select an image.', 'danger')
            return render_template('upload.html', form=form, categories=categories)
        filename = save_image(file, secrets.token_hex(8))
        if not filename:
            flash('Invalid image format.', 'danger')
            return render_template('upload.html', form=form, categories=categories)

        dish = Dish(
            name=form.name.data,
            description=form.description.data,
            price=form.price.data,
            image_url=f'/static/images/dishes/{filename}',
            category_id=form.category.data,
            uploaded_by=current_user.id,
            status='pending'
        )
        db.session.add(dish)
        db.session.commit()

        upload = Upload(
            dish_id=dish.id,
            uploaded_by=current_user.id,
            reviewed_by=None,
            status='pending'
        )
        db.session.add(upload)
        db.session.commit()

        flash(f'Dish "{form.name.data}" uploaded successfully. Awaiting manager review.', 'success')
        return redirect(url_for('dashboard'))
    return render_template('upload.html', form=form, categories=categories)

@app.route('/review/<int:upload_id>', methods=['GET', 'POST'])
@login_required
def review(upload_id):
    if current_user.role != 'manager':
        flash('Only managers can review dishes.', 'danger')
        return redirect(url_for('dashboard'))
    upload = Upload.query.get_or_404(upload_id)
    dish = Dish.query.get_or_404(upload.dish_id)
    form = ReviewForm()
    if request.method == 'POST' and form.validate_on_submit():
        if form.action.data == 'approve':
            upload.status = 'approved'
            upload.reviewed_by = current_user.id
            upload.reviewed_at = datetime.utcnow()
            dish.status = 'approved'
            flash(f'Dish "{dish.name}" approved successfully.', 'success')
        else:
            upload.status = 'rejected'
            upload.reviewed_by = current_user.id
            upload.reviewed_at = datetime.utcnow()
            upload.review_comment = form.comment.data or 'No comment provided.'
            dish.status = 'rejected'
            flash(f'Dish "{dish.name}" rejected.', 'warning')
        db.session.commit()
        return redirect(url_for('dashboard'))
    return render_template('review.html', upload=upload, dish=dish, form=form)

