    elif action == 'reject':
        upload.status = 'rejected'
        upload.reviewed_by = current_user.id
        upload.reviewed_at = datetime.utcnow()
        upload.review_comment = comment
        db.session.commit()
        return jsonify({'status': 'rejected'})
    else:
        return jsonify({'error': 'Invalid action'}), 400

