## ⚙️ `app.js`

```javascript
// ---------- State ----------
const state = {
  clips: [],
  transitions: [],
  fps: 30,
  previewW: 800,
  previewH: 450,
  previewCtx: null,
  previewImg: null,
  previewInterval: null,
  previewTime: 0,
  clipWidth: 0,
  clipHeight: 0,
  clipColor: null,
};

// ---------- Colors ----------
const COLORS = [
  '#ff5f56', '#ffc95c', '#28c840', '#3b5bdb', '#5bc0eb',
  '#a18cd1', '#ff9f43', '#ff6b9d', '#fdcb6e', '#84fab0',
];

// ---------- Utilities ----------
function randColor() {
  return COLORS[Math.floor(Math.random() * COLORS.length)];
}

function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }

function uid() { return 'c_' + Math.random().toString(36).slice(2, 9); }

function rgbString(r, g, b) {
  const c = [r, g, b].map(v => Math.round(v)).map(v => v < 16 ? '0' + v.toString(16) : v.toString(16)).join('');
  return '#' + c;
}

// ---------- Clip Management ----------
function addClip() {
  const color = randColor();
  const clip = {
    id: uid(),
    color: color,
    name: 'Clip ' + (state.clips.length + 1),
    duration: 3,
    startTime: state.clips.length === 0 ? 0 : state.clips[state.clips.length - 1].endTime,
    endTime: state.clips[state.clips.length - 1].endTime + 3,
    transition: null,
    transitionDuration: 0.5,
  };
  state.clips.push(clip);
  renderTimeline();
  renderPreview();
}

function removeClip(id) {
  state.clips = state.clips.filter(c => c.id !== id);
  state.transitions = state.transitions.filter(t => t.clipId !== id);
  renderTimeline();
  renderPreview();
}

function updateClip(id, prop, value) {
  const c = state.clips.find(x => x.id === id);
  if (!c) return;
  c[prop] = value;
  renderTimeline();
  renderPreview();
}

function updateTransition(id, prop, value) {
  const t = state.transitions.find(x => x.id === id);
  if (!t) return;
  t[prop] = value;
  renderTimeline();
  renderPreview();
}

// ---------- Timeline Rendering ----------
function renderTimeline() {
  const timeline = document.getElementById('timeline');
  const ruler = document.createElement('div');
  ruler.className = 'timeline-ruler';
  ruler.style.height = state.clipHeight + 'px';

  const tickCount = 40;
  const tickStep = state.clipWidth / tickCount;
  for (let i = 0; i <= tickCount; i++) {
    const tick = document.createElement('div');
    tick.className = 'tick';
    tick.style.left = (i * tickStep) + 'px';
    if (i % 5 === 0) {
      const label = document.createElement('div');
      label.className = 'label';
      label.textContent = (i * 0.05).toFixed(1) + 's';
      tick.appendChild(label);
    }
    ruler.appendChild(tick);
  }
  timeline.appendChild(ruler);

  const track = document.createElement('div');
  track.className = 'timeline-track';
  track.style.height = (state.previewH - 20) + 'px';

  state.clips.forEach((clip, idx) => {
    const clipEl = document.createElement('div');
    clipEl.className = 'clip-timeline';
    clipEl.dataset.clipId = clip.id;
    clipEl.style.left = (idx * state.clipWidth) + 'px';
    clipEl.style.width = state.clipWidth + 'px';

    // Clip bar
    const bar = document.createElement('div');
    bar.className = 'clip-bar';
    bar.style.left = '0';
    bar.style.width = '0%';
    clipEl.appendChild(bar);

    // Clip label
    const label = document.createElement('div');
    label.className = 'clip-label';
    label.textContent = clip.name + ' · ' + clip.duration.toFixed(1) + 's';
    clipEl.appendChild(label);

    // Clip handle
    const handle = document.createElement('div');
    handle.className = 'clip-handle';
    handle.style.left = '0';
    clipEl.appendChild(handle);

    // Transition bar (if any)
    if (clip.transition) {
      const tBar = document.createElement('div');
      tBar.className = 'clip-bar';
      tBar.style.background = 'linear-gradient(90deg, #ff9f43, #ff6b9d)';
      tBar.style.left = '0';
      tBar.style.width = '0%';
      clipEl.appendChild(tBar);
    }

    track.appendChild(clipEl);
  });

  timeline.appendChild(track);

  // Update clip widths
  const first = state.clips[0];
  if (first) {
    const firstEl = timeline.querySelector('.clip-timeline[data-clip-id="' + first.id + '"]');
    if (firstEl) {
      state.clipWidth = firstEl.offsetWidth;
      state.clipHeight = firstEl.offsetHeight - firstEl.querySelector('.clip-bar').offsetHeight - 16;
    }
  }

  // Set scroll
  const maxScroll = state.clips.length * state.clipWidth - timeline.clientWidth;
  timeline.scrollLeft = maxScroll;
}

// ---------- Preview Rendering ----------
function renderPreview() {
  const canvas = document.getElementById('preview');
  const ctx = canvas.getContext('2d');
  state.previewCtx = ctx;
  state.previewW = canvas.width;
  state.previewH = canvas.height;
  state.previewImg = document.createElement('img');

  const totalDuration = state.clips.reduce((sum, c) => sum + c.duration, 0);
  const frameDuration = 1 / state.fps;
  const frames = Math.max(1, Math.round(totalDuration * state.fps));
  const frameIndex = Math.round(state.previewTime / frameDuration);

  ctx.clearRect(0, 0, state.previewW, state.previewH);

  // Background
  ctx.fillStyle = '#000';
  ctx.fillRect(0, 0, state.previewW, state.previewH);

  // Draw frame
  const frameTime = frameIndex * frameDuration;
  const frameInfo = getFrameInfo(frameTime);
  if (frameInfo) {
    const { clip, t, tStart, tEnd, transitionStart, transitionEnd } = frameInfo;

    // Clip background
    ctx.fillStyle = rgbString(...hexToRgb(clip.color));
    ctx.fillRect(0, 0, state.previewW, state.previewH);

    // Transition overlay
    if (transitionStart < transitionEnd) {
      const transitionColor = hexToRgb(clip.color);
      const transitionAlpha = Math.max(0, Math.min(1, (frameTime - transitionStart) / transitionEnd));
      ctx.fillStyle = `rgba(${transitionColor[0]}, ${transitionColor[1]}, ${transitionColor[2]}, ${transitionAlpha})`;
      ctx.fillRect(0, 0, state.previewW, state.previewH);
    }

    // Clip rectangle
    const clipX = (clip.startTime / totalDuration) * state.previewW;
    const clipY = (clip.endTime / totalDuration) * state.previewH;
    ctx.fillStyle = rgbString(...hexToRgb(clip.color));
    ctx.fillRect(clipX, 0, state.previewW - clipX, clipY);

    // Clip label
    ctx.fillStyle = '#fff';
    ctx.font = '14px -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif';
    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    ctx.fillText(clip.name, 10, 10);
  }

  // FPS label
  ctx.fillStyle = '#8a93a6';
  ctx.font = '11px -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif';
  ctx.fillText('FPS: ' + state.fps + ' · ' + totalDuration.toFixed(1) + 's', state.previewW - 110, 14);

  // Update info
  document.getElementById('preview-info').textContent =
    'Frame ' + frameIndex + ' / ' + frames + ' · ' + frameTime.toFixed(2) + 's';

  // Draw preview image
  const img = state.previewImg;
  img.onload = () => {
    ctx.drawImage(img, 0, 0, state.previewW, state.previewH);
  };
  img.src = canvas.toDataURL('image/png');
}

function getFrameInfo(frameTime) {
  // Find which clip contains this frame
  let clip = null;
  for (const c of state.clips) {
    if (frameTime >= c.startTime && frameTime <= c.endTime) {
      clip = c;
      break;
    }
  }
  if (!clip) return null;

  const t = frameTime - clip.startTime;
  const tStart = clip.transition ? clip.transition.startTime : 0;
  const tEnd = clip.transition ? clip.transition.endTime : clip.duration;
  const transitionStart = clip.transition ? clip.transition.transitionStart : 0;
  const transitionEnd = clip.transition ? clip.transition.transitionEnd : 0;

  return { clip, t, tStart, tEnd, transitionStart, transitionEnd };
}

function hexToRgb(hex) {
  const h = hex.replace('#', '');
  return [
    parseInt(h.substring(0, 2), 16),
    parseInt(h.substring(2, 4), 16),
    parseInt(h.substring(4, 6), 16),
  ];
}

// ---------- Transition Logic ----------
function addTransition(clipId) {
  const clip = state.clips.find(c => c.id === clipId);
  if (!clip) return;
  const t = {
    id: uid(),
    clipId,
    type: 'fade',
    duration: 0.5,
    startTime: 0,
    endTime: clip.duration,
    transitionStart: 0,
    transitionEnd: clip.duration,
  };
  state.transitions.push(t);
  renderTimeline();
  renderPreview();
}

function removeTransition(id) {
  state.transitions = state.transitions.filter(t => t.id !== id);
  renderTimeline();
  renderPreview();
}

function setTransitionType(id, type) {
  const t = state.transitions.find(x => x.id === id);
  if (!t) return;
  t.type = type;
  renderTimeline();
  renderPreview();
}

// ---------- Preview Loop ----------
function startPreviewLoop() {
  if (state.previewInterval) clearInterval(state.previewInterval);
  state.previewInterval = setInterval(() => {
    state.previewTime += 1 / state.fps;
    renderPreview();
  }, 1000 / state.fps);
}

function stopPreviewLoop() {
  if (state.previewInterval) clearInterval(state.previewInterval);
  state.previewInterval = null;
}

// ---------- Render / Export ----------
function renderAllFrames() {
  const totalDuration = state.clips.reduce((sum, c) => sum + c.duration, 0);
  const frames = Math.max(1, Math.round(totalDuration * state.fps));
  const frameDuration = 1 / state.fps;

  const canvas = document.getElementById('preview');
  const ctx = canvas.getContext('2d');
  ctx.clearRect(0, 0, state.previewW, state.previewH);

  const dataUrl = canvas.toDataURL('image/png');
  const base64 = dataUrl.replace(/^data:image\/png;base64,/, '');

  return new Promise(resolve => {
    const tempCanvas = document.createElement('canvas');
    tempCanvas.width = state.previewW;
    tempCanvas.height = state.previewH;
    const tctx = tempCanvas.getContext('2d');
    tctx.fillStyle = '#000';
    tctx.fillRect(0, 0, state.previewW, state.previewH);

    const framesArr = [];
    for (let i = 0; i < frames; i++) {
      const frameTime = i * frameDuration;
      const frameInfo = getFrameInfo(frameTime);
      if (frameInfo) {
        const { clip, t, tStart, tEnd, transitionStart, transitionEnd } = frameInfo;

        // Clip background
        tctx.fillStyle = rgbString(...hexToRgb(clip.color));
        tctx.fillRect(0, 0, state.previewW, state.previewH);

        // Transition overlay
        if (transitionStart < transitionEnd) {
          const transitionColor = hexToRgb(clip.color);
          const transitionAlpha = Math.max(0, Math.min(1, (frameTime - transitionStart) / transitionEnd));
          tctx.fillStyle = `rgba(${transitionColor[0]}, ${transitionColor[1]}, ${transitionColor[2]}, ${transitionAlpha})`;
          tctx.fillRect(0, 0, state.previewW, state.previewH);
        }

        // Clip rectangle
        const clipX = (clip.startTime / totalDuration) * state.previewW;
        const clipY = (clip.endTime / totalDuration) * state.previewH;
        tctx.fillStyle = rgbString(...hexToRgb(clip.color));
        tctx.fillRect(clipX, 0, state.previewW - clipX, clipY);
      }

      // FPS label
      tctx.fillStyle = '#8a93a6';
      tctx.font = '11px -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif';
      tctx.fillText('FPS: ' + state.fps + ' · ' + (i * frameDuration).toFixed(2) + 's', state.previewW - 110, 14);

      framesArr.push(tctx.getImageData(0, 0, state.previewW, state.previewH));
    }

    // Write frames to file
    const blob = new Blob(framesArr.map(d => d.data), { type: 'image/png' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'transitions_' + Date.now() + '.png';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);

    resolve();
  });
}

function exportVideo() {
  const totalDuration = state.clips.reduce((sum, c) => sum + c.duration, 0);
  const frames = Math.max(1, Math.round(totalDuration * state.fps));
  const frameDuration = 1 / state.fps;

  const canvas = document.getElementById('preview');
  const ctx = canvas.getContext('2d');

  // Render all frames to a temporary canvas
  const tempCanvas = document.createElement('canvas');
  tempCanvas.width = state.previewW;
  tempCanvas.height = state.previewH;
  const tctx = tempCanvas.getContext('2d');
  tctx.fillStyle = '#000';
  tctx.fillRect(0, 0, state.previewW, state.previewH);

  const framesArr = [];
  for (let i = 0; i < frames; i++) {
    const frameTime = i * frameDuration;
    const frameInfo = getFrameInfo(frameTime);
    if (frameInfo) {
      const { clip, t, tStart, tEnd, transitionStart, transitionEnd } = frameInfo;

      // Clip background
      tctx.fillStyle = rgbString(...hexToRgb(clip.color));
      tctx.fillRect(0, 0, state.previewW, state.previewH);

      // Transition overlay
      if (transitionStart < transitionEnd) {
        const transitionColor = hexToRgb(clip.color);
        const transitionAlpha = Math.max(0, Math.min(1, (frameTime - transitionStart) / transitionEnd));
        tctx.fillStyle = `rgba(${transitionColor[0]}, ${transitionColor[1]}, ${transitionColor[2]}, ${transitionAlpha})`;
        tctx.fillRect(0, 0, state.previewW, state.previewH);
      }

      // Clip rectangle
      const clipX = (clip.startTime / totalDuration) * state.previewW;
      const clipY = (clip.endTime / totalDuration) * state.previewH;
      tctx.fillStyle = rgbString(...hexToRgb(clip.color));
      tctx.fillRect(clipX, 0, state.previewW - clipX, clipY);
    }

    // FPS label
    tctx.fillStyle = '#8a93a6';
    tctx.font = '11px -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif';
    tctx.fillText('FPS: ' + state.fps + ' · ' + (i * frameDuration).toFixed(2) + 's', state.previewW - 110, 14);

    framesArr.push(tctx.getImageData(0, 0, state.previewW, state.previewH));
  }

  // Write to file via FFmpeg
  const blob = new Blob(framesArr.map(d => d.data), { type: 'image/png' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'transitions_' + Date.now() + '.png';
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

// ---------- Events ----------
document.getElementById('add-clip').addEventListener('click', addClip);
document.getElementById('render-btn').addEventListener('click', () => {
  const totalDuration = state.clips.reduce((sum, c) => sum + c.duration, 0);
  const frames = Math.max(1, Math.round(totalDuration * state.fps));
  document.getElementById('preview-info').textContent =
    'Rendering ' + frames + ' frames...';
  renderAllFrames().then(() => {
    document.getElementById('preview-info').textContent =
      'Done. Open the downloaded PNG to inspect frames.';
  });
});

document.getElementById('fps').addEventListener('input', (e) => {
  state.fps = parseInt(e.target.value, 10);
  renderPreview();
});

// Drag to reorder clips
const clipList = document.getElementById('clip-list');
clipList.addEventListener('pointerdown', (e) => {
  if (e.target.closest('.clip-item')) {
    e.preventDefault();
    const item = e.target.closest('.clip-item');
    const id = item.dataset.clipId;
    const idx = state.clips.findIndex(c => c.id === id);
    if (idx < 0) return;
    const dragged = state.clips.splice(idx, 1)[0];
    state.clips.unshift(dragged);
    renderTimeline();
    renderPreview();
  }
});

// ---------- Init ----------
document.getElementById('add-clip').click();
