## 🎬 Optional: Real MP4 Export via FFmpeg

To export a real video, you would need to pipe the canvas frames through FFmpeg. Here's a Node.js snippet you can run in a terminal:

```javascript
// ffmpeg-export.js
const { spawn } = require('child_process');
const fs = require('fs').promises;

async function exportVideo(canvas, fps, output) {
  const tempDir = './temp';
  await fs.mkdir(tempDir, { recursive: true });
  const frames = [];

  const totalDuration = state.clips.reduce((s, c) => s + c.duration, 0);
  const frameCount = Math.round(totalDuration * fps);

  for (let i = 0; i < frameCount; i++) {
    const frameTime = i / fps;
    const frameInfo = getFrameInfo(frameTime);
    if (!frameInfo) continue;

    const { clip, t, tStart, tEnd, transitionStart, transitionEnd } = frameInfo;

    const tempCanvas = document.createElement('canvas');
    tempCanvas.width = canvas.width;
    tempCanvas.height = canvas.height;
    const tctx = tempCanvas.getContext('2d');
    tctx.fillStyle = '#000';
    tctx.fillRect(0, 0, canvas.width, canvas.height);

    // Clip background
    tctx.fillStyle = rgbString(...hexToRgb(clip.color));
    tctx.fillRect(0, 0, canvas.width, canvas.height);

    // Transition overlay
    if (transitionStart < transitionEnd) {
      const transitionColor = hexToRgb(clip.color);
      const transitionAlpha = Math.max(0, Math.min(1, (frameTime - transitionStart) / transitionEnd));
      tctx.fillStyle = `rgba(${transitionColor[0]}, ${transitionColor[1]}, ${transitionColor[2]}, ${transitionAlpha})`;
      tctx.fillRect(0, 0, canvas.width, canvas.height);
    }

    // Clip rectangle
    const clipX = (clip.startTime / totalDuration) * canvas.width;
    const clipY = (clip.endTime / totalDuration) * canvas.height;
    tctx.fillStyle = rgbString(...hexToRgb(clip.color));
    tctx.fillRect(clipX, 0, canvas.width - clipX, clipY);

    // FPS label
    tctx.fillStyle = '#8a93a6';
    tctx.font = '11px -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif';
    tctx.fillText('FPS: ' + fps + ' · ' + (i / fps).toFixed(2) + 's', canvas.width - 110, 14);

    frames.push(tempCanvas.toDataURL('image/png').replace(/^data:image\/png;base64,/, ''));
  }

  // Write frames
  const frameFiles = frames.map((data, i) => {
    const f = `${tempDir}/frame_${i.toString().padStart(5, '0')}.png`;
    fs.writeFile(f, data, 'base64');
    return f;
  });

  // FFmpeg command
  const cmd = [
    'ffmpeg',
    '-y',
    '-framerate', fps.toString(),
    '-i', `${tempDir}/frame_%05d.png`,
    '-c:v', 'libx264',
    '-pix_fmt', 'yuv420p',
    output,
  ];

  const proc = spawn('ffmpeg', cmd);

  proc.on('error', (err) => console.error('FFmpeg error:', err));
  proc.on('close', (code) => {
    console.log('FFmpeg exit code:', code);
    frameFiles.forEach(f => fs.unlink(f).catch(() => {}));
    fs.rmdir(tempDir, { recursive: true }).catch(() => {});
  });

  return new Promise((resolve, reject) => {
    proc.on('error', reject);
    proc.on('close', (code) => {
      if (code === 0) resolve();
      else reject(new Error('FFmpeg failed'));
    });
  });
}
```

