## 🧠 main.js

```javascript
(() => {
  'use strict';

  const state = {
    videoUrl: '',
    videoDuration: 0,
    subtitles: [],
    currentFont: 'Arial, sans-serif',
    fontSize: 32,
    color: '#ffffff',
    bgOpacity: 60,
    position: 'bottom',
    align: 'center',
    uploadedFile: null,
  };

  const $ = (id) => document.getElementById(id);

  // ---------- UI refs ----------
  const uploadBtn = $('uploadBtn');
  const fileInput = $('fileInput');
  const videoEl = $('videoEl');
  const videoContainer = $('videoContainer');
  const videoOverlay = $('videoOverlay');
  const timeline = $('timeline');
  const subtitleList = $('subtitleList');
  const addSubtitleBtn = $('addSubtitleBtn');
  const exportBtn = $('exportBtn');
  const statusText = $('statusText');
  const fontSelect = $('fontSelect');
  const fontSizeInput = $('fontSize');
  const colorInput = $('colorInput');
  const bgOpacityInput = $('bgOpacity');
  const bgOpacityVal = $('bgOpacityVal');
  const positionSelect = $('positionSelect');
  const alignSelect = $('alignSelect');

  // ---------- Fonts ----------
  const fonts = ['Arial', 'Helvetica', 'Georgia', 'Courier New', 'Times New Roman', 'Verdana', 'Impact', 'Tahoma', 'Roboto', 'Segoe UI'];
  fonts.forEach(f => {
    const opt = document.createElement('option');
    opt.value = f;
    opt.textContent = f;
    fontSelect.appendChild(opt);
  });

  // ---------- Upload ----------
  uploadBtn.addEventListener('click', () => fileInput.click());
  fileInput.addEventListener('change', (e) => {
    const file = e.target.files[0];
    if (!file) return;
    state.uploadedFile = file;
    loadVideo(file);
  });

  async function loadVideo(file) {
    const url = URL.createObjectURL(file);
    videoEl.src = url;
    state.videoUrl = url;
    videoEl.load();
    videoOverlay.classList.remove('hidden');
    videoOverlay.textContent = 'Preparing…';
    await new Promise(r => videoEl.addEventListener('loadedmetadata', r, { once: true }));
    videoOverlay.textContent = 'Ready';
    state.videoDuration = videoEl.duration;
    renderTimeline();
    updateSubtitleList();
    exportBtn.disabled = false;
    statusText.textContent = `Loaded: ${file.name} (${formatTime(state.videoDuration)})`;
  }

  // ---------- Timeline ----------
  function renderTimeline() {
    timeline.innerHTML = '';
    if (state.subtitles.length === 0) {
      const empty = document.createElement('div');
      empty.className = 'timeline-track';
      empty.textContent = 'No subtitles yet. Add one to see it here.';
      empty.style.cursor = 'default';
      empty.style.justifyContent = 'center';
      empty.style.gridTemplateColumns = '1fr';
      empty.style.gap = '0';
      timeline.appendChild(empty);
      return;
    }
    state.subtitles.forEach((s, i) => {
      const track = document.createElement('div');
      track.className = 'timeline-track';
      track.dataset.index = i;
      const start = formatTime(s.start);
      const end = formatTime(s.end);
      const dur = formatTime(s.end - s.start);
      track.innerHTML = `
        <span class="time">${start} → ${end}</span>
        <span class="dur">${dur}</span>
        <span class="text">${s.text}</span>
      `;
      track.addEventListener('click', () => {
        const idx = parseInt(track.dataset.index, 10);
        const s2 = state.subtitles[idx];
        if (!s2) return;
        const t = s2.start + (s2.end - s2.start) / 2;
        videoEl.currentTime = t;
        videoEl.play().catch(() => {});
      });
      timeline.appendChild(track);
    });
  }

  // ---------- Subtitles ----------
  function addSubtitle() {
    const s = {
      id: Date.now() + '-' + Math.random().toString(36).slice(2, 7),
      start: 0,
      end: state.videoDuration || 5,
      text: 'New caption',
      font: state.currentFont,
      size: state.fontSize,
      color: state.color,
      bgOpacity: state.bgOpacity,
      position: state.position,
      align: state.align,
    };
    state.subtitles.push(s);
    renderTimeline();
    updateSubtitleList();
    statusText.textContent = `Added caption · ${state.subtitles.length} total`;
  }

  addSubtitleBtn.addEventListener('click', addSubtitle);

  function deleteSubtitle(id) {
    state.subtitles = state.subtitles.filter(s => s.id !== id);
    renderTimeline();
    updateSubtitleList();
    statusText.textContent = `Deleted caption · ${state.subtitles.length} total`;
  }

  function updateSubtitleList() {
    subtitleList.innerHTML = '';
    if (state.subtitles.length === 0) {
      const empty = document.createElement('div');
      empty.textContent = 'No captions yet. Click "+ Add Caption" to begin.';
      empty.style.padding = '24px';
      empty.style.color = '#888';
      subtitleList.appendChild(empty);
      return;
    }
    state.subtitles.forEach((s, i) => {
      const item = document.createElement('div');
      item.className = 'subtitle-item';
      item.innerHTML = `
        <div class="info">
          <div class="title">${escapeHtml(s.text)}</div>
          <div class="meta">${formatTime(s.start)} – ${formatTime(s.end)}</div>
        </div>
        <div class="actions">
          <button data-act="edit" data-i="${i}">✎</button>
          <button data-act="del" data-i="${i}">✕</button>
        </div>
      `;
      item.addEventListener('click', (e) => {
        if (e.target.closest('[data-act]')) return;
        videoEl.currentTime = s.start;
        videoEl.play().catch(() => {});
      });
      item.querySelector('[data-act="del"]').addEventListener('click', (e) => {
        e.stopPropagation();
        deleteSubtitle(s.id);
      });
      item.querySelector('[data-act="edit"]').addEventListener('click', (e) => {
        e.stopPropagation();
        openEditDialog(s, i);
      });
      subtitleList.appendChild(item);
    });
  }

  function openEditDialog(s, i) {
    const dialog = document.createElement('div');
    dialog.className = 'dialog';
    dialog.innerHTML = `
      <div class="dialog-header">Edit Caption</div>
      <div class="dialog-body">
        <label>Text<input type="text" id="edText" value="${escapeHtml(s.text)}" /></label>
        <label>Start<input type="time" id="edStart" value="${formatTimeCode(s.start)}" /></label>
        <label>End<input type="time" id="edEnd" value="${formatTimeCode(s.end)}" /></label>
        <div class="dialog-actions">
          <button id="edCancel">Cancel</button>
          <button id="edSave">Save</button>
        </div>
      </div>
    `;
    document.body.appendChild(dialog);
    const text = dialog.querySelector('#edText');
    const start = dialog.querySelector('#edStart');
    const end = dialog.querySelector('#edEnd');
    const cancel = dialog.querySelector('#edCancel');
    const save = dialog.querySelector('#edSave');
    cancel.addEventListener('click', () => dialog.remove());
    save.addEventListener('click', () => {
      s.text = text.value.trim() || 'Untitled';
      s.start = parseTimeCode(start.value);
      s.end = parseTimeCode(end.value);
      renderTimeline();
      updateSubtitleList();
      dialog.remove();
      statusText.textContent = `Edited caption · ${state.subtitles.length} total`;
    });
    // Focus
    requestAnimationFrame(() => text.focus());
  }

  function formatTimeCode(t) {
    if (!t) return '00:00:00.000';
    const h = Math.floor(t / 3600);
    const m = Math.floor((t % 3600) / 60);
    const s = Math.floor(t % 60);
    const ms = Math.floor((t - Math.floor(t)) * 1000);
    return `${pad(h)}:${pad(m)}:${pad(s)}.${pad(ms, 3)}`;
  }
  function parseTimeCode(s) {
    const [h, m, sec] = s.split(':').map(Number);
    const [s2, ms] = sec.split('.');
    const total = (h * 3600 + m * 60 + s2) + (ms ? ms / 1000 : 0);
    return total;
  }
  function pad(n, w = 2) { return String(n).padStart(w, '0'); }
  function formatTime(sec) {
    if (!isFinite(sec)) return '0:00';
    const h = Math.floor(sec / 3600);
    const m = Math.floor((sec % 3600) / 60);
    const s = Math.floor(sec % 60);
    const ms = Math.floor((sec - Math.floor(sec)) * 1000);
    return `${pad(h)}:${pad(m)}:${pad(s)}.${pad(ms, 3)}`;
  }
  function formatTimeShort(sec) {
    if (!isFinite(sec)) return '0:00';
    const m = Math.floor(sec / 60);
    const s = Math.floor(sec % 60);
    const ms = Math.floor((sec - Math.floor(sec)) * 1000);
    return `${pad(m)}:${pad(s)}.${pad(ms, 3)}`;
  }

  // ---------- Style sync ----------
  fontSizeInput.addEventListener('input', (e) => {
    state.fontSize = parseInt(e.target.value, 10);
    state.subtitles.forEach(s => { if (s.size === 32) s.size = state.fontSize; });
    renderTimeline();
    updateSubtitleList();
  });
  colorInput.addEventListener('input', (e) => {
    state.color = e.target.value;
    state.subtitles.forEach(s => { if (s.color === '#ffffff') s.color = state.color; });
    renderTimeline();
    updateSubtitleList();
  });
  bgOpacityInput.addEventListener('input', (e) => {
    state.bgOpacity = parseInt(e.target.value, 10);
    state.subtitles.forEach(s => { if (s.bgOpacity === 60) s.bgOpacity = state.bgOpacity; });
    bgOpacityVal.textContent = `${e.target.value}%`;
    renderTimeline();
    updateSubtitleList();
  });
  positionSelect.addEventListener('change', (e) => {
    state.position = e.target.value;
    state.subtitles.forEach(s => { if (s.position === 'bottom') s.position = state.position; });
    renderTimeline();
    updateSubtitleList();
  });
  alignSelect.addEventListener('change', (e) => {
    state.align = e.target.value;
    state.subtitles.forEach(s => { if (s.align === 'center') s.align = state.position; });
    renderTimeline();
    updateSubtitleList();
  });

  // ---------- Export ----------
  exportBtn.addEventListener('click', async () => {
    if (!state.videoUrl || state.subtitles.length === 0) {
      statusText.textContent = 'No video or subtitles to export';
      return;
    }
    statusText.textContent = 'Generating subtitles file…';
    const ass = await generateASS();
    statusText.textContent = 'Embedding subtitles into video…';
    const output = await embedASS(state.videoUrl, ass);
    statusText.textContent = 'Export complete. Download your video.';
    const a = document.createElement('a');
    a.href = output;
    a.download = `subtitle-${Date.now()}.mp4`;
    document.body.appendChild(a);
    a.click();
    a.remove();
  });

  async function generateASS() {
    const subs = state.subtitles.map(s => {
      const pos = s.position === 'bottom' ? 'Bottom' : s.position === 'top' ? 'Top' : 'Center';
      const align = s.align === 'center' ? 'Center' : s.align === 'left' ? 'Left' : 'Right';
      const color = s.color;
      const bg = s.bgOpacity > 0 ? `Alpha=${s.bgOpacity},` : '';
      return `[${pos}]${align},${bg}Color=${color}`;
    }).join('\n');
    return `[Script Info]
ScriptType: v4.00
Collisions: Normal
PlayResX: 1920
PlayResY: 1080

[V4+ Styles]
Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV

[Events]
Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text
${subs}
`;
  }

  // ---------- FFmpeg worker ----------
  const worker = new Worker('worker.js');

  worker.onmessage = (e) => {
    if (e.data.type === 'progress') {
      statusText.textContent = `Processing… ${e.data.msg}`;
    } else if (e.data.type === 'done') {
      statusText.textContent = 'Export complete. Download your video.';
      setTimeout(() => {
        const a = document.createElement('a');
        a.href = e.data.output;
        a.download = `subtitle-${Date.now()}.mp4`;
        document.body.appendChild(a);
        a.click();
        a.remove();
      }, 500);
    } else if (e.data.type === 'error') {
      statusText.textContent = `Error: ${e.data.msg}`;
    }
  };

  async function embedASS(videoUrl, ass) {
    return new Promise((resolve, reject) => {
      worker.postMessage({
        cmd: 'ffmpeg',
        args: [
          '-y',
          '-i', videoUrl,
          '-vf', `ass="${encodeURIComponent(ass)}"`,
          '-c:v', 'copy',
          '-c:a', 'copy',
          'output.mp4',
        ],
      });
      worker.onmessage = (e) => {
        if (e.data.type === 'done') {
          resolve(e.data.output);
        } else if (e.data.type === 'error') {
          reject(e.data.msg);
        }
      };
    });
  }

  // ---------- Helpers ----------
  function escapeHtml(s) {
    return String(s).replace(/[&<>"']/g, c => ({
      '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
    }[c]));
  }

  // ---------- Keyboard shortcuts ----------
  document.addEventListener('keydown', (e) => {
    if (e.target.tagName === 'INPUT' || e.target.tagName === 'SELECT') return;
    if (e.key === 'Enter') addSubtitle();
    if (e.key === 'Delete' || e.key === 'Backspace') {
      if (state.subtitles.length > 0) deleteSubtitle(state.subtitles[state.subtitles.length - 1].id);
    }
  });

})();
```

