## ⚙️ worker.js

```javascript
// Node.js worker: spawn FFmpeg via child_process
const { spawn } = require('child_process');
const path = require('path');
const fs = require('fs').promises;

const ffmpegPath = require('ffmpeg-static');

const worker = self;

worker.onmessage = async (e) => {
  const { cmd, args } = e.data;
  if (cmd !== 'ffmpeg') {
    worker.postMessage({ type: 'error', msg: 'Unknown command' });
    return;
  }

  const ffmpeg = ffmpegPath;
  const proc = spawn(ffmpeg, args, {
    cwd: process.cwd(),
    shell: true,
    env: process.env,
  });

  let output = '';
  proc.stdout.on('data', (chunk) => { output += chunk.toString(); });
  proc.stderr.on('data', (chunk) => {
    output += chunk.toString();
    // Emit progress lines
    const lines = chunk.toString().split('\n');
    lines.forEach(l => {
      if (l.includes('frame=')) {
        worker.postMessage({ type: 'progress', msg: l });
      }
    });
  });
  proc.on('close', (code) => {
    if (code !== 0) {
      worker.postMessage({ type: 'error', msg: `FFmpeg exited with code ${code}: ${output}` });
    } else {
      worker.postMessage({ type: 'done', output: path.join(process.cwd(), 'output.mp4') });
    }
  });
};
```

