## 🏗️ server.js

```javascript
const express = require('express');
const multer = require('multer');
const path = require('path');
const fs = require('fs').promises;
const ffmpegPath = require('ffmpeg-static');
const { spawn } = require('child_process');

const app = express();
const port = 3000;

// Serve static files
app.use(express.static('public'));

// Multer for uploads
const upload = multer({ dest: 'uploads/' });

app.use(express.json());

// ---------- Upload ----------
app.post('/api/upload', upload.single('file'), async (req, res) => {
  if (!req.file) return res.status(400).json({ error: 'No file' });
  const { originalname, path: tmpPath } = req.file;
  const ext = path.extname(originalname);
  const newFileName = `video-${Date.now()}${ext}`;
  await fs.rename(tmpPath, path.join('uploads', newFileName));
  res.json({ url: `/uploads/${newFileName}` });
});

// ---------- Generate ASS ----------
app.post('/api/ass', async (req, res) => {
  const { subs } = req.body;
  const out = path.join('temp', 'subtitles.ass');
  await fs.writeFile(out, subs);
  res.json({ path: out });
});

// ---------- Embed ----------
app.post('/api/embed', async (req, res) => {
  const { videoUrl, assPath } = req.body;
  const ffmpeg = ffmpegPath;
  const out = path.join('output', 'final.mp4');
  const proc = spawn(ffmpeg, [
    '-y', '-i', videoUrl, '-i', assPath,
    '-vf', `ass="${assPath}"`,
    '-c:v', 'copy', '-c:a', 'copy', '-c:s', 'mov_text',
    out,
  ], { cwd: process.cwd() });

  proc.on('close', (code) => {
    if (code !== 0) {
      res.status(500).json({ error: `FFmpeg exited with code ${code}` });
    } else {
      res.json({ path: out });
    }
  });
});

// ---------- Serve uploaded files ----------
app.use('/uploads', express.static('uploads'));
app.use('/output', express.static('output'));

app.get('/', (req, res) => res.sendFile(path.join(__dirname, 'public', 'index.html')));

app.listen(port, () => {
  console.log(`Server running at http://localhost:${port}`);
});
```

