### 3. `components/WaveformCanvas.tsx`

```tsx
import React, { useRef, useEffect, useState } from 'react';

interface WaveformProps {
  audioBuffer?: AudioBuffer;
  labels?: Label[];
  selectedRange?: { start: number; end: number };
  onRangeChange?: (range: { start: number; end: number } | null) => void;
  onLabelClick?: (id: string) => void;
  onLabelDelete?: (id: string) => void;
  width?: number;
  height?: number;
}

const WaveformCanvas: React.FC<WaveformProps> = ({
  audioBuffer,
  labels = [],
  selectedRange,
  onRangeChange,
  onLabelClick,
  onLabelDelete,
  width = 600,
  height = 120,
}) => {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const [samples, setSamples] = useState<number[]>([]);
  const [canvasWidth, setCanvasWidth] = useState(0);
  const [canvasHeight, setCanvasHeight] = useState(0);
  const [isDrawingRange, setIsDrawingRange] = useState(false);
  const [rangeStart, setRangeStart] = useState<number | null>(null);
  const [hoverX, setHoverX] = useState<number | null>(null);

  useEffect(() => {
    if (!audioBuffer) return;
    const ctx = audioBuffer.getChannelData(0);
    const sampleRate = audioBuffer.sampleRate;
    const duration = audioBuffer.duration;
    const numSamples = ctx.length;
    const samplesPerSecond = sampleRate;
    const sampleStep = Math.max(1, Math.round(numSamples / Math.max(1, duration)));

    const arr: number[] = [];
    for (let i = 0; i < numSamples; i += sampleStep) {
      const v = Math.abs(ctx[i]);
      arr.push(v);
    }
    setSamples(arr);
  }, [audioBuffer]);

  useEffect(() => {
    const c = canvasRef.current;
    if (!c) return;
    const dpr = window.devicePixelRatio || 1;
    const rect = c.getBoundingClientRect();
    c.width = rect.width * dpr;
    c.height = rect.height * dpr;
    setCanvasWidth(rect.width);
    setCanvasHeight(rect.height);
  }, []);

  const draw = () => {
    if (!canvasRef.current || !samples.length || !audioBuffer) return;
    const c = canvasRef.current;
    const ctx = c.getContext('2d');
    if (!ctx) return;

    const rect = c.getBoundingClientRect();
    const W = rect.width;
    const H = rect.height;

    // background
    ctx.fillStyle = '#0f172a';
    ctx.fillRect(0, 0, W, H);

    const duration = audioBuffer.duration;
    const sampleRate = audioBuffer.sampleRate;
    const numSamples = samples.length;
    const secondsPerSample = duration / numSamples;

    const scaleX = W / duration;
    const scaleY = H / 2;

    // grid lines
    ctx.strokeStyle = 'rgba(148, 163, 184, 0.15)';
    ctx.lineWidth = 1;
    for (let i = 0; i <= 5; i++) {
      const x = (i * duration) / 5 * scaleX;
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, H);
      ctx.stroke();
    }

    // waveform
    ctx.strokeStyle = '#334155';
    ctx.lineWidth = 1;
    ctx.beginPath();
    samples.forEach((v, i) => {
      const t = i * secondsPerSample;
      const x = t * scaleX;
      const y = H / 2 - v * scaleY;
      if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // labels
    labels.forEach((label) => {
      const x = label.start * scaleX;
      const w = (label.end - label.start) * scaleX;
      const top = 4;
      const left = x;
      const right = x + w;
      const midY = H / 2;

      // background
      ctx.fillStyle = '#1e293b';
      ctx.fillRect(left, top, w, H - top * 2);

      // label text
      ctx.fillStyle = '#e2e8f0';
      ctx.font = '11px ui-monospace, "SF Mono", Menlo, monospace';
      ctx.textAlign = 'left';
      ctx.textBaseline = 'middle';
      ctx.fillText(label.name, left + 6, midY);

      // delete button
      const btnX = right - 18;
      ctx.fillStyle = '#334155';
      ctx.fillRect(btnX, top + 4, 14, H - top * 2 - 8);
      ctx.fillStyle = '#f8fafc';
      ctx.font = '10px ui-monospace, "SF Mono", Menlo, monospace';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText('×', btnX + 7, midY);

      // hover highlight
      if (hoverX !== null && hoverX >= left && hoverX <= right) {
        ctx.strokeStyle = 'rgba(220, 50, 50, 0.5)';
        ctx.lineWidth = 1;
        ctx.strokeRect(left, top, w, H - top * 2);
      }
    });

    // selection range
    if (selectedRange) {
      const { start, end } = selectedRange;
      const sx = start * scaleX;
      const ex = end * scaleX;
      const top = H - 8;
      const bottom = H - 4;
      ctx.fillStyle = 'rgba(16, 185, 129, 0.25)';
      ctx.fillRect(sx, top, ex - sx, bottom - top);
      ctx.strokeStyle = '#10b981';
      ctx.lineWidth = 1;
      ctx.strokeRect(sx, top, ex - sx, bottom - top);
    }
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    const rect = canvasRef.current?.getBoundingClientRect();
    if (!rect) return;
    const x = e.clientX - rect.left;
    const time = x / canvasWidth * duration;
    setRangeStart(time);
    setIsDrawingRange(true);
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    const rect = canvasRef.current?.getBoundingClientRect();
    if (!rect) return;
    const x = e.clientX - rect.left;
    setHoverX(x);
  };

  const handleMouseUp = () => {
    if (!isDrawingRange) return;
    const rect = canvasRef.current?.getBoundingClientRect();
    if (!rect || rangeStart === null) {
      setIsDrawingRange(false);
      setRangeStart(null);
      return;
    }
    const x = rect.width - (e.clientX - rect.left);
    const end = x / canvasWidth * duration;
    const start = rangeStart;
    if (start >= end) return;
    onRangeChange?.({ start, end });
    setIsDrawingRange(false);
    setRangeStart(null);
  };

  const handleLabelClick = (id: string) => {
    onLabelClick?.(id);
  };

  const handleLabelDelete = (id: string) => {
    onLabelDelete?.(id);
  };

  return (
    <div className="relative">
      <canvas
        ref={canvasRef}
        width={width}
        height={height}
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={() => setHoverX(null)}
        style={{ width, height, display: 'block' }}
      />
      {hoverX !== null && (
        <div
          className="absolute top-2 left-2 bg-gray-800 text-white text-xs px-2 py-1 rounded"
          style={{ transform: 'translateY(-100%)' }}
        >
          {Math.round(hoverX / canvasWidth * duration)}s
        </div>
      )}
    </div>
  );
};
```

