### 7. `App.tsx`

```tsx
import React, { useState, useRef, useCallback, useEffect } from 'react';
import { useAudio } from './hooks/useAudio';
import WaveformCanvas from './components/WaveformCanvas';
import LabelList from './components/LabelList';
import LabelEditor from './components/LabelEditor';
import Toolbar from './components/Toolbar';
import { Label, AudioMeta } from './types';

const App: React.FC = () => {
  const { audioRef, isPlaying, currentTime, duration, error, play, pause, seek, load } = useAudio();
  const [audioFile, setAudioFile] = useState<File | null>(null);
  const [audioBuffer, setAudioBuffer] = useState<AudioBuffer | null>(null);
  const [labels, setLabels] = useState<Label[]>([]);
  const [selectedRange, setSelectedRange] = useState<{ start: number; end: number } | null>(null);
  const [editingLabel, setEditingLabel] = useState<Label | null>(null);
  const [importedLabels, setImportedLabels] = useState<Label[]>([]);
  const [importError, setImportError] = useState<string | null>(null);

  const audioCtxRef = useRef<AudioContext | null>(null);

  // Auto-load audio when file changes
  useEffect(() => {
    if (audioFile) {
      load(audioFile);
    }
  }, [audioFile, load]);

  // Auto-update buffer when audio metadata is ready
  useEffect(() => {
    if (audioRef.current && audioRef.current.src && audioRef.current.readyState >= 2) {
      const ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
      audioCtxRef.current = ctx;
      const src = ctx.createMediaElementSource(audioRef.current);
      src.connect(ctx.destination);
      audioRef.current.playbackRate.value = 1;
      audioRef.current.play().catch(() => {});
    }
  }, [audioRef]);

  const handleRangeChange = useCallback((range: { start: number; end: number } | null) => {
    setSelectedRange(range);
  }, []);

  const handleLabelClick = useCallback((id: string) => {
    const label = labels.find((l) => l.id === id);
    if (!label) return;
    setEditingLabel(label);
    seek(label.start);
    play();
  }, [labels, seek, play]);

  const handleLabelDelete = useCallback((id: string) => {
    setLabels((prev) => prev.filter((l) => l.id !== id));
    if (editingLabel && editingLabel.id === id) setEditingLabel(null);
  }, [editingLabel]);

  const handleLabelSave = useCallback((label: Label) => {
    setLabels((prev) => {
      const existing = prev.find((l) => l.id === label.id);
      if (existing) {
        return prev.map((l) => (l.id === label.id ? { ...label } : l));
      }
      return [...prev, label];
    });
    setEditingLabel(null);
  }, []);

  const handleLabelCancel = useCallback(() => {
    setEditingLabel(null);
  }, []);

  const addLabel = useCallback(() => {
    if (!selectedRange || labels.some((l) => l.start === selectedRange.start && l.end === selectedRange.end)) return;
    const id = 'lbl_' + Math.random().toString(36).slice(2, 10);
    setLabels((prev) => [...prev, { id, start: selectedRange.start, end: selectedRange.end, name: `Segment ${prev.length + 1}`, notes: '' }]);
    setEditingLabel(null);
    setSelectedRange(null);
  }, [selectedRange, labels]);

  const clearAll = useCallback(() => {
    if (labels.length === 0) return;
    setLabels([]);
    setEditingLabel(null);
    setSelectedRange(null);
  }, [labels]);

  const handleFileChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setAudioFile(file);
      setLabels([]);
      setEditingLabel(null);
      setSelectedRange(null);
    }
  }, []);

  const handleImport = useCallback(() => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = '.json';
    input.onchange = (ev) => {
      const file = (ev.target as HTMLInputElement).files?.[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = (e) => {
        try {
          const data = JSON.parse(e.target?.result as string);
          if (!Array.isArray(data.labels)) {
            throw new Error('Invalid JSON: missing "labels" array.');
          }
          const imported = data.labels.map((item: any, i) => ({
            id: 'im_' + i,
            start: parseFloat(item.start || 0),
            end: parseFloat(item.end || 0),
            name: item.name || `Imported ${i + 1}`,
            notes: item.notes || '',
          }));
          setLabels((prev) => [...prev, ...imported]);
          setImportError(null);
        } catch (err) {
          setImportError(err instanceof Error ? err.message : 'Failed to parse JSON.');
        }
      };
      reader.readAsText(file);
    };
    input.click();
  }, []);

  const handleExport = useCallback(() => {
    const data = {
      file: audioFile?.name || 'audio',
      labels: labels.map((l) => ({
        start: l.start,
        end: l.end,
        name: l.name,
        notes: l.notes,
      })),
    };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = (audioFile?.name || 'audio') + '.json';
    a.click();
    URL.revokeObjectURL(url);
  }, [audioFile, labels]);

  // Auto-play when labels exist
  useEffect(() => {
    if (labels.length > 0 && currentTime < labels[0].start) {
      play();
    }
  }, [labels, currentTime, play]);

  // Auto-pause when labels end
  useEffect(() => {
    if (labels.length > 0 && currentTime >= labels[labels.length - 1].end) {
      pause();
    }
  }, [labels, currentTime, pause]);

  return (
    <div className="min-h-screen bg-gray-900 text-white">
      <div className="container mx-auto px-4 py-8">
        <h1 className="text-3xl font-bold mb-6">Audio Segmentation Labeler</h1>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2">
            <div className="bg-gray-800 rounded-lg border border-gray-700 p-4">
              <div className="flex items-center justify-between mb-4">
                <div className="text-sm text-gray-400">
                  {audioFile ? audioFile.name : 'No audio loaded'}
                </div>
                <div className="text-sm text-gray-400">
                  {duration.toFixed(2)}s
                </div>
              </div>
              <div className="mb-4">
                <div className="flex justify-between text-xs text-gray-400 mb-2">
                  <span>0.00s</span>
                  <span>{duration.toFixed(2)}s</span>
                </div>
                <div className="h-40 rounded bg-gray-700">
                  <WaveformCanvas
                    audioBuffer={audioBuffer}
                    labels={labels}
                    selectedRange={selectedRange}
                    onRangeChange={handleRangeChange}
                    onLabelClick={handleLabelClick}
                    onLabelDelete={handleLabelDelete}
                  />
                </div>
              </div>
              <div className="flex gap-2">
                <button
                  onClick={play}
                  disabled={isPlaying}
                  className="bg-blue-600 hover:bg-blue-700 disabled:bg-gray-600 disabled:cursor-not-allowed text-white px-4 py-2 rounded"
                >
                  {isPlaying ? '⏸ Pause' : '▶ Play'}
                </button>
                <button
                  onClick={pause}
                  disabled={!isPlaying}
                  className="bg-gray-600 hover:bg-gray-700 disabled:bg-gray-600 disabled:cursor-not-allowed text-white px-4 py-2 rounded"
                >
                  Pause
                </button>
              </div>
            </div>
          </div>

          <div className="space-y-4">
            <div className="bg-gray-800 rounded-lg border border-gray-700 p-4">
              <h2 className="text-sm text-gray-400 uppercase font-semibold mb-3">Labels</h2>
              <LabelList labels={labels} onLabelClick={handleLabelClick} onLabelDelete={handleLabelDelete} />
            </div>
            <div className="bg-gray-800 rounded-lg border border-gray-700 p-4">
              <h2 className="text-sm text-gray-400 uppercase font-semibold mb-3">Controls</h2>
              <Toolbar
                audioFile={audioFile}
                labels={labels}
                onAddLabel={addLabel}
                onImport={handleImport}
                onExport={handleExport}
                onClear={clearAll}
              />
            </div>
          </div>
        </div>

        <div className="mt-6 text-sm text-gray-400">
          Tip: Drag on the waveform to select a range, then click "+ Add Label" to create a label.
        </div>

        {editingLabel && (
          <div className="fixed inset-0 flex items-center justify-center z-50 bg-black bg-opacity-50">
            <LabelEditor label={editingLabel} onSave={handleLabelSave} onCancel={handleLabelCancel} />
          </div>
        )}

        {importError && (
          <div className="fixed bottom-4 left-1/2 transform -translate-x-1/2 bg-red-800 text-white p-3 rounded text-sm z-50">
            {importError}
          </div>
        )}
      </div>
    </div>
  );
};

export default App;
```

