  top: 0; left: 0; right: 0; bottom: 0;
  pointer-events: none;
}
.clip {
  position: absolute;
  top: 0; bottom: 0;
  cursor: grab;
  user-select: none;
  pointer-events: auto;
  transition: transform 0.15s ease;
  z-index: 2;
}
.clip:hover { filter: brightness(0.95); }
.clip.dragging { opacity: 0.4; }
.clip .clip-thumb {
  position: absolute;
  top: 8px; left: 8px; right: 8px; bottom: 8px;
  background: linear-gradient(135deg, #6366f1, #8b5cf6);
  color: white;
  font-size: 11px;
  font-weight: 700;
  display: grid; place-items: center;
  border-radius: 6px;
  overflow: hidden;
  text-align: center;
  line-height: 1;
}
.clip .clip-thumb svg { width: 14px; height: 14px; }
.clip .clip-meta {
  position: absolute;
  bottom: 8px; left: 8px;
  background: rgba(0,0,0,0.75);
  color: #fff;
  padding: 3px 8px;
  border-radius: 4px;
  font-size: 10px;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  pointer-events: none;
}
.clip .clip-handle {
  position: absolute;
  top: 50%; left: 0; right: 0;
  height: 10px;
  background: rgba(0,0,0,0.5);
  cursor: ew-resize;
  pointer-events: auto;
  z-index: 3;
}
.clip .clip-handle:hover { background: rgba(0,0,0,0.8); }
.clip .clip-handle::before {
  content: '';
  position: absolute;
  top: 50%; left: 50%;
  width: 8px; height: 8px;
  background: #fff;
  border-radius: 50%;
  transform: translate(-50%, -50%);
  pointer-events: none;
}

.playhead {
  position: absolute;
  top: 0; bottom: 0;
  width: 3px;
  background: #ef4444;
  z-index: 4;
  pointer-events: none;
}
.playhead::after {
  content: '';
  position: absolute;
  top: 50%; left: -4px;
  width: 8px; height: 8px;
  background: #ef4444;
  border-radius: 50%;
  transform: translateY(-50%);
  box-shadow: 0 0 0 0 rgba(239,68,68,0.5);
  animation: pulse 1.2s infinite;
}
@keyframes pulse {
  0% { box-shadow: 0 0 0 0 rgba(239,68,68,0.5); }
  70% { box-shadow: 0 0 0 8px rgba(239,68,68,0); }
  100% { box-shadow: 0 0 0 0 rgba(239,68,68,0); }
}

.preview-wrap {
  flex: 1;
  overflow: hidden;
  background: #0f172a;
  display: flex;
  flex-direction: column;
  min-height: 0;
}
.preview-label {
  padding: 8px 16px;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #94a3b8;
  background: rgba(255,255,255,0.05);
  border-bottom: 1px solid rgba(255,255,255,0.06);
}
.preview {
  flex: 1;
  position: relative;
  background: #0b1220;
  overflow: hidden;
  display: grid;
  place-items: center;
}
.preview canvas, .preview video {
  width: 100%; height: 100%;
  display: block;
  max-height: 100%;
  max-width: 100%;
}
.preview-empty {
  display: flex; flex-direction: column; align-items: center; gap: 12px;
  color: #94a3b8;
  padding: 24px;
}
.preview-empty svg { opacity: 0.5; }
.preview-empty p { margin: 0; font-size: 13px; }

/* Scrollbars */
::-webkit-scrollbar { width: 10px; height: 10px; }
::-webkit-scrollbar-track { background: #f3f4f6; }
::-webkit-scrollbar-thumb { background: #d1d5db; border-radius: 5px; }
::-webkit-scrollbar-thumb:hover { background: #9ca3af; }

/* Responsive */
@media (max-width: 900px) {
  .workspace { grid-template-columns: 1fr; }
  .panel-left { display: none; }
}
@media (max-width: 500px) {
  .app-header { padding: 10px 12px; }
  .brand h1 { font-size: 14px; }
  .tagline { display: none; }
  .btn span { display: none; }
  .btn { padding: 8px 10px; }
}
