          <input type="range" id="thickness" min="1" max="20" value="3" />
        </label>
      </div>

      <div class="tool-group">
        <label class="swatch" title="Text size">
          <input type="range" id="textSize" min="12" max="60" value="28" />
        </label>
        <label class="swatch" title="Text align">
          <select id="textAlign">
            <option value="left">Left</option>
            <option value="center">Center</option>
            <option value="right">Right</option>
          </select>
        </label>
      </div>
    </aside>

    <main class="editor">
      <div id="stage" class="stage" tabindex="0" aria-label="Screenshot editor">
        <canvas id="canvas"></canvas>
        <div id="preview" class="preview"></div>
      </div>
      <div id="tooltip" class="tooltip" hidden></div>
    </main>
  </div>

  <footer class="status">
    <span id="statusText">Ready</span>
    <span class="sep">•</span>
    <span id="statusMeta">0 edits</span>
  </footer>
</div>

<script src="app.js"></script>
