## ⚙️ `app.js`

```javascript
(() => {
  'use strict';

  // ---------- State ----------
  const state = {
    mode: 'area',
    tool: 'select',
    color: '#000000',
    opacity: 1,
    thickness: 3,
    textSize: 28,
    textAlign: 'left',
    history: [],
    redoStack: [],
    current: [],
    editing: false,
    startX: 0, startY: 0,
    isDrawing: false,
    startX2: 0, startY2: 0,
    currentPath: [],
    previewText: 'Click to capture',
  };

  // ---------- DOM ----------
  const canvas = document.getElementById('canvas');
  const ctx = canvas.getContext('2d');
  const stage = document.getElementById('stage');
  const preview = document.getElementById('preview');
  const tooltip = document.getElementById('tooltip');
  const statusText = document.getElementById('statusText');
  const statusMeta = document.getElementById('statusMeta');

  const colorPicker = document.getElementById('colorPicker');
  const opacityInput = document.getElementById('opacity');
  const thicknessInput = document.getElementById('thickness');
  const textSizeInput = document.getElementById('textSize');
  const textAlignSelect = document.getElementById('textAlign');

  const undoBtn = document.getElementById('undoBtn');
  const redoBtn = document.getElementById('redoBtn');
  const saveBtn = document.getElementById('saveBtn');

  const modeBtns = document.querySelectorAll('.mode-btn');
  const toolBtns = document.querySelectorAll('.tool');

  // ---------- Canvas sizing ----------
  function resizeCanvas() {
    const rect = stage.getBoundingClientRect();
    canvas.width = rect.width * devicePixelRatio;
    canvas.height = rect.height * devicePixelRatio;
    ctx.setTransform(devicePixelRatio, 0, 0, devicePixelRatio, 0, 0);
    ctx.fillStyle = '#1f2937';
    ctx.fillRect(0, 0, rect.width, rect.height);
  }

  let lastRect = null;
  function updatePreview() {
    if (!lastRect) return;
    const { x, y, w, h } = lastRect;
    preview.style.left = `${x}px`;
    preview.style.top = `${y}px`;
    preview.style.width = `${w}px`;
    preview.style.height = `${h}px`;
    preview.textContent = state.previewText;
  }

  // ---------- Mode ----------
  function setMode(m) {
    state.mode = m;
    modeBtns.forEach(b => {
      const active = b.dataset.mode === m;
      b.classList.toggle('active', active);
      b.setAttribute('aria-selected', active);
    });
    if (m === 'area') {
      lastRect = null;
      updatePreview();
    }
  }

  // ---------- Tool ----------
  function setTool(t) {
    state.tool = t;
    toolBtns.forEach(b => b.classList.toggle('active', b.dataset.tool === t));
    if (t === 'select') {
      state.editing = false;
      state.currentPath = [];
    }
  }

  // ---------- Drawing ----------
  function drawRect(x, y, w, h) {
    ctx.save();
    ctx.globalAlpha = state.opacity;
    ctx.strokeStyle = state.color;
    ctx.lineWidth = state.thickness;
    ctx.setLineDash([]);
    ctx.strokeRect(x, y, w, h);
    ctx.restore();
  }

  function drawArrow(x1, y1, x2, y2) {
    ctx.save();
    ctx.globalAlpha = state.opacity;
    ctx.strokeStyle = state.color;
    ctx.lineWidth = state.thickness;
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.stroke();
    const dx = x2 - x1, dy = y2 - y1;
    const len = Math.hypot(dx, dy) || 1;
    const ax = (dx / len) * 12, ay = (dy / len) * 12;
    const x3 = x2 - ay, y3 = y2 + ax;
    const x4 = x2 + ay, y4 = y2 - ax;
    ctx.beginPath();
    ctx.moveTo(x2, y2);
    ctx.lineTo(x3, y3);
    ctx.lineTo(x4, y4);
    ctx.closePath();
    ctx.fillStyle = state.color;
    ctx.fill('evenodd');
    ctx.restore();
  }

  function drawLine(x1, y1, x2, y2) {
    ctx.save();
    ctx.globalAlpha = state.opacity;
    ctx.strokeStyle = state.color;
    ctx.lineWidth = state.thickness;
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.stroke();
    ctx.restore();
  }

  function drawFree(x1, y1, x2, y2) {
    ctx.save();
    ctx.globalAlpha = state.opacity;
    ctx.strokeStyle = state.color;
    ctx.lineWidth = state.thickness;
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.stroke();
    ctx.restore();
  }

  function drawText(x, y, text) {
    ctx.save();
    ctx.globalAlpha = state.opacity;
    ctx.fillStyle = state.color;
    ctx.font = `600 ${state.textSize}px -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif`;
    ctx.textAlign = state.textAlign;
    ctx.textBaseline = 'middle';
    ctx.fillText(text, x, y);
    ctx.restore();
  }

  function drawSelectionRect(x1, y1, x2, y2) {
    ctx.save();
    ctx.globalAlpha = 0.25;
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 2;
    ctx.setLineDash([6, 4]);
    ctx.strokeRect(x1, y1, x2 - x1, y2 - y1);
    ctx.restore();
  }

  function updateSelectionRect(x, y) {
    const r = lastRect;
    if (!r) return;
    const w = Math.abs(x - r.x);
    const h = Math.abs(y - r.y);
    const x2 = Math.min(r.x, x);
    const y2 = Math.min(r.y, y);
    lastRect = { x: x2, y: y2, w, h };
    updatePreview();
  }

  // ---------- Capture ----------
  async function captureArea(x, y, w, h) {
    const { width, height } = stage.getBoundingClientRect();
    const offscreen = document.createElement('canvas');
    offscreen.width = w;
    offscreen.height = h;
    const octx = offscreen.getContext('2d');
    octx.fillStyle = '#1f2937';
    octx.fillRect(0, 0, w, h);
    octx.drawImage(canvas, x, y, w, h, 0, 0, w, h);
    return offscreen;
  }

  async function captureWindow() {
    const rect = stage.getBoundingClientRect();
    return await captureArea(0, 0, rect.width, rect.height);
  }

  async function capturePage() {
    const html = document.documentElement;
    const scrollX = window.scrollX || 0;
    const scrollY = window.scrollY || 0;
    const w = html.scrollWidth;
    const h = html.scrollHeight;
    const offscreen = document.createElement('canvas');
    offscreen.width = w;
    offscreen.height = h;
    const octx = offscreen.getContext('2d');
    octx.fillStyle = '#1f2937';
    octx.fillRect(0, 0, w, h);
    octx.save();
    octx.translate(scrollX, scrollY);
    octx.scale(1, -1);
    octx.translate(0, -h);
    html.scrollIntoView(false);
    const clone = html.cloneNode(true);
    clone.querySelectorAll('*').forEach(el => {
      if (el.style.position === 'fixed') {
        el.style.position = 'absolute';
        el.style.top = '0';
        el.style.left = '0';
      }
      if (el.style.width === '100%') el.style.width = 'auto';
      if (el.style.height === '100%') el.style.height = 'auto';
    });
    octx.drawImage(clone, 0, 0, w, h);
    octx.restore();
    return offscreen;
  }

  // ---------- History ----------
  function snapshot() {
    return {
      mode: state.mode,
      tool: state.tool,
      color: state.color,
      opacity: state.opacity,
      thickness: state.thickness,
      textSize: state.textSize,
      textAlign: state.textAlign,
      current: state.current.slice(),
    };
  }

  function restore(s) {
    state.mode = s.mode;
    state.tool = s.tool;
    state.color = s.color;
    state.opacity = s.opacity;
    state.thickness = s.thickness;
    state.textSize = s.textSize;
    state.textAlign = s.textAlign;
    state.current = s.current;
    state.editing = false;
    state.currentPath = [];
  }

  function pushHistory() {
    state.history.push(snapshot());
    if (state.history.length > 100) state.history.shift();
    if (state.redoStack.length) state.redoStack = [];
    renderStatus();
  }

  function undo() {
    if (state.history.length <= 1) return;
    state.redoStack.push(snapshot());
    const prev = state.history.pop();
    restore(prev);
    renderStatus();
  }

  function redo() {
    if (state.redoStack.length <= 0) return;
    state.history.push(snapshot());
    const next = state.redoStack.pop();
    restore(next);
    renderStatus();
  }

  function renderStatus() {
    statusMeta.textContent = `${state.history.length} edits`;
    undoBtn.disabled = state.history.length <= 1;
    redoBtn.disabled = state.redoStack.length <= 0;
  }

  // ---------- Canvas events ----------
  function getPoint(e) {
    const rect = canvas.getBoundingClientRect();
    const p = canvas.getPoint(e.clientX - rect.left, e.clientY - rect.top);
    return p;
  }

  function getPointFromEvent(e) {
    if (e.touches && e.touches.length) {
      return getPoint(e.touches[0]);
    }
    return getPoint(e);
  }

  function setTooltip(x, y, text) {
    tooltip.textContent = text;
    tooltip.hidden = false;
    const rect = stage.getBoundingClientRect();
    const tw = tooltip.offsetWidth;
    const th = tooltip.offsetHeight;
    const left = Math.max(8, Math.min(rect.width - tw - 8, x - tw / 2));
    const top = Math.max(8, Math.min(rect.height - th - 8, y - th / 2));
    tooltip.style.left = `${left}px`;
    tooltip.style.top = `${top}px`;
  }

  function hideTooltip() {
    tooltip.hidden = true;
  }

  function clearSelection() {
    lastRect = null;
    updatePreview();
    hideTooltip();
  }

  function startSelection(x, y) {
    lastRect = { x, y, w: 0, h: 0 };
    updatePreview();
    setTooltip(x, y, 'Drag to select area');
    state.editing = true;
  }

  function endSelection(x, y) {
    if (!lastRect) return;
    const w = Math.abs(x - lastRect.x);
    const h = Math.abs(y - lastRect.y);
    if (w < 3 || h < 3) { clearSelection(); return; }
    state.current.push({ type: 'rect', x: Math.min(lastRect.x, x), y: Math.min(lastRect.y, y), w, h, color: state.color, opacity: state.opacity, thickness: state.thickness });
    clearSelection();
    pushHistory();
  }

  function startDraw(x, y) {
    state.isDrawing = true;
    state.startX = x; state.startY = y;
    state.startX2 = x; state.startY2 = y;
    state.currentPath = [];
  }

  function endDraw(x, y) {
    if (!state.isDrawing) return;
    state.isDrawing = false;
    const tool = state.tool;
    const x1 = state.startX, y1 = state.startY;
    const x2 = x, y2 = y;
    if (tool === 'rect') {
      const w = Math.abs(x2 - x1), h = Math.abs(y2 - y1);
      const x3 = Math.min(x1, x2), y3 = Math.min(y1, y2);
      state.current.push({ type: 'rect', x: x3, y: y3, w, h, color: state.color, opacity: state.opacity, thickness: state.thickness });
    } else if (tool === 'arrow') {
      state.current.push({ type: 'arrow', x1, y1, x2, y2, color: state.color, opacity: state.opacity, thickness: state.thickness });
    } else if (tool === 'line') {
      state.current.push({ type: 'line', x1, y1, x2, y2, color: state.color, opacity: state.opacity, thickness: state.thickness });
    } else if (tool === 'free') {
      state.current.push({ type: 'free', x1, y1, x2, y2, color: state.color, opacity: state.opacity, thickness: state.thickness });
    } else if (tool === 'text') {
      state.current.push({ type: 'text', x: x1, y: y1, text: state.previewText, color: state.color, opacity: state.opacity, thickness: state.textSize, textAlign: state.textAlign });
    }
    pushHistory();
  }

  function moveDraw(x, y) {
    if (!state.isDrawing) return;
    state.startX2 = x; state.startY2 = y;
    if (state.tool === 'free') {
      state.currentPath.push({ x, y });
      drawFree(state.currentPath[0].x, state.currentPath[0].y, x, y);
    } else {
      drawSelectionRect(state.startX, state.startY, x, y);
    }
  }

  function cancelDraw() {
    if (!state.isDrawing) return;
    state.isDrawing = false;
    state.startX = 0; state.startY = 0;
    state.startX2 = 0; state.startY2 = 0;
    state.currentPath = [];
    drawSelectionRect(state.startX, state.startY, state.startX2, state.startY2);
  }

  function clearAll() {
    state.current = [];
    pushHistory();
  }

  function updateCanvas() {
    ctx.fillStyle = '#1f2937';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    state.current.forEach(item => {
      if (item.type === 'rect') drawRect(item.x, item.y, item.w, item.h);
      else if (item.type === 'arrow') drawArrow(item.x1, item.y1, item.x2, item.y2);
      else if (item.type === 'line') drawLine(item.x1, item.y1, item.x2, item.y2);
      else if (item.type === 'free') drawFree(item.x1, item.y1, item.x2, item.y2);
      else if (item.type === 'text') drawText(item.x, item.y, item.text);
    });
  }

  // ---------- Bindings ----------
  stage.addEventListener('mousedown', (e) => {
    const p = getPointFromEvent(e);
    if (state.mode === 'area') {
      if (state.editing) {
        endSelection(p.x, p.y);
      } else {
        startSelection(p.x, p.y);
      }
    } else {
      if (state.tool === 'select') {
        startSelection(p.x, p.y);
      } else {
        startDraw(p.x, p.y);
      }
    }
  });

  stage.addEventListener('mousemove', (e) => {
    const p = getPointFromEvent(e);
    if (state.mode === 'area') {
      if (state.editing) {
        updateSelectionRect(p.x, p.y);
      } else if (state.tool === 'select') {
        updateSelectionRect(p.x, p.y);
      } else {
        moveDraw(p.x, p.y);
      }
    } else {
      if (state.tool === 'select') {
        updateSelectionRect(p.x, p.y);
      } else {
        moveDraw(p.x, p.y);
      }
    }
  });

  stage.addEventListener('mouseup', (e) => {
    const p = getPointFromEvent(e);
    if (state.mode === 'area') {
      if (state.editing) {
        endSelection(p.x, p.y);
      } else {
        endSelection(p.x, p.y);
      }
    } else {
      endDraw(p.x, p.y);
    }
  });

  stage.addEventListener('mouseleave', () => {
    if (state.isDrawing) cancelDraw();
  });

  stage.addEventListener('click', (e) => {
    if (state.mode === 'area') {
      if (state.editing) {
        endSelection(e.clientX, e.clientY);
      } else {
        endSelection(e.clientX, e.clientY);
      }
    } else {
      if (state.tool === 'select') {
        endSelection(e.clientX, e.clientY);
      } else {
        endDraw(e.clientX, e.clientY);
      }
    }
  });

  stage.addEventListener('dblclick', (e) => {
    if (state.mode === 'area') {
      if (state.editing) {
        endSelection(e.clientX, e.clientY);
      } else {
        endSelection(e.clientX, e.clientY);
      }
    } else {
      if (state.tool === 'select') {
        endSelection(e.clientX, e.clientY);
      } else {
        endDraw(e.clientX, e.clientY);
      }
    }
  });

  // Touch support
  stage.addEventListener('touchstart', (e) => {
    e.preventDefault();
    const t = e.touches[0];
    const p = getPoint(t);
    if (state.mode === 'area') {
      if (state.editing) {
        endSelection(p.x, p.y);
      } else {
        startSelection(p.x, p.y);
      }
    } else {
      if (state.tool === 'select') {
        startSelection(p.x, p.y);
      } else {
        startDraw(p.x, p.y);
      }
    }
  }, { passive: false });

  stage.addEventListener('touchmove', (e) => {
    e.preventDefault();
    const t = e.touches[0];
    const p = getPoint(t);
    if (state.mode === 'area') {
      if (state.editing) {
        updateSelectionRect(p.x, p.y);
      } else {
        moveDraw(p.x, p.y);
      }
    } else {
      if (state.tool === 'select') {
        updateSelectionRect(p.x, p.y);
      } else {
        moveDraw(p.x, p.y);
      }
    }
  }, { passive: false });

  stage.addEventListener('touchend', () => {
    if (state.isDrawing) cancelDraw();
  });

  // Keyboard
  window.addEventListener('keydown', (e) => {
    if (e.target.tagName === 'INPUT' || e.target.tagName === 'SELECT') return;
    if (e.key === 'Escape') {
      clearSelection();
      cancelDraw();
    } else if (e.key === 'Delete' || e.key === 'Backspace') {
      clearAll();
    } else if ((e.ctrlKey || e.metaKey) && e.key === 'z') {
      e.preventDefault();
      undo();
    } else if ((e.ctrlKey || e.metaKey) && (e.key === 'y' || (e.shiftKey && e.key === 'Z'))) {
      e.preventDefault();
      redo();
    } else if (e.key === ' ' && !e.shiftKey) {
      e.preventDefault();
      const next = state.mode === 'area' ? 'window' : state.mode === 'window' ? 'page' : 'area';
      setMode(next);
    }
  });

  // Mode buttons
  modeBtns.forEach(b => {
    b.addEventListener('click', () => setMode(b.dataset.mode));
  });

  // Tool buttons
  toolBtns.forEach(b => {
    b.addEventListener('click', () => setTool(b.dataset.tool));
  });

  // Color
  colorPicker.addEventListener('input', (e) => {
    state.color = e.target.value;
    pushHistory();
  });

  // Opacity
  opacityInput.addEventListener('input', (e) => {
    state.opacity = e.target.value / 100;
    pushHistory();
  });

  // Thickness
  thicknessInput.addEventListener('input', (e) => {
    state.thickness = e.target.value;
    pushHistory();
  });

  // Text size
  textSizeInput.addEventListener('input', (e) => {
    state.textSize = e.target.value;
    pushHistory();
  });

  // Text align
  textAlignSelect.addEventListener('change', (e) => {
    state.textAlign = e.target.value;
    pushHistory();
  });

  // Undo/Redo
  undoBtn.addEventListener('click', undo);
  redoBtn.addEventListener('click', redo);

  // Save
  saveBtn.addEventListener('click', async () => {
    const rect = stage.getBoundingClientRect();
    const offscreen = document.createElement('canvas');
    offscreen.width = rect.width;
    offscreen.height = rect.height;
    const octx = offscreen.getContext('2d');
    octx.fillStyle = '#1f2937';
    octx.fillRect(0, 0, rect.width, rect.height);
    octx.save();
    octx.translate(rect.left, rect.top);
    octx.scale(1, -1);
    octx.translate(0, -rect.height);
    octx.drawImage(canvas, 0, 0);
    octx.restore();

    const link = document.createElement('a');
    link.download = `screenshot-${Date.now()}.png`;
    link.href = offscreen.toDataURL('image/png');
    link.click();
    statusText.textContent = 'Saved';
    setTimeout(() => { statusText.textContent = 'Ready'; }, 1500);
  });

  // Clear
  stage.addEventListener('contextmenu', (e) => {
    e.preventDefault();
    clearAll();
  });

  // ---------- Init ----------
  function init() {
    resizeCanvas();
    updateCanvas();
    setMode('area');
    setTool('select');
    renderStatus();
  }

  window.addEventListener('resize', () => {
    resizeCanvas();
    updateCanvas();
  });

  init();
})();
