from flask_sqlalchemy import SQLAlchemy
from werkzeug.security import generate_password_hash, check_password_hash
from datetime import datetime
from sqlalchemy import event

db = SQLAlchemy()

class User(db.Model):
    __tablename__ = 'users'
    id = db.Column(db.Integer, primary_key=True)
    email = db.Column(db.String(120), unique=True, nullable=False)
    password_hash = db.Column(db.String(255), nullable=False)
    role = db.Column(db.String(20), nullable=False)  # customer, agent, admin
    first_name = db.Column(db.String(50))
    last_name = db.Column(db.String(50))
    phone = db.Column(db.String(20))
    created_at = db.Column(db.DateTime, default=datetime.utcnow)

    def set_password(self, password):
        self.password_hash = generate_password_hash(password)

    def check_password(self, password):
        return check_password_hash(self.password_hash, password)

    def __repr__(self):
        return f"<User {self.email}>"

class CustomerProfile(db.Model):
    __tablename__ = 'customer_profiles'
    id = db.Column(db.Integer, primary_key=True)
    user_id = db.Column(db.Integer, db.ForeignKey('users.id'), unique=True)
    address = db.Column(db.String(200))
    date_of_birth = db.Column(db.Date)
    annual_income = db.Column(db.Float)
    emergency_contact = db.Column(db.String(100))

    def __repr__(self):
        return f"<Customer {self.user.email}>"

class InsuranceProduct(db.Model):
    __tablename__ = 'insurance_products'
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(100), nullable=False)
    description = db.Column(db.Text)
    premium_per_month = db.Column(db.Float, nullable=False)
    coverage_limit = db.Column(db.Float)
    min_age = db.Column(db.Integer)
    max_age = db.Column(db.Integer)
    created_at = db.Column(db.DateTime, default=datetime.utcnow)

    def __repr__(self):
        return f"<Product {self.name}>"

class Policy(db.Model):
    __tablename__ = 'policies'
    id = db.Column(db.Integer, primary_key=True)
    customer_id = db.Column(db.Integer, db.ForeignKey('users.id'))
    product_id = db.Column(db.Integer, db.ForeignKey('insurance_products.id'))
    start_date = db.Column(db.Date)
    end_date = db.Column(db.Date)
    status = db.Column(db.String(20), default='Active')  # Active, Expired, Cancelled
    premium_paid = db.Column(db.Float, default=0.0)
    agent_id = db.Column(db.Integer, db.ForeignKey('users.id'))

    def __repr__(self):
        return f"<Policy {self.id}>"

class Claim(db.Model):
    __tablename__ = 'claims'
    id = db.Column(db.Integer, primary_key=True)
    policy_id = db.Column(db.Integer, db.ForeignKey('policies.id'))
    customer_id = db.Column(db.Integer, db.ForeignKey('users.id'))
    description = db.Column(db.Text)
    amount = db.Column(db.Float)
    submitted_at = db.Column(db.DateTime, default=datetime.utcnow)
    status = db.Column(db.String(20), default='Submitted')  # Submitted, Under Review, Approved, Paid
    approved_at = db.Column(db.DateTime)
    paid_at = db.Column(db.DateTime)
    agent_id = db.Column(db.Integer, db.ForeignKey('users.id'))

    def __repr__(self):
        return f"<Claim {self.id}>"

# Event: auto-set approved_at/paid_at when status changes
@event.listens_for(Claim.status, 'set', propagate=True)
def set_claim_time(target, value, oldvalue, initiator):
    if value == 'Approved' and oldvalue != 'Approved':
        target.approved_at = datetime.utcnow()
    elif value == 'Paid' and oldvalue != 'Paid':
        target.paid_at = datetime.utcnow()
