from flask_wtf import FlaskForm
from wtforms import StringField, PasswordField, SubmitField, SelectField, TextAreaField, FloatField, DateField, IntegerField
from wtforms.validators import DataRequired, Email, Length, Optional

class LoginForm(FlaskForm):
    email = StringField('Email', validators=[DataRequired(), Email()])
    password = PasswordField('Password', validators=[DataRequired()])
    submit = SubmitField('Login')

class RegisterForm(FlaskForm):
    email = StringField('Email', validators=[DataRequired(), Email()])
    password = PasswordField('Password', validators=[DataRequired(), Length(min=6)])
    first_name = StringField('First Name', validators=[DataRequired()])
    last_name = StringField('Last Name', validators=[DataRequired()])
    phone = StringField('Phone', validators=[DataRequired()])
    role = SelectField('Role', choices=[('customer','Customer'), ('agent','Agent'), ('admin','Admin')], validators=[DataRequired()])
    submit = SubmitField('Register')

class CustomerProfileForm(FlaskForm):
    address = StringField('Address', validators=[DataRequired()])
    date_of_birth = DateField('Date of Birth', validators=[DataRequired()])
