    min_age = IntegerField('Min Age', validators=[DataRequired()])
    max_age = IntegerField('Max Age', validators=[DataRequired()])
    submit = SubmitField('Add Product')

class AdminClaimReviewForm(FlaskForm):
    status = SelectField('Status', choices=[('Under Review','Under Review'), ('Approved','Approved'), ('Paid','Paid')], validators=[DataRequired()])
    notes = TextAreaField('Notes')
    submit = SubmitField('Update Claim')
