// ============================================================
// Equestrian Show Jumping Game
// ============================================================
// A browser-based HTML5 Canvas game where the player guides a horse
// through an obstacle course. Jump over rails, avoid water pits,
// and reach the finish line. Each obstacle knocked down deducts points.
// ============================================================

(() => {
  'use strict';

  // ---------- Configuration ----------
  const CONFIG = {
    GRAVITY: 0.5,
    JUMP_VELOCITY: -12,
    MAX_FALL: 12,
    HORIZONTAL_SPEED: 5,
    WIN_SCORE: 100,
    MAX_OBSTACLES: 8,
    SPAWN_INTERVAL: 1500,
    SPAWN_MIN_INTERVAL: 600,
    SPAWN_MAX_INTERVAL: 2400,
    START_X: 120,
    START_Y: 320,
    FINISH_X: 800,
    FINISH_Y: 320,
    OBSTACLE_WIDTH: 60,
    OBSTACLE_HEIGHT: 20,
    OBSTACLE_GAP: 120,
    RAIL_HEIGHT: 18,
    RAIL_GAP: 100,
    WATER_HEIGHT: 14,
    WATER_GAP: 140,
    PLAYER_WIDTH: 48,
    PLAYER_HEIGHT: 64,
    PLAYER_JUMP_HEIGHT: 60,
    RAIL_POINTS: -20,
    WATER_POINTS: -15,
    FINISH_POINTS: 50,
    HIT_POINTS: -5,
    WIN_POINTS: 20,
  };

  // ---------- State ----------
  const state = {
    running: true,
    score: CONFIG.WIN_SCORE,
    obstacles: [],
    rails: [],
    waters: [],
    finish: null,
    player: null,
    keys: {},
    cameraX: 0,
    cameraSpeed: 12,
    lastSpawn: 0,
    spawnTimer: 0,
    frameCount: 0,
    jumpPhase: 0,
    jumpStart: 0,
    jumpStartY: 0,
    hitFlash: 0,
    hitFlashTimer: 0,
    hitFlashTimerMax: 15,
    finishFlash: 0,
    finishFlashTimer: 0,
    finishFlashTimerMax: 60,
    cameraFollow: true,
  };

  // ---------- Canvas setup ----------
  const canvas = document.createElement('canvas');
  canvas.width = 960;
  canvas.height = 480;
  document.body.appendChild(canvas);
  const ctx = canvas.getContext('2d');

  // ---------- Input ----------
  window.addEventListener('keydown', (e) => {
    if (e.repeat) return;
    state.keys[e.key.toLowerCase()] = true;
    if (e.key === ' ') e.preventDefault();
  });
  window.addEventListener('keyup', (e) => {
    state.keys[e.key.toLowerCase()] = false;
  });

  // ---------- Obstacle factories ----------
  function spawnObstacle() {
    const x = CONFIG.START_X + state.cameraX + state.spawnTimer;
    const type = Math.random() < 0.5 ? 'rail' : 'water';
    if (type === 'rail') {
      state.rails.push({ x, y: CONFIG.RAIL_HEIGHT, w: CONFIG.OBSTACLE_WIDTH, h: CONFIG.RAIL_HEIGHT, gap: CONFIG.RAIL_GAP, points: CONFIG.RAIL_POINTS });
    } else {
      state.waters.push({ x, y: CONFIG.WATER_HEIGHT, w: CONFIG.OBSTACLE_WIDTH, h: CONFIG.WATER_HEIGHT, gap: CONFIG.WATER_GAP, points: CONFIG.WATER_POINTS });
    }
  }

  function spawnFinish() {
    if (!state.finish) {
      state.finish = {
        x: CONFIG.FINISH_X + state.cameraX,
        y: CONFIG.FINISH_Y,
        w: 60,
        h: 60,
        points: CONFIG.FINISH_POINTS,
      };
    }
  }

  // ---------- Player ----------
  function createPlayer() {
    return {
      x: CONFIG.START_X,
      y: CONFIG.START_Y,
      vx: 0,
      vy: 0,
      w: CONFIG.PLAYER_WIDTH,
      h: CONFIG.PLAYER_HEIGHT,
      jumping: false,
      onGround: false,
      facing: 1,
      animFrame: 0,
      animTimer: 0,
      animSpeed: 8,
    };
  }

  function updatePlayer() {
    const p = state.player;

    // Horizontal movement
    if (state.keys['arrowleft'] || state.keys['a']) p.vx = -CONFIG.HORIZONTAL_SPEED;
    else if (state.keys['arrowright'] || state.keys['d']) p.vx = CONFIG.HORIZONTAL_SPEED;
    else p.vx = 0;

    // Jump
    if ((state.keys['arrowup'] || state.keys['w']) && !p.jumping && p.onGround) {
      p.vy = CONFIG.JUMP_VELOCITY;
      p.jumping = true;
      p.onGround = false;
      state.jumpStart = performance.now();
      state.jumpStartY = p.y;
    }

    // Gravity
    p.vy += CONFIG.GRAVITY;
    if (p.vy > CONFIG.MAX_FALL) p.vy = CONFIG.MAX_FALL;

    p.x += p.vx;
    p.y += p.vy;

    // Ground check
    p.onGround = false;
    if (p.y >= CONFIG.START_Y) {
      p.y = CONFIG.START_Y;
      p.vy = 0;
      p.jumping = false;
      p.onGround = true;
    }

    // Jump phase animation
    if (p.jumping) {
      state.jumpPhase = (performance.now() - state.jumpStart) / 100;
      if (state.jumpPhase > 1) state.jumpPhase = 1;
      p.y = state.jumpStartY - state.jumpPhase * CONFIG.PLAYER_JUMP_HEIGHT;
    }

    // Facing direction
    if (p.vx < 0) p.facing = -1;
    else if (p.vx > 0) p.facing = 1;

    // Animation
    p.animTimer++;
    if (p.animTimer >= p.animSpeed) {
      p.animTimer = 0;
      p.animFrame = (p.animFrame + 1) % 4;
    }

    // Camera follow
    if (state.cameraFollow) {
      state.cameraX += p.vx * state.cameraSpeed;
    }

    // Clamp camera
    if (state.cameraX < 0) state.cameraX = 0;
    if (state.cameraX > CONFIG.FINISH_X - CONFIG.START_X) state.cameraX = CONFIG.FINISH_X - CONFIG.START_X;

    // Collision with obstacles
    checkObstacleCollisions(p);
  }

  function checkObstacleCollisions(p) {
    const px = p.x - state.cameraX;
    const py = p.y;

    // Rails
    for (let i = state.rails.length - 1; i >= 0; i--) {
      const r = state.rails[i];
      if (px + p.w > r.x && px < r.x + r.w && py + p.h > r.y && py < r.y + r.h) {
        state.score += r.points;
        state.hitFlash = 1;
        state.hitFlashTimer = state.hitFlashTimerMax;
        state.rails.splice(i, 1);
      }
    }

    // Water
    for (let i = state.waters.length - 1; i >= 0; i--) {
      const w = state.waters[i];
      if (px + p.w > w.x && px < w.x + w.w && py + p.h > w.y && py < w.y + w.h) {
        state.score += w.points;
        state.hitFlash = 1;
        state.hitFlashTimer = state.hitFlashTimerMax;
        state.waters.splice(i, 1);
      }
    }

    // Finish
    if (state.finish) {
      const fx = state.finish.x - state.cameraX;
      const fy = state.finish.y;
      if (px + p.w > fx && px < fx + state.finish.w && py + p.h > fy && py < fy + state.finish.h) {
        state.score += state.finish.points;
        state.finishFlash = 1;
        state.finishFlashTimer = state.finishFlashTimerMax;
        state.running = false;
      }
    }
  }

  // ---------- Rendering ----------
  function drawBackground() {
    // Sky gradient
    const sky = ctx.createLinearGradient(0, 0, 0, CONFIG.START_Y);
    sky.addColorStop(0, '#87CEEB');
    sky.addColorStop(1, '#A8D8F0');
    ctx.fillStyle = sky;
    ctx.fillRect(0, 0, canvas.width, CONFIG.START_Y);

    // Ground
    const ground = ctx.createLinearGradient(0, CONFIG.START_Y, 0, canvas.height);
    ground.addColorStop(0, '#8B4513');
    ground.addColorStop(1, '#6B3410');
    ctx.fillStyle = ground;
    ctx.fillRect(0, CONFIG.START_Y, canvas.width, canvas.height - CONFIG.START_Y);

    // Grass stripes
    ctx.fillStyle = '#228B22';
    for (let i = 0; i < 4; i++) {
      ctx.fillRect(0, CONFIG.START_Y + i * 18, canvas.width, 6);
    }
  }

  function drawFinishLine() {
    if (!state.finish) return;
    const fx = state.finish.x - state.cameraX;
    const fy = state.finish.y;
    const fw = state.finish.w;
    const fh = state.finish.h;

    // Shadow
    ctx.fillStyle = 'rgba(0,0,0,0.3)';
    ctx.fillRect(fx + fw / 2 - 2, fy + fh + 2, fw, 4);

    // Finish flag
    ctx.fillStyle = '#F5F5F5';
    ctx.fillRect(fx + fw / 2 - 8, fy - 18, 16, 18);
    ctx.fillStyle = '#B8860B';
    ctx.fillRect(fx + fw / 2 - 8, fy - 18, 16, 4);
    ctx.fillStyle = '#000';
    ctx.fillRect(fx + fw / 2 - 4, fy - 22, 8, 10);

    // Finish line
    ctx.fillStyle = '#F5F5F5';
    ctx.fillRect(fx, fy, fw, 3);
    ctx.fillStyle = '#B8860B';
    ctx.fillRect(fx, fy, fw, 1);

    // Finish flash
    if (state.finishFlash > 0) {
      ctx.fillStyle = `rgba(255,255,0,${state.finishFlash * 0.5})`;
      ctx.fillRect(fx - 20, fy - 30, fw + 40, 40);
    }
  }

  function drawObstacles() {
    // Rails
    for (const r of state.rails) {
      const rx = r.x - state.cameraX;
      ctx.fillStyle = '#B8860B';
      ctx.fillRect(rx, r.y, r.w, r.h);
      ctx.fillStyle = '#8B4513';
      ctx.fillRect(rx + 2, r.y + 2, r.w - 4, r.h - 4);
    }

    // Water pits
    for (const w of state.waters) {
      const wx = w.x - state.cameraX;
      ctx.fillStyle = '#1E90FF';
      ctx.fillRect(wx, w.y, w.w, w.h);
      ctx.fillStyle = '#0047AB';
      ctx.fillRect(wx + 2, w.y + 2, w.w - 4, w.h - 4);
    }
  }

  function drawPlayer() {
    const p = state.player;
    const px = p.x - state.cameraX;
    const py = p.y;

    // Hitbox (debug)
    // ctx.strokeStyle = 'rgba(255,0,0,0.5)';
    // ctx.strokeRect(px, py, p.w, p.h);

    // Body
    ctx.fillStyle = '#8B4513';
    ctx.fillRect(px, py, p.w, p.h);

    // Shadow
    ctx.fillStyle = 'rgba(0,0,0,0.3)';
    ctx.fillRect(px + p.w / 2 - 2, py + p.h + 2, p.w, 4);

    // Head
    ctx.fillStyle = '#C0C0C0';
    ctx.fillRect(px + 8, py - 20, p.w - 16, 20);

    // Eyes
    ctx.fillStyle = '#000';
    ctx.fillRect(px + 14, py - 18, 4, 4);
    ctx.fillRect(px + 26, py - 18, 4, 4);

    // Mane
    ctx.fillStyle = '#A9A9A9';
    ctx.fillRect(px + 4, py - 28, 12, 14);
    ctx.fillRect(px + 20, py - 30, 12, 16);

    // Legs
    ctx.fillStyle = '#8B4513';
    ctx.fillRect(px + 2, py + 40, 8, 20);
    ctx.fillRect(px + 32, py + 40, 8, 20);
    ctx.fillRect(px + 4, py + 40, 4, 10);
    ctx.fillRect(px + 32, py + 40, 4, 10);

    // Tail
    ctx.fillStyle = '#A9A9A9';
    ctx.fillRect(px + p.w - 10, py + 30, 14, 10);

    // Jumping motion
    if (p.jumping) {
      ctx.save();
      ctx.translate(px + p.w / 2, py + p.h / 2);
      ctx.rotate(state.jumpPhase * 0.5);
      ctx.translate(-px - p.w / 2, -py - p.h / 2);
      ctx.fillStyle = 'rgba(255,255,255,0.4)';
      ctx.fillRect(px - 6, py - 6, 12, 12);
      ctx.restore();
    }

    // Hit flash
    if (state.hitFlash > 0) {
      ctx.fillStyle = `rgba(255,0,0,${state.hitFlash})`;
      ctx.fillRect(px - 2, py - 2, p.w + 4, p.h + 4);
    }
  }

  function drawUI() {
    // Score
    ctx.fillStyle = '#FFF';
    ctx.font = 'bold 28px Arial';
    ctx.fillText(`Score: ${state.score}`, 20, 40);

    // Instructions
    ctx.fillStyle = '#FFF';
    ctx.font = '14px Arial';
    ctx.fillText('Use arrow keys or WASD to move', 20, 70);
    ctx.fillText('Space to jump', 20, 90);

    // Game over / Win
    if (!state.running) {
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#FFF';
      ctx.font = 'bold 48px Arial';
      ctx.textAlign = 'center';
      ctx.fillText(state.score >= CONFIG.WIN_SCORE ? 'YOU WIN!' : 'GAME OVER', canvas.width / 2, canvas.height / 2 - 20);
      ctx.font = '20px Arial';
      ctx.fillText(`Final Score: ${state.score}`, canvas.width / 2, canvas.height / 2 + 30);
      ctx.fillText('Press Space to restart', canvas.width / 2, canvas.height / 2 + 70);
      ctx.textAlign = 'left';
    }
  }

  // ---------- Game loop ----------
  function loop() {
    state.frameCount++;

    if (state.running) {
      updatePlayer();

      // Spawn obstacles
      state.spawnTimer += 16;
      if (state.spawnTimer > CONFIG.SPAWN_MIN_INTERVAL && state.spawnTimer < CONFIG.SPAWN_MAX_INTERVAL) {
        state.lastSpawn = state.spawnTimer;
        state.spawnTimer = 0;
        spawnObstacle();
      }

      // Spawn finish line after enough obstacles
      if (!state.finish && state.rails.length + state.waters.length >= CONFIG.MAX_OBSTACLES) {
        spawnFinish();
      }

      // Camera follow
      if (state.cameraFollow) {
        state.cameraX += state.player.vx * state.cameraSpeed;
      }
      if (state.cameraX < 0) state.cameraX = 0;
      if (state.cameraX > CONFIG.FINISH_X - CONFIG.START_X) state.cameraX = CONFIG.FINISH_X - CONFIG.START_X;
    } else {
      // Idle camera
      state.cameraX += (CONFIG.FINISH_X - CONFIG.START_X - state.cameraX) * 0.05;
      if (Math.abs(CONFIG.FINISH_X - CONFIG.START_X - state.cameraX) < 0.1) {
        state.cameraX = CONFIG.FINISH_X - CONFIG.START_X;
      }
    }

    // Decay timers
    if (state.hitFlash > 0) {
      state.hitFlashTimer--;
      if (state.hitFlashTimer <= 0) state.hitFlash = 0;
    }
    if (state.finishFlash > 0) {
      state.finishFlashTimer--;
      if (state.finishFlashTimer <= 0) state.finishFlash = 0;
    }

    // Clear
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw
    drawBackground();
    drawObstacles();
    drawFinishLine();
    drawPlayer();
    drawUI();

    requestAnimationFrame(loop);
  }

  // ---------- Restart ----------
  function restart() {
    state.running = true;
    state.score = CONFIG.WIN_SCORE;
    state.obstacles = [];
    state.rails = [];
    state.waters = [];
    state.finish = null;
    state.player = createPlayer();
    state.cameraX = 0;
    state.spawnTimer = 0;
    state.lastSpawn = 0;
    state.hitFlash = 0;
    state.finishFlash = 0;
    state.cameraFollow = true;
  }

  // ---------- Start ----------
  state.player = createPlayer();
  state.cameraX = 0;
  spawnFinish();
  requestAnimationFrame(loop);
})();
```

Creating a **sandbox-style shooting game editor** involves several components:

1. **Scene Editor** — Drag-and-drop placement of entities (enemies, obstacles, props).
2. **Properties Panel** — Adjust properties per entity (health, speed, spawn rate, etc.).
3. **Level Objectives** — Define win/lose conditions (e.g., kill 10 enemies, reach flag).
4. **Preview Mode** — Test the level in real time.
5. **Save/Load** — Serialize the level to a file (JSON).
6. **UI** — Toolbar, canvas, inspector, and menus.

