<title>Modular Synthesizer</title>
<link rel="stylesheet" href="style.css">
</head>
<body>
<div class="app">
  <header class="topbar">
    <h1>Modular Synthesizer</h1>
    <div class="topbar-right">
      <button id="btn-play" class="btn" title="Play/Pause">⏸ Play</button>
      <button id="btn-record" class="btn" title="Record (WAV export)">⏺ Record</button>
      <button id="btn-undo" class="btn" title="Undo">↶ Undo</button>
