### 3. `app.js`

```javascript
/* =========================================================
   StickerLab — Dynamic Sticker Editor
   ========================================================= */

const canvas = document.getElementById('mainCanvas');
const ctx = canvas.getContext('2d');
const uploadedImg = document.getElementById('uploadedImg');
const emptyState = document.getElementById('emptyState');
const palette = document.getElementById('stickerPalette');
const animSelect = document.getElementById('animSelect');
const speedRange = document.getElementById('speedRange');
const speedVal = document.getElementById('speedVal');
const canvasFrame = document.querySelector('.canvas-frame');
const canvasOverlay = document.getElementById('canvasOverlay');
const overlayText = document.getElementById('overlayText');
const metaSize = document.getElementById('metaSize');
const metaLayers = document.getElementById('metaLayers');

// State
const state = {
  image: null,
  stickers: [], // { id, type, text, x, y, w, h, rot, anim, animPhase, color }
  anim: 'none',
  speed: 1,
  animating: false,
  gifFrames: [],
  gifFrameIndex: 0,
  gifTimer: null,
  videoRecorder: null,
  videoChunks: [],
  videoBlob: null,
};

const STICKER_TYPES = [
  { id: 'emoji1', type: 'emoji', text: '😀', color: '#fbbf24' },
  { id: 'emoji2', type: 'emoji', text: '😎', color: '#f97316' },
  { id: 'emoji3', type: 'emoji', text: '✨', color: '#60a5fa' },
  { id: 'emoji4', type: 'emoji', text: '❤️', color: '#ec4899' },
  { id: 'emoji5', type: 'emoji', text: '🔥', color: '#f92672' },
  { id: 'emoji6', type: 'emoji', text: '🚀', color: '#f472b6' },
  { id: 'text1', type: 'text', text: 'Hello', color: '#60a5fa' },
  { id: 'text2', type: 'text', text: 'World', color: '#818cf8' },
  { id: 'text3', type: 'text', text: 'StickerLab', color: '#a78bfa' },
  { id: 'text4', type: 'text', text: '✨', color: '#fbbf24' },
  { id: 'text5', type: 'text', text: 'WOW', color: '#f92672' },
  { id: 'shape1', type: 'shape', text: '★', color: '#f472b6' },
  { id: 'shape2', type: 'shape', text: '★', color: '#a78bfa' },
  { id: 'shape3', type: 'shape', text: '★', color: '#fbbf24' },
];

// ---------- Utilities ----------
function loadImage(file) {
  return new Promise((resolve, reject) => {
    const r = new FileReader();
    r.onload = () => resolve(r.result);
    r.onerror = reject;
    r.readAsDataURL(file);
  });
}

function rand(min, max) { return Math.random() * (max - min) + min; }

function getStickerCount(type) {
  return state.stickers.filter(s => s.type === type).length;
}

function addSticker(type) {
  const sticker = STICKER_TYPES.find(t => t.id === type);
  if (!sticker) return;
  const rect = canvas.getBoundingClientRect();
  const imgW = uploadedImg ? uploadedImg.naturalWidth : 1200;
  const imgH = uploadedImg ? uploadedImg.naturalHeight : 800;
  const scale = Math.min(rect.width / imgW, rect.height / imgH);
  const w = (sticker.type === 'text' ? 160 : 80) * scale;
  const h = (sticker.type === 'text' ? 40 : 48) * scale;
  const x = rand(20, rect.width - w - 20);
  const y = rand(20, rect.height - h - 20);
  state.stickers.push({
    id: 's' + Date.now() + Math.random().toString(36).slice(2, 6),
    type: sticker.type,
    text: sticker.text,
    color: sticker.color,
    x, y, w, h,
    rot: 0,
    anim: animSelect.value,
    animPhase: Math.random() * Math.PI * 2,
    scale: 1,
  });
  render();
  updatePaletteCounts();
}

function updatePaletteCounts() {
  STICKER_TYPES.forEach(t => {
    const el = document.getElementById('sticker-' + t.id);
    if (el) el.querySelector('.count').textContent = getStickerCount(t.id);
  });
}

function removeSticker(id) {
  state.stickers = state.stickers.filter(s => s.id !== id);
  render();
  updatePaletteCounts();
}

function reset() {
  state.stickers = [];
  state.anim = 'none';
  animSelect.value = 'none';
  state.speed = 1;
  speedRange.value = 1;
  speedVal.textContent = '1.0';
  render();
  updatePaletteCounts();
}

function updateImage() {
  const rect = canvas.getBoundingClientRect();
  const imgW = uploadedImg ? uploadedImg.naturalWidth : 1200;
  const imgH = uploadedImg ? uploadedImg.naturalHeight : 800;
  const scale = Math.min(rect.width / imgW, rect.height / imgH);
  canvas.width = imgW * scale;
  canvas.height = imgH * scale;
  metaSize.textContent = `${imgW} × ${imgH} px`;
  metaLayers.textContent = `${state.stickers.length} sticker${state.stickers.length === 1 ? '' : 's'}`;
  render();
}

// ---------- Rendering ----------
function render() {
  const rect = canvas.getBoundingClientRect();
  const imgW = uploadedImg ? uploadedImg.naturalWidth : 1200;
  const imgH = uploadedImg ? uploadedImg.naturalHeight : 800;
  const scale = Math.min(rect.width / imgW, rect.height / imgH);
  canvas.width = imgW * scale;
  canvas.height = imgH * scale;

  ctx.clearRect(0, 0, canvas.width, canvas.height);

  if (uploadedImg) {
    ctx.drawImage(uploadedImg, 0, 0, canvas.width, canvas.height);
  }

  state.stickers.forEach(s => {
    const x = s.x;
    const y = s.y;
    const w = s.w;
    const h = s.h;
    const rot = s.rot;

    if (s.type === 'text') {
      ctx.save();
      ctx.translate(x + w / 2, y + h / 2);
      ctx.rotate(rot);
      ctx.fillStyle = s.color;
      ctx.font = `bold ${Math.max(14, Math.round(h * 0.5)) * 0.8}px system-ui, sans-serif`;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(s.text, 0, 0);
      ctx.restore();
    } else {
      // Emoji / shape: draw with color
      ctx.save();
      ctx.translate(x + w / 2, y + h / 2);
      ctx.rotate(rot);
      ctx.fillStyle = s.color;
      ctx.font = 'bold 24px system-ui, sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(s.text, 0, 0);
      ctx.restore();
    }
  });
}

// ---------- Animation loop ----------
function animate() {
  if (!state.image) return;
  const rect = canvas.getBoundingClientRect();
  const imgW = uploadedImg ? uploadedImg.naturalWidth : 1200;
  const imgH = uploadedImg ? uploadedImg.naturalHeight : 800;
  const scale = Math.min(rect.width / imgW, rect.height / imgH);
  canvas.width = imgW * scale;
  canvas.height = imgH * scale;

  ctx.clearRect(0, 0, canvas.width, canvas.height);

  if (uploadedImg) {
    ctx.drawImage(uploadedImg, 0, 0, canvas.width, canvas.height);
  }

  const speed = state.speed;
  state.stickers.forEach(s => {
    const x = s.x;
    const y = s.y;
    const w = s.w;
    const h = s.h;
    s.rot += 0.05 * speed;

    if (s.anim === 'bounce') {
      s.animPhase += 0.15 * speed;
      const t = s.animPhase % Math.PI * 2;
      const dist = Math.abs(Math.sin(t) * 10);
      s.x += Math.sin(t) * 1.5;
      s.y += Math.cos(t) * 1.5;
    } else if (s.anim === 'pulse') {
      s.animPhase += 0.2 * speed;
      const t = s.animPhase % Math.PI * 2;
      const pulse = 1 + Math.sin(t) * 0.15;
      s.scale = 1 + Math.sin(t) * 0.2;
      s.w *= pulse;
      s.h *= pulse;
    } else if (s.anim === 'spin') {
      s.animPhase += 0.1 * speed;
    } else if (s.anim === 'wiggle') {
      s.animPhase += 0.15 * speed;
      const t = s.animPhase % Math.PI * 2;
      const wiggle = Math.sin(t) * 2;
      s.x += wiggle * 0.5;
      s.y += Math.cos(t) * 0.5;
    }

    if (s.type === 'text') {
      ctx.save();
      ctx.translate(x + w / 2, y + h / 2);
      ctx.rotate(s.rot);
      ctx.fillStyle = s.color;
      ctx.font = `bold ${Math.max(14, Math.round(h * 0.5)) * 0.8}px system-ui, sans-serif`;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(s.text, 0, 0);
      ctx.restore();
    } else {
      ctx.save();
      ctx.translate(x + w / 2, y + h / 2);
      ctx.rotate(s.rot);
      ctx.scale(s.scale, s.scale);
      ctx.fillStyle = s.color;
      ctx.font = 'bold 24px system-ui, sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(s.text, 0, 0);
      ctx.restore();
    }
  });

  if (state.animating) {
    state.gifFrames.push(canvas.toDataURL('image/png'));
    if (state.gifFrames.length >= 150) {
      state.animating = false;
      canvasOverlay.classList.remove('active');
      overlayText.textContent = 'Animation complete';
      setTimeout(() => { overlayText.textContent = 'Generating…'; }, 500);
    }
  }
}

// ---------- GIF export ----------
function exportGif() {
  if (!state.image) return;
  if (state.gifFrames.length < 2) {
    alert('Render animation first (press play or wait for auto-play).');
    return;
  }
  canvasOverlay.classList.add('active');
  overlayText.textContent = 'Exporting GIF…';

  const gif = new GIF({
    workers: 2,
    quality: 9,
    width: canvas.width,
    height: canvas.height,
  });
  state.gifFrames.forEach((frame, i) => {
    const img = new Image();
    img.onload = () => gif.addFrame(img, { delay: 60, copy: true });
    img.src = frame;
  });
  gif.on('finished', function (blob) {
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'stickerlab.gif';
    a.click();
    URL.revokeObjectURL(url);
    canvasOverlay.classList.remove('active');
    overlayText.textContent = 'GIF exported!';
    setTimeout(() => { overlayText.textContent = 'Export GIF'; }, 1500);
  });
  gif.on('error', function (err) {
    console.error(err);
    canvasOverlay.classList.remove('active');
    overlayText.textContent = 'Export failed';
  });
  gif.on('progress', function (p) {
    overlayText.textContent = `Exporting… ${Math.round(p * 100)}%`;
  });
  gif.render();
}

// ---------- Video export ----------
async function exportVideo() {
  if (!state.image) return;
  if (state.stickers.length === 0) {
    alert('Add at least one sticker to export a video.');
    return;
  }
  canvasOverlay.classList.add('active');
  overlayText.textContent = 'Recording video…';

  // Create a small offscreen canvas for recording
  const offCanvas = document.createElement('canvas');
  offCanvas.width = canvas.width;
  offCanvas.height = canvas.height;
  const offCtx = offCanvas.getContext('2d');

  // Capture source image
  offCtx.drawImage(canvas, 0, 0);

  // MediaRecorder
  const stream = canvas.captureStream(30);
  const videoTrack = stream.getVideoTracks()[0];
  const enc = videoTrack.getSettings().codec || 'vp9';
  const mime = `video/webm;codecs=${enc},opus`;

  const options = { mimeType: mime };
  const recorder = new MediaRecorder(stream, options);
  recorder.ondataavailable = (e) => {
    if (e.data.size > 0) state.videoChunks.push(e.data);
  };
  recorder.onstop = () => {
    state.videoBlob = new Blob(state.videoChunks, { type: mime });
    const url = URL.createObjectURL(state.videoBlob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'stickerlab.webm';
    a.click();
    URL.revokeObjectURL(url);
    canvasOverlay.classList.remove('active');
    overlayText.textContent = 'Video exported!';
    setTimeout(() => { overlayText.textContent = 'Export Video'; }, 1500);
  };
  recorder.onerror = (e) => {
    console.error(e);
    canvasOverlay.classList.remove('active');
    overlayText.textContent = 'Export failed';
  };

  state.videoChunks = [];
  recorder.start();
  await new Promise(r => setTimeout(r, 1500));
  recorder.stop();
}

// ---------- Event wiring ----------
document.getElementById('addBtn').addEventListener('click', () => {
  if (!state.image) {
    alert('Upload an image first.');
    return;
  }
  addSticker(STICKER_TYPES[0].id);
});

palette.addEventListener('click', (e) => {
  const btn = e.target.closest('.sticker-item');
  if (!btn) return;
  addSticker(btn.dataset.id);
});

animSelect.addEventListener('change', (e) => {
  state.anim = e.target.value;
  state.stickers.forEach(s => s.anim = e.target.value);
  render();
});

speedRange.addEventListener('input', (e) => {
  state.speed = parseFloat(e.target.value);
  speedVal.textContent = state.speed.toFixed(1);
});

document.getElementById('exportGifBtn').addEventListener('click', exportGif);
document.getElementById('exportVideoBtn').addEventListener('click', exportVideo);
document.getElementById('resetBtn').addEventListener('click', reset);

// File upload
const fileInput = document.createElement('input');
fileInput.type = 'file';
fileInput.accept = 'image/*';
fileInput.style.display = 'none';

document.addEventListener('click', (e) => {
  if (e.target.closest('.add-sticker')) {
    e.stopPropagation();
    fileInput.click();
  }
});

document.addEventListener('change', (e) => {
  if (e.target === fileInput && fileInput.files[0]) {
    loadImage(fileInput.files[0]).then(dataUrl => {
      uploadedImg.src = dataUrl;
      emptyState.classList.add('hidden');
      state.image = dataUrl;
      updateImage();
      // Auto-add a sticker
      setTimeout(() => addSticker(STICKER_TYPES[0].id), 200);
    }).catch(err => {
      alert('Failed to load image: ' + err.message);
    });
  }
});

// Keyboard shortcuts
document.addEventListener('keydown', (e) => {
  if (e.target.tagName === 'INPUT' || e.target.tagName === 'SELECT') return;
  if (e.key === 'g' || e.key === 'G') exportGif();
  if (e.key === 'v' || e.key === 'V') exportVideo();
  if (e.key === 'r' || e.key === 'R') reset();
});

// ---------- Init ----------
updatePaletteCounts();
