## ⚙️ script.js

```javascript
(() => {
  'use strict';

  const $ = (id) => document.getElementById(id);

  const els = {
    dropzone: $('dropzone'),
    audioInput: $('audioInput'),
    lrcInput: $('lrcInput'),
    browseBtn: $('browseBtn'),
    audioEl: $('audioEl'),
    lyrics: $('lyrics'),
    lyricsWrap: $('lyricsWrap'),
    playBtn: $('playBtn'),
    pauseBtn: $('pauseBtn'),
    stopBtn: $('stopBtn'),
    exportBtn: $('exportBtn'),
    offset: $('offset'),
    offsetValue: $('offsetValue'),
    speed: $('speed'),
    speedValue: $('speedValue'),
    audioName: $('audioName'),
    audioDur: $('audioDur'),
    infoOffset: $('infoOffset'),
    infoSpeed: $('infoSpeed'),
    wordCount: $('wordCount'),
  };

  const state = {
    audio: null,
    lrc: null,
    words: [],
    currentOffset: 0,
    currentSpeed: 1,
    playing: false,
    rafId: null,
  };

  // ---------- File handling ----------
  function handleFiles() {
    els.audioInput.click();
    els.lrcInput.click();
  }

  els.browseBtn.addEventListener('click', handleFiles);
  els.dropzone.addEventListener('click', handleFiles);

  ['dragenter', 'dragover'].forEach((ev) => {
    els.dropzone.addEventListener(ev, (e) => {
      e.preventDefault();
      els.dropzone.classList.add('dragover');
    });
  });
  ['dragleave', 'drop'].forEach((ev) => {
    els.dropzone.addEventListener(ev, (e) => {
      e.preventDefault();
      els.dropzone.classList.remove('dragover');
    });
  });
  els.dropzone.addEventListener('drop', (e) => {
    const files = e.dataTransfer.files;
    if (files.length >= 2) {
      loadFiles(files[0], files[1]);
    } else if (files.length === 1) {
      loadFiles(files[0], null);
    }
  });

  els.audioInput.addEventListener('change', (e) => {
    const f = e.target.files[0];
    if (f) loadFiles(f, null);
  });
  els.lrcInput.addEventListener('change', (e) => {
    const f = e.target.files[0];
    if (f) loadLrcFile(f);
  });

  // ---------- Load audio ----------
  function loadFiles(audioFile, lrcFile) {
    if (!audioFile) {
      alert('Please upload an audio file.');
      return;
    }
    loadAudio(audioFile);
    if (lrcFile) loadLrcFile(lrcFile);
    else {
      state.lrc = null;
      renderLyrics();
    }
  }

  function loadAudio(file) {
    const url = URL.createObjectURL(file);
    state.audio = new Audio(url);
    state.audioEl = state.audio;
    state.audio.addEventListener('loadedmetadata', () => {
      els.audioName.textContent = file.name;
      els.audioDur.textContent = formatTime(state.audio.duration);
    });
    state.audio.addEventListener('error', () => {
      els.audioName.textContent = 'Error loading audio';
      els.audioDur.textContent = '—';
    });
    state.audio.play().catch(() => {});
  }

  // ---------- Load LRC ----------
  function loadLrcFile(file) {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        state.lrc = parseLrc(e.target.result);
        renderLyrics();
      } catch (err) {
        alert('Invalid LRC format:\n' + err.message);
      }
    };
    reader.onerror = () => alert('Failed to read LRC file.');
    reader.readAsText(file);
  }

  function parseLrc(text) {
    const lines = text.split('\n').map((l) => l.trim()).filter(Boolean);
    const words = [];
    const currentLine = [];
    let currentTime = 0;

    for (const line of lines) {
      const m = line.match(/^\[(\d+):(\d+\.?\d*)\]\s*(.*)$/);
      if (m) {
        const mm = parseInt(m[1], 10);
        const ss = parseFloat(m[2]);
        const total = mm * 60 + ss;
        const raw = m[3];
        const parts = raw.split(/\s+/).filter(Boolean);
        for (const part of parts) {
          const match = part.match(/^(\d+\.?\d*)\s*(.*)$/);
          if (match) {
            const dur = parseFloat(match[1]);
            const text = match[2];
            words.push({ time: total, duration: dur, text });
          } else {
            words.push({ time: total, duration: 0, text: part });
          }
        }
        currentLine.length = 0;
        currentTime = total;
      } else {
        currentLine.push(line);
      }
    }

    // Final line
    if (currentLine.length) {
      const parts = currentLine.join(' ').split(/\s+/).filter(Boolean);
      for (const part of parts) {
        const match = part.match(/^(\d+\.?\d*)\s*(.*)$/);
        if (match) {
          const dur = parseFloat(match[1]);
          const text = match[2];
          words.push({ time: currentTime, duration: dur, text });
        } else {
          words.push({ time: currentTime, duration: 0, text: part });
        }
      }
    }

    return words;
  }

  // ---------- Rendering ----------
  function renderLyrics() {
    els.lyrics.innerHTML = '';
    state.words = state.lrc || [];

    els.wordCount.textContent = state.words.length;
    els.lyricsWrap.scrollTop = 0;

    const container = document.createElement('div');
    container.className = 'lyrics';

    // Group into lines
    const lines = [];
    for (const w of state.words) {
      const line = lines[lines.length - 1];
      if (!line || line.text + ' ' + w.text.length > 70) {
        lines.push({ text: '', words: [] });
      }
      lines[lines.length - 1].text += w.text + ' ';
      lines[lines.length - 1].words.push(w);
    }

    for (const line of lines) {
      const wrap = document.createElement('div');
      wrap.className = 'line';
      const num = document.createElement('span');
      num.className = 'line-number';
      num.textContent = line.words.length;
      wrap.appendChild(num);
      const text = document.createElement('span');
      text.className = 'line-text';
      for (const w of line.words) {
        const span = document.createElement('span');
        span.className = 'word';
        span.textContent = w.text;
        span.dataset.time = w.time;
        span.dataset.duration = w.duration;
        span.dataset.offset = state.currentOffset;
        span.dataset.speed = state.currentSpeed;
        text.appendChild(span);
      }
      wrap.appendChild(text);
      container.appendChild(wrap);
    }

    els.lyrics.appendChild(container);
    attachWordHandlers(container);
  }

  function attachWordHandlers(container) {
    container.querySelectorAll('.word').forEach((word) => {
      word.addEventListener('click', () => {
        if (!state.audio) return;
        const time = parseFloat(word.dataset.time) + state.currentOffset;
        state.audio.currentTime = time;
        state.audio.play().catch(() => {});
      });
    });
  }

  // ---------- Timing ----------
  function formatTime(sec) {
    if (!isFinite(sec)) return '—';
    const h = Math.floor(sec / 3600);
    const m = Math.floor((sec % 3600) / 60);
    const s = sec % 60;
    return h ? `${h}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}` : `${m}:${String(s).padStart(2, '0')}`;
  }

  function getCurrentTime() {
    if (!state.audio) return 0;
    return state.audio.currentTime * state.currentSpeed + state.currentOffset;
  }

  function getWordIndex(time) {
    let max = -1;
    for (let i = 0; i < state.words.length; i++) {
      const w = state.words[i];
      const start = w.time + state.currentOffset;
      const end = start + w.duration;
      if (time >= start && time <= end) {
        max = i;
      }
    }
    return max;
  }

  // ---------- Animation loop ----------
  function tick() {
    if (!state.playing || !state.audio) return;
    const time = getCurrentTime();
    const idx = getWordIndex(time);

    // Highlight current word
    els.lyrics.querySelectorAll('.word').forEach((w) => {
      const wIdx = parseInt(w.dataset.index, 10);
      const active = !Number.isNaN(wIdx) && wIdx === idx;
      w.classList.toggle('active', active);
      if (active) {
        w.dataset.index = idx;
      }
    });

    state.rafId = requestAnimationFrame(tick);
  }

  // ---------- Controls ----------
  els.offset.addEventListener('input', () => {
    state.currentOffset = parseFloat(els.offset.value);
    els.offsetValue.textContent = state.currentOffset.toFixed(1);
    els.infoOffset.textContent = state.currentOffset.toFixed(1) + ' s';
    if (state.words.length) renderLyrics();
  });

  els.speed.addEventListener('input', () => {
    state.currentSpeed = parseFloat(els.speed.value);
    els.speedValue.textContent = state.currentSpeed.toFixed(1) + '×';
    els.infoSpeed.textContent = state.currentSpeed.toFixed(1) + '×';
  });

  function play() {
    if (!state.audio) return;
    state.playing = true;
    state.audio.play().catch(() => {});
    state.rafId = requestAnimationFrame(tick);
  }
  function pause() {
    if (!state.audio) return;
    state.playing = false;
    state.audio.pause();
    cancelAnimationFrame(state.rafId);
  }
  function stop() {
    if (!state.audio) return;
    state.playing = false;
    state.audio.pause();
    state.audio.currentTime = 0;
    cancelAnimationFrame(state.rafId);
  }

  els.playBtn.addEventListener('click', play);
  els.pauseBtn.addEventListener('click', pause);
  els.stopBtn.addEventListener('click', stop);

  // ---------- Export ----------
  function exportLrc() {
    if (!state.lrc) return;
    const out = state.lrc.map((w) => {
      const start = w.time + state.currentOffset;
      const end = start + w.duration;
      return `[${formatTime(start)}] ${w.text}`;
    }).join('\n');
    const blob = new Blob([out], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'karaoke.lrc';
    a.click();
    URL.revokeObjectURL(url);
  }
  els.exportBtn.addEventListener('click', exportLrc);

  // ---------- Keyboard ----------
  document.addEventListener('keydown', (e) => {
    if (e.code === 'Space') {
      e.preventDefault();
      if (state.playing) pause(); else play();
    } else if (e.key === 'Escape') {
      pause();
    }
  });
})();
