$("#copyBtn").addEventListener("click", async () => {
  const shape = SHAPES[state.shape];
  const dim = {};
  shape.params.forEach(p => { dim[p.k] = state.params[p.k] || 0; });
  const area = shape.area ? fmt(shape.area(...Object.values(dim))) : null;
  const perimeter = shape.perimeter ? fmt(shape.perimeter(...Object.values(dim))) : null;
  const volume = shape.volume ? fmtBig(shape.volume(...Object.values(dim))) : null;
  const surface = shape.surface ? fmtBig(shape.surface(...Object.values(dim))) : null;

  const lines = [
    `Shape: ${shape.label}`,
    `Parameters: ${shape.params.map(p => `${p.k} = ${state.params[p.k] || 0}`).join(", ")}`,
    `Area: ${area} m²`,
    `Perimeter: ${perimeter} m`,
    `Volume: ${volume} m³`,
    `Surface Area: ${surface} m²`
  ].filter(l => l.includes(":") && l.split(":")[1].trim() !== "null" && l.split(":")[1].trim() !== "—");

  if (lines.length === 0) { toast("Nothing to copy", "error"); return; }
  await navigator.clipboard.writeText(lines.join("\n"));
  toast("Results copied to clipboard");
});

$("#shareBtn").addEventListener("click", async () => {
  const shape = SHAPES[state.shape];
  const dim = {};
  shape.params.forEach(p => { dim[p.k] = state.params[p.k] || 0; });
  const area = shape.area ? fmt(shape.area(...Object.values(dim))) : null;
  const perimeter = shape.perimeter ? fmt(shape.perimeter(...Object.values(dim))) : null;
  const volume = shape.volume ? fmtBig(shape.volume(...Object.values(dim))) : null;
  const surface = shape.surface ? fmtBig(shape.surface(...Object.values(dim))) : null;

  const text = [
    `Geometric Calculator · ${shape.label}`,
    `r = ${dim.radius || 0} m`,
    `Area = ${area} m²`,
    `Perimeter = ${perimeter} m`,
    `Volume = ${volume} m³`,
    `Surface Area = ${surface} m²`
  ].join("\n");

  const shareData = { title: "Geometric Calculator", text };
  if (navigator.share) {
    navigator.share(shareData).catch(() => {});
  } else {
    try {
      await navigator.clipboard.writeText(text);
      toast("Link ready (copy manually)");
    } catch {
      toast("Share not supported", "error");
    }
  }
});

