## ⚙️ JavaScript

```javascript
// Rhythm Trainer — app.js
(() => {
  'use strict';

  const state = {
    bpm: 120,
    pattern: 4,          // 4/4, 3/4, or 6/4
    rounds: 5,
    roundsLeft: 0,
    taps: 0,
    score: 0,
    accuracy: 0,
    targetTimes: [],     // ms from round start for each beat
    roundStartTime: 0,
    roundTaps: [],
    isPlaying: false,
    beatIndex: 0,
    lastBeatTime: 0,
    audioCtx: null,
  };

  const els = {
    bpm: document.getElementById('bpm'),
    bpmVal: document.getElementById('bpmVal'),
    pattern: document.getElementById('pattern'),
    rounds: document.getElementById('rounds'),
    startBtn: document.getElementById('startBtn'),
    resetBtn: document.getElementById('resetBtn'),
    metronome: document.getElementById('metronome'),
    status: document.getElementById('status'),
    accuracy: document.getElementById('accuracy'),
    score: document.getElementById('score'),
    taps: document.getElementById('taps'),
    statAccuracy: document.querySelector('.stat:nth-of-type(1)'),
    statScore: document.querySelector('.stat:nth-of-type(2)'),
    statTaps: document.querySelector('.stat:nth-of-type(3)'),
  };

  // Build metronome dots based on pattern
  function buildMetronome() {
    const dots = document.querySelectorAll('.dot');
    dots.forEach((d, i) => {
      d.remove();
    });
    const count = state.pattern === 6 ? 6 : state.pattern;
    for (let i = 0; i < count; i++) {
      const d = document.createElement('div');
      d.className = 'dot';
      els.metronome.appendChild(d);
    }
  }

  function setBpmDisplay() {
    els.bpmVal.textContent = state.bpm;
  }

  function setPatternDisplay() {
    els.pattern.value = state.pattern;
  }

  function setStatus(text, cls = '') {
    els.status.textContent = text;
    els.status.className = 'status ' + cls;
  }

  function updateStats() {
    els.accuracy.textContent = state.accuracy.toFixed(1) + '%';
    els.score.textContent = state.score;
    els.taps.textContent = state.taps;
    els.statAccuracy.classList.toggle('best', state.accuracy >= 95);
    els.statAccuracy.classList.toggle('worst', state.accuracy <= 60);
  }

  function resetStats() {
    state.taps = 0;
    state.score = 0;
    state.accuracy = 0;
    state.roundTaps = [];
    state.targetTimes = [];
    updateStats();
    setStatus('Ready', 'ready');
  }

  function roundStart() {
    state.roundStartTime = performance.now();
    state.beatIndex = 0;
    state.lastBeatTime = state.roundStartTime;
    state.targetTimes = generateTargetTimes();
    state.roundTaps = [];
    els.status.textContent = 'Round ' + (state.roundsLeft) + ' of ' + state.rounds;
    setStatus('Round ' + (state.roundsLeft) + ' of ' + state.rounds, 'ready');
    els.metronome.querySelectorAll('.dot').forEach(d => d.classList.remove('active', 'hit', 'miss'));
  }

  function generateTargetTimes() {
    const beats = state.pattern === 6 ? 6 : state.pattern;
    const beatInterval = 60000 / state.bpm / beats; // ms per beat
    const times = [];
    for (let i = 0; i < beats; i++) {
      times.push(state.roundStartTime + i * beatInterval);
    }
    return times;
  }

  function playBeat() {
    if (!state.audioCtx) initAudio();
    const osc = state.audioCtx.createOscillator();
    const gain = state.audioCtx.createGain();
    osc.type = 'square';
    osc.frequency.value = 440 + Math.sin(state.beatIndex * 0.3) * 80;
    gain.gain.setValueAtTime(0, state.audioCtx.currentTime);
    gain.gain.linearRampToValueAtTime(0.15, state.audioCtx.currentTime + 0.02);
    gain.gain.exponentialRampToValueAtTime(0.001, state.audioCtx.currentTime + 0.25);
    osc.connect(gain).connect(state.audioCtx.destination);
    osc.start();
    osc.stop(state.audioCtx.currentTime + 0.26);
  }

  function initAudio() {
    state.audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    // Prevent iOS autoplay blocking
    try { state.audioCtx.resume(); } catch (e) {}
  }

  function tapHandler(e) {
    if (!state.isPlaying) return;
    const now = performance.now();
    const target = state.targetTimes[state.beatIndex];
    const diff = now - target;
    state.roundTaps.push({ time: now, diff });
    state.taps++;

    const dot = els.metronome.children[state.beatIndex];
    dot.classList.add('hit');
    setTimeout(() => dot.classList.remove('hit'), 200);

    const absDiff = Math.abs(diff);
    if (absDiff < 50) {
      state.score += 10;
    } else if (absDiff < 150) {
      state.score += 5;
    } else {
      state.score -= 2;
    }

    state.accuracy = Math.round((state.score / (state.taps * 10)) * 100);

    if (state.beatIndex < state.targetTimes.length - 1) {
      state.beatIndex++;
      state.lastBeatTime = target;
    } else {
      roundEnd();
    }
  }

  function roundEnd() {
    state.isPlaying = false;
    state.roundsLeft--;
    const total = state.roundTaps.length;
    const misses = state.roundTaps.filter(t => Math.abs(t.diff) > 150).length;
    const avg = total ? state.roundTaps.reduce((s, t) => s + Math.abs(t.diff), 0) / total : 0;

    els.status.textContent = 'Round done — ' + total + ' taps';
    setStatus('Round done — ' + total + ' taps', 'done');

    // Final score bonus
    if (misses === 0) state.score += 50;
    if (avg < 20) state.score += 20;

    updateStats();
    if (state.roundsLeft > 0) {
      setTimeout(() => roundStart(), 1200);
    } else {
      setTimeout(() => {
        setStatus('Final score: ' + state.score, 'done');
      }, 1200);
    }
  }

  function startRoundLoop() {
    state.isPlaying = true;
    const beatInterval = 60000 / state.bpm / state.pattern;
    const interval = beatInterval;
    state.beatIndex = 0;
    state.lastBeatTime = state.roundStartTime;

    const tick = () => {
      if (!state.isPlaying) return;
      const now = performance.now();
      const target = state.targetTimes[state.beatIndex];
      const diff = now - target;
      const dot = els.metronome.children[state.beatIndex];
      dot.classList.add('active');
      setTimeout(() => dot.classList.remove('active'), 100);

      if (now >= target) {
        playBeat();
        state.beatIndex++;
        state.lastBeatTime = target;
      }
      setTimeout(tick, interval);
    };
    tick();
  }

  function start() {
    state.roundsLeft = state.rounds;
    resetStats();
    roundStart();
    startRoundLoop();
    setStatus('Playing', 'playing');
  }

  function reset() {
    state.isPlaying = false;
    state.roundsLeft = 0;
    state.taps = 0;
    state.score = 0;
    state.accuracy = 0;
    state.roundTaps = [];
    state.targetTimes = [];
    els.metronome.querySelectorAll('.dot').forEach(d => d.classList.remove('active', 'hit', 'miss'));
    if (state.audioCtx) state.audioCtx.close();
    state.audioCtx = null;
    setStatus('Ready', 'ready');
    updateStats();
  }

  // Event wiring
  els.bpm.addEventListener('input', (e) => {
    state.bpm = parseInt(e.target.value, 10);
    setBpmDisplay();
  });
  els.pattern.addEventListener('change', (e) => {
    state.pattern = parseInt(e.target.value, 10);
    setPatternDisplay();
    buildMetronome();
  });
  els.rounds.addEventListener('input', (e) => {
    state.rounds = parseInt(e.target.value, 10);
  });
  els.startBtn.addEventListener('click', start);
  els.resetBtn.addEventListener('click', reset);

  // Prevent double-tap on mobile
  let tapTimer = null;
  document.addEventListener('click', (e) => {
    if (tapTimer) return;
    tapTimer = setTimeout(() => tapTimer = null, 200);
    tapHandler(e);
  });

  // Init
  setBpmDisplay();
  setPatternDisplay();
  buildMetronome();
  updateStats();
})();
```

