### 📄 `background.js`

```javascript
(function () {
  'use strict';

  const STORAGE_KEY = 'tasks';

  // ---------- Persistence ----------
  function loadTasks() {
    return new Promise(resolve => {
      chrome.storage.sync.get(STORAGE_KEY, (result) => {
        resolve(result[STORAGE_KEY] || []);
      });
    });
  }

  function saveTasks(tasks) {
    return new Promise(resolve => {
      chrome.storage.sync.set({ [STORAGE_KEY]: tasks }, () => resolve());
    });
  }

  // ---------- Task model ----------
  function parseSchedule(raw) {
    if (!raw) return null;
    const parts = raw.trim().split(/\s+/);
    if (parts.length < 2) return null;
    const type = parts[0];
    const time = parts.slice(1).join(' ');
    return { type, time };
  }

  function parseTime(timeStr) {
    const m = timeStr.match(/(\d{1,2}):(\d{2})(?:\s*(am|pm|AM|PM)?)?/);
    if (!m) return null;
    let h = parseInt(m[1], 10);
    const mi = parseInt(m[2], 10);
    const ampm = m[3];
    if (ampm && ampm !== 'am' && ampm !== 'pm') return null;
    if (ampm === 'pm' && h !== 12) h += 12;
    if (ampm === 'am' && h === 12) h = 0;
    return { h, mi };
  }

  function nextFireTime(task) {
    const { type, time: rawTime } = task;
    const parsed = parseTime(rawTime);
    if (!parsed) return null;
    const { h, mi } = parsed;
    const now = new Date();
    now.setMilliseconds(0);
    now.setSeconds(0);
    now.setMinutes(now.getMinutes() + 1);

    let target = new Date(now);
    target.setHours(h, mi, 0, 0);

    if (target <= now) {
      target.setDate(target.getDate() + 1);
    }

    if (type === 'daily') {
      // fire at the same time every day
      return target;
    }
    if (type === 'hourly') {
      // fire every hour at the given minute
      const diff = (target.getTime() - now.getTime()) / 36e5;
      const offset = Math.ceil(diff);
      return new Date(now.getTime() + offset * 36e5);
    }
    return target;
  }

  // ---------- Alarm management ----------
  function scheduleAlarm(task) {
    const fireAt = nextFireTime(task);
    if (!fireAt) return;

    const alarmId = `task-${task.id}-${fireAt.getTime()}`;
    chrome.alarms.create(alarmId, {
      when: fireAt.getTime(),
      periodInMinutes: task.type === 'daily' ? 24 * 60 : 60
    });
  }

  function clearAlarm(id) {
    chrome.alarms.clear(id);
  }

  // ---------- Notification ----------
  function showNotification(task) {
    const title = `Task: ${task.name}`;
    const body = `Due at ${task.time} — ${task.js}`;
    chrome.notifications.create({
      type: 'basic',
      iconUrl: 'icon48.png',
      title,
      message: body,
      requireInteraction: true
    });
  }

  // ---------- JS Execution ----------
  async function executeJS(task) {
    try {
      // Use chrome.tabs.executeScript to inject JS into active tab
      // This runs in the context of the active tab (not background).
      // We'll inject a small script that runs the JS code.
      const code = task.js;
      const script = `(${code})()`;
      const result = await chrome.tabs.executeScript(null, {
        code: `(() => { try { ${script} } catch (e) { console.error(e); } })()`
      });
      return result;
    } catch (err) {
      console.error('JS execution failed:', err);
      return null;
    }
  }

  // ---------- Alarm handler ----------
  chrome.alarms.onAlarm.addListener(async (alarm) => {
    const id = alarm.name;
    if (!id.startsWith('task-')) return;
    const parts = id.split('-');
    const taskId = parts[1];
    const tasks = await loadTasks();
    const task = tasks.find(t => t.id === taskId);
    if (!task) return;

    showNotification(task);
    await executeJS(task);

    // Reschedule for next occurrence
    const fireAt = nextFireTime(task);
    if (fireAt) {
      const newId = `task-${task.id}-${fireAt.getTime()}`;
      chrome.alarms.create(newId, {
        when: fireAt.getTime(),
        periodInMinutes: task.type === 'daily' ? 24 * 60 : 60
      });
    }
  });

  // ---------- Popup UI ----------
  chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
    if (request.action === 'listTasks') {
      loadTasks().then(sendResponse);
    } else if (request.action === 'addTask') {
      const task = {
        id: Date.now().toString(),
        name: request.name,
        time: request.time,
        type: request.type,
        js: request.js || ''
      };
      loadTasks().then(tasks => {
        saveTasks([...tasks, task]);
        scheduleAlarm(task);
        sendResponse({ ok: true });
      });
    } else if (request.action === 'deleteTask') {
      loadTasks().then(tasks => {
        const filtered = tasks.filter(t => t.id !== request.id);
        saveTasks(filtered);
        clearAlarm(`task-${request.id}`);
        sendResponse({ ok: true });
      });
    }
    return true;
  });

  // ---------- Init ----------
  loadTasks().then(tasks => {
    tasks.forEach(scheduleAlarm);
  });
})();
