```javascript
(function () {
  'use strict';

  const form = document.getElementById('addForm');
  const nameInput = document.getElementById('name');
  const timeInput = document.getElementById('time');
  const typeSelect = document.getElementById('type');
  const jsInput = document.getElementById('js');
  const tasksEl = document.getElementById('tasks');
  const emptyEl = document.getElementById('empty');

  function formatTime(date) {
    const h = date.getHours();
    const m = date.getMinutes();
    const ampm = h >= 12 ? 'pm' : 'am';
    const hh = ((h + 11) % 12) + 1;
    return `${hh}:${String(m).padStart(2, '0')} ${ampm}`;
  }

  function render() {
    chrome.runtime.sendMessage({ action: 'listTasks' }, (tasks) => {
      tasksEl.innerHTML = '';
      if (!tasks || tasks.length === 0) {
        emptyEl.style.display = 'block';
        return;
      }
      emptyEl.style.display = 'none';
      tasks.forEach((task) => {
        const row = document.createElement('div');
        row.className = 'task';
        row.innerHTML = `
          <div class="task-info">
            <div class="task-name">${escapeHtml(task.name)}</div>
            <div class="task-meta">${escapeHtml(task.type)} at ${formatTime(new Date(task.time))}</div>
          </div>
          <div class="task-actions">
            <button data-action="delete" data-id="${task.id}">Delete</button>
          </div>
        `;
        tasksEl.appendChild(row);
      });
    });
  }

  function escapeHtml(str) {
    return String(str).replace(/[&<>"']/g, (c) => ({
      '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
    }[c]));
  }

  form.addEventListener('submit', (e) => {
    e.preventDefault();
    const name = nameInput.value.trim();
    const time = timeInput.value;
    const type = typeSelect.value;
    const js = jsInput.value.trim();

    if (!name || !time) return;

    chrome.runtime.sendMessage({
      action: 'addTask',
      name,
      time,
      type,
      js
    }, () => {
      render();
      form.reset();
      nameInput.focus();
    });
  });

  tasksEl.addEventListener('click', (e) => {
    const btn = e.target.closest('button[data-action="delete"]');
    if (!btn) return;
    const id = btn.dataset.id;
    chrome.runtime.sendMessage({ action: 'deleteTask', id }, () => render());
  });

  render();
})();
