## ✅ Option 2: Standalone Web App (No notifications, no JS execution)

If you want a **standalone HTML page** (no extension), you can use `setInterval` + `setTimeout` and `Notification` API. But **`Notification` requires user permission**, and **`eval`/`Function` is blocked**.

### 📄 `standalone.html`

```html
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <title>Task Scheduler</title>
  <style>
    body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; }
    h1 { margin: 16px 0; }
    .task { padding: 10px; margin: 8px 0; border: 1px solid #ddd; }
    .task-name { font-weight: 600; }
    .task-time { color: #666; font-size: 14px; }
    .task-js { color: #007acc; font-family: "Consolas", monospace; font-size: 13px; }
    .empty { color: #999; font-style: italic; }
    button { padding: 6px 12px; margin: 8px 4px; cursor: pointer; }
  </style>
</head>
<body>
  <h1>Task Scheduler</h1>
  <div id="tasks" class="tasks"></div>
  <div id="empty" class="empty">No tasks yet.</div>

  <h2>Add Task</h2>
  <form id="addForm">
    <div><label>Task name: <input id="name" type="text" /></label></div>
    <div><label>Time: <input id="time" type="time" /></label></div>
    <div><label>Schedule: <select id="type"><option value="daily">Daily</option><option value="hourly">Hourly</option></select></label></div>
    <div><label>JS to run: <textarea id="js" rows="3">location.reload()</textarea></label></div>
    <button type="submit">Add Task</button>
  </form>

  <script>
    const STORAGE_KEY = 'tasks';
    const tasksEl = document.getElementById('tasks');
    const emptyEl = document.getElementById('empty');

    function loadTasks() {
      try {
        const raw = localStorage.getItem(STORAGE_KEY);
        return raw ? JSON.parse(raw) : [];
      } catch { return []; }
    }

    function saveTasks(tasks) {
      try { localStorage.setItem(STORAGE_KEY, JSON.stringify(tasks)); } catch {}
    }

    function formatTime(date) {
      const h = date.getHours();
      const m = date.getMinutes();
      const ampm = h >= 12 ? 'pm' : 'am';
      const hh = ((h + 11) % 12) + 1;
      return `${hh}:${String(m).padStart(2, '0')} ${ampm}`;
    }

    function nextFireTime(task) {
      const [h, m] = task.time.split(':').map(Number);
      const now = new Date();
      now.setMilliseconds(0);
      now.setMinutes(now.getMinutes() + 1);
      let target = new Date(now);
      target.setHours(h, m, 0, 0);
      if (target <= now) target.setDate(target.getDate() + 1);
      return target;
    }

    function showNotification(task) {
      if (!('Notification' in window)) return;
      if (Notification.permission !== 'granted') {
        Notification.requestPermission().then(() => showNotification(task));
        return;
      }
      const n = new Notification('Task Scheduler', {
        body: `Due at ${task.time} — ${task.js}`,
        icon: 'icon48.png'
      });
      n.onclick = () => window.focus();
    }

    function executeJS(task) {
      try {
        // Create a sandboxed function from the JS string
        const fn = new Function('location', 'console', task.js);
        fn(window.location, window.console);
      } catch (err) {
        console.error('JS execution failed:', err);
      }
    }

    function render() {
      const tasks = loadTasks();
      tasksEl.innerHTML = '';
      if (!tasks || tasks.length === 0) {
        emptyEl.style.display = 'block';
        return;
      }
      emptyEl.style.display = 'none';
      tasks.forEach((task) => {
        const row = document.createElement('div');
        row.className = 'task';
        row.innerHTML = `
          <div class="task-name">${escapeHtml(task.name)}</div>
          <div class="task-time">${escapeHtml(task.type)} at ${formatTime(new Date(task.time))}</div>
          <div class="task-js">${escapeHtml(task.js)}</div>
        `;
        tasksEl.appendChild(row);
      });
    }

    function escapeHtml(str) {
      return String(str).replace(/[&<>"']/g, (c) => ({
        '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
      }[c]));
    }

    function scheduleTask(task) {
      const fireAt = nextFireTime(task);
      if (!fireAt) return;
      const id = `task-${task.id}`;
      setTimeout(() => {
        showNotification(task);
        executeJS(task);
        if (task.type === 'daily') {
          scheduleTask(task);
        }
      }, fireAt.getTime() - Date.now());
    }

    form.addEventListener('submit', (e) => {
      e.preventDefault();
      const name = document.getElementById('name').value.trim();
      const time = document.getElementById('time').value;
      const type = document.getElementById('type').value;
      const js = document.getElementById('js').value.trim();
      if (!name || !time) return;

      const task = {
        id: Date.now().toString(),
        name,
        time,
        type,
        js
      };
      const tasks = loadTasks();
      saveTasks([...tasks, task]);
      scheduleTask(task);
      render();
      form.reset();
      document.getElementById('name').focus();
    });

    render();
  </script>
</body>
</html>
