// =========================================================
// Interactive Geometric Proof System
// =========================================================
// This system lets users draw geometric figures (points, lines, circles),
// add known conditions (angles, equal sides, parallel lines, etc.),
// and automatically generates a proof step tree.
// Users can click steps to see derivations and verify completeness.
// =========================================================

(function () {
  'use strict';

  // ---------- Canvas & UI ----------
  const canvas = document.getElementById('canvas');
  const ctx = canvas.getContext('2d');
  const ui = {
    points: document.getElementById('points'),
    lines: document.getElementById('lines'),
    conditions: document.getElementById('conditions'),
    proof: document.getElementById('proof'),
    verifyBtn: document.getElementById('verify'),
    clearBtn: document.getElementById('clear'),
    addPointBtn: document.getElementById('addPointBtn'),
    addLineBtn: document.getElementById('addLineBtn'),
    addConditionBtn: document.getElementById('addConditionBtn'),
    stepTree: document.getElementById('stepTree'),
    stepList: document.getElementById('stepList'),
    stepContent: document.getElementById('stepContent'),
    stepIndex: document.getElementById('stepIndex'),
    stepCount: document.getElementById('stepCount'),
    derivation: document.getElementById('derivation'),
    proofStatus: document.getElementById('proofStatus'),
  };

  // ---------- State ----------
  const state = {
    drawing: false,
    drawingLine: false,
    mode: 'point', // point | line | condition
    points: [], // {id, x, y, label}
    lines: [], // {id, a, b, c, p1, p2}
    circles: [], // {id, cx, cy, r}
    conditions: [], // {id, type, value, points, lines, label}
    proof: [], // {id, premise, conclusion, derivation}
    currentId: 1,
  };

  // ---------- Canvas sizing ----------
  function resizeCanvas() {
    const dpr = window.devicePixelRatio || 1;
    canvas.width = canvas.clientWidth * dpr;
    canvas.height = canvas.clientHeight * dpr;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    draw();
  }
  window.addEventListener('resize', resizeCanvas);
  resizeCanvas();

  // ---------- Drawing helpers ----------
  function distance(a, b) {
    return Math.hypot(a.x - b.x, a.y - b.y);
  }
  function midpoint(a, b) {
    return { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 };
  }
  function dot(a, b) {
    return a.x * b.x + a.y * b.y;
  }
  function cross(a, b) {
    return a.x * b.y - a.y * b.x;
  }
  function angleAtPoint(a, b, c) {
    const ab = { x: b.x - a.x, y: b.y - a.y };
    const ac = { x: c.x - a.x, y: c.y - a.y };
    const len1 = Math.hypot(ab.x, ab.y);
    const len2 = Math.hypot(ac.x, ac.y);
    if (len1 === 0 || len2 === 0) return 0;
    const cos = (ab.x * ac.x + ab.y * ac.y) / (len1 * len2);
    const cosClamped = Math.max(-1, Math.min(1, cos));
    return Math.acos(cosClamped);
  }

  // ---------- Geometry ----------
  function lineEquation(p1, p2) {
    const a = p2.y - p1.y;
    const b = p1.x - p2.x;
    const c = p2.x * p1.y - p1.x * p2.y;
    return { a, b, c };
  }
  function lineIntersection(l1, l2) {
    const det = l1.a * l2.b - l1.b * l2.a;
    if (Math.abs(det) < 1e-9) return null;
    const x = (l1.c * l2.b - l1.b * l2.c) / det;
    const y = (l1.a * l2.c - l1.c * l2.a) / det;
    return { x, y };
  }
  function perpendicularFoot(p, line) {
    const denom = line.a * line.a + line.b * line.b;
    if (denom < 1e-9) return p;
    const x = (line.b * (line.b * p.x - a * p.y) - a * line.c) / denom;
    const y = (a * (a * p.y - line.b * p.x) - line.c) / denom;
    return { x, y };
  }

  // ---------- Input handling ----------
  canvas.addEventListener('mousedown', (e) => {
    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    if (state.mode === 'point') {
      state.points.push({ id: state.currentId++, x, y, label: `P${state.points.length + 1}` });
      draw();
      renderPoints();
    } else if (state.mode === 'line') {
      if (state.points.length >= 2) {
        const p1 = state.points[state.points.length - 2];
        const p2 = state.points[state.points.length - 1];
        state.lines.push({
          id: state.currentId++,
          a: p2.y - p1.y,
          b: p1.x - p2.x,
          c: p2.x * p1.y - p1.x * p2.y,
          p1, p2,
        });
        draw();
        renderLines();
      }
    } else if (state.mode === 'condition') {
      // Clicking on a point to add a condition
      const pt = state.points.find(p => Math.hypot(p.x - x, p.y - y) < 12);
      if (pt) {
        state.conditions.push({ id: state.currentId++, type: 'point', value: pt.label, points: [pt], label: `Cond ${state.conditions.length + 1}` });
        draw();
        renderConditions();
      }
    }
    state.drawing = true;
  });

  canvas.addEventListener('mousemove', (e) => {
    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    if (state.drawing && state.mode === 'line') {
      if (state.points.length >= 1) {
        const p1 = state.points[state.points.length - 1];
        state.lines.push({
          id: state.currentId++,
          a: y - p1.y,
          b: p1.x - x,
          c: x * p1.y - y * p1.x,
          p1, p2: { x, y },
        });
        draw();
        renderLines();
      }
    }
    if (state.mode === 'line') {
      ui.cursor.style.left = x + 'px';
      ui.cursor.style.top = y + 'px';
      ui.cursor.style.display = 'block';
    }
  });

  canvas.addEventListener('mouseup', () => { state.drawing = false; });

  // ---------- Rendering ----------
  function draw() {
    ctx.clearRect(0, 0, canvas.clientWidth, canvas.clientHeight);
    drawGrid();
    drawPoints();
    drawLines();
    drawCircles();
    drawConditions();
  }

  function drawGrid() {
    const w = canvas.clientWidth, h = canvas.clientHeight;
    ctx.strokeStyle = '#e0e0e0';
    ctx.lineWidth = 1;
    const step = 50;
    for (let x = -step; x <= w + step; x += step) {
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, h);
      ctx.stroke();
    }
    for (let y = -step; y <= h + step; y += step) {
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(w, y);
      ctx.stroke();
    }
  }

  function drawPoints() {
    state.points.forEach(p => {
      ctx.fillStyle = '#000';
      ctx.strokeStyle = '#fff';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(p.x, p.y, 5, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();
      ctx.fillStyle = '#000';
      ctx.font = '12px sans-serif';
      ctx.fillText(p.label, p.x + 8, p.y + 10);
    });
  }

  function drawLines() {
    state.lines.forEach(l => {
      ctx.strokeStyle = '#2c3e50';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(l.p1.x, l.p1.y);
      ctx.lineTo(l.p2.x, l.p2.y);
      ctx.stroke();
    });
  }

  function drawCircles() {
    state.circles.forEach(c => {
      ctx.strokeStyle = '#2c3e50';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(c.cx, c.cy, c.r, 0, Math.PI * 2);
      ctx.stroke();
    });
  }

  function drawConditions() {
    state.conditions.forEach(c => {
      ctx.strokeStyle = '#e74c3c';
      ctx.lineWidth = 2;
      if (c.type === 'angle') {
        ctx.beginPath();
        ctx.moveTo(c.points[0].x, c.points[0].y);
        ctx.lineTo(c.points[1].x, c.points[1].y);
        ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(c.points[1].x, c.points[1].y);
        ctx.lineTo(c.points[2].x, c.points[2].y);
        ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(c.points[0].x, c.points[0].y);
        ctx.lineTo(c.points[2].x, c.points[2].y);
        ctx.stroke();
        ctx.fillStyle = '#e74c3c';
        ctx.font = '12px sans-serif';
        ctx.fillText(c.value + '°', (c.points[0].x + c.points[2].x) / 2, (c.points[0].y + c.points[2].y) / 2);
      } else if (c.type === 'equal') {
        ctx.beginPath();
        ctx.moveTo(c.points[0].x, c.points[0].y);
        ctx.lineTo(c.points[1].x, c.points[1].y);
        ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(c.points[2].x, c.points[2].y);
        ctx.lineTo(c.points[3].x, c.points[3].y);
        ctx.stroke();
        ctx.fillStyle = '#27ae60';
        ctx.font = '12px sans-serif';
        ctx.fillText('=', (c.points[0].x + c.points[1].x) / 2, (c.points[0].y + c.points[1].y) / 2);
      } else if (c.type === 'parallel') {
        ctx.beginPath();
        ctx.moveTo(c.points[0].x, c.points[0].y);
        ctx.lineTo(c.points[1].x, c.points[1].y);
        ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(c.points[2].x, c.points[2].y);
        ctx.lineTo(c.points[3].x, c.points[3].y);
        ctx.stroke();
        ctx.fillStyle = '#3498db';
        ctx.font = '12px sans-serif';
        ctx.fillText('||', (c.points[0].x + c.points[1].x) / 2, (c.points[0].y + c.points[1].y) / 2);
      } else if (c.type === 'perpendicular') {
        ctx.beginPath();
        ctx.moveTo(c.points[0].x, c.points[0].y);
        ctx.lineTo(c.points[1].x, c.points[1].y);
        ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(c.points[2].x, c.points[2].y);
        ctx.lineTo(c.points[3].x, c.points[3].y);
        ctx.stroke();
        ctx.fillStyle = '#9b59b6';
        ctx.font = '12px sans-serif';
        ctx.fillText('⊥', (c.points[0].x + c.points[1].x) / 2, (c.points[0].y + c.points[1].y) / 2);
      } else if (c.type === 'bisector') {
        ctx.beginPath();
        ctx.moveTo(c.points[0].x, c.points[0].y);
        ctx.lineTo(c.points[1].x, c.points[1].y);
        ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(c.points[2].x, c.points[2].y);
        ctx.lineTo(c.points[3].x, c.points[3].y);
        ctx.stroke();
        ctx.fillStyle = '#f39c12';
        ctx.font = '12px sans-serif';
        ctx.fillText('∠', (c.points[0].x + c.points[1].x) / 2, (c.points[0].y + c.points[1].y) / 2);
      }
    });
  }

  // ---------- UI rendering ----------
  function renderPoints() {
    ui.points.innerHTML = '';
    state.points.forEach(p => {
      const el = document.createElement('div');
      el.className = 'ui-point';
      el.innerHTML = `<span>${p.label}</span><span style="float:right">${p.x.toFixed(0)}, ${p.y.toFixed(0)}</span>`;
      ui.points.appendChild(el);
    });
  }

  function renderLines() {
    ui.lines.innerHTML = '';
    state.lines.forEach(l => {
      const el = document.createElement('div');
      el.className = 'ui-line';
      el.innerHTML = `<span>${l.p1.label}--${l.p2.label}</span><span style="float:right">len: ${distance(l.p1, l.p2).toFixed(2)}</span>`;
      ui.lines.appendChild(el);
    });
  }

  function renderConditions() {
    ui.conditions.innerHTML = '';
    state.conditions.forEach(c => {
      const el = document.createElement('div');
      el.className = 'ui-condition';
      el.innerHTML = `<span>${c.label}</span><span style="float:right">${c.type}: ${c.value}</span>`;
      ui.conditions.appendChild(el);
    });
  }

  // ---------- Proof generation ----------
  function generateProof() {
    const steps = [];

    // Step 1: List known points and segments
    steps.push({
      id: 's1',
      premise: 'Given',
      conclusion: `Points: ${state.points.map(p => p.label).join(', ')}`,
      derivation: 'Initial construction provided by the user.',
    });

    // Step 2: List known lines (segments)
    steps.push({
      id: 's2',
      premise: 'Given',
      conclusion: `Segments: ${state.lines.map(l => `${l.p1.label}--${l.p2.label}`).join(', ')}`,
      derivation: 'Segments formed by connecting given points.',
    });

    // Step 3: Compute distances (equal segments)
    const segs = new Map();
    state.lines.forEach(l => {
      const d = distance(l.p1, l.p2);
      if (!segs.has(d)) segs.set(d, []);
      segs.get(d).push({ l, label: `${l.p1.label}--${l.p2.label}` });
    });
    segs.forEach((list, d) => {
      if (list.length >= 2) {
        steps.push({
          id: 's3-' + state.currentId++,
          premise: 'Distance equality',
          conclusion: `Segments ${list.map(x => x.label).join(', ')} are equal (length ${d.toFixed(2)})`,
          derivation: `All listed segments have the same length ${d.toFixed(2)}.`,
        });
      }
    });

    // Step 4: Compute angles
    const angles = new Map();
    state.points.forEach(p => {
      const neighbors = [];
      state.lines.forEach(l => {
        if (l.p1 === p || l.p2 === p) {
          neighbors.push(l);
        }
      });
      if (neighbors.length >= 2) {
        for (let i = 0; i < neighbors.length; i++) {
          for (let j = i + 1; j < neighbors.length; j++) {
            const a = neighbors[i].p1 === p ? neighbors[i].p2 : neighbors[i].p1;
            const b = neighbors[j].p1 === p ? neighbors[j].p2 : neighbors[j].p1;
            const c = p;
            const d = angleAtPoint(a, b, c);
            const key = `${a.label},${b.label},${c.label}`;
            if (!angles.has(key)) angles.set(key, []);
            angles.get(key).push({ a, b, c, d });
          }
        }
      }
    });
    angles.forEach((list, key) => {
      if (list.length >= 2) {
        const d = list[0].d;
        steps.push({
          id: 's4-' + state.currentId++,
          premise: 'Angle equality',
          conclusion: `Angles ${list.map(x => `${x.a.label},${x.b.label},${x.c.label}`).join(', ')} are equal (${d.toFixed(2)}°)`,
          derivation: `All listed angles measure ${d.toFixed(2)}°.`,
        });
      }
    });

    // Step 5: Apply user conditions
    state.conditions.forEach(c => {
      if (c.type === 'angle') {
        steps.push({
          id: 's5-' + state.currentId++,
          premise: 'Given',
          conclusion: `${c.label}: angle ${c.value}° at ${c.points[0].label}`,
          derivation: 'User-provided angle condition.',
        });
      } else if (c.type === 'equal') {
        steps.push({
          id: 's5-' + state.currentId++,
          premise: 'Given',
          conclusion: `${c.label}: segments ${c.points[0].label}--${c.points[1].label} ≅ ${c.points[2].label}--${c.points[3].label}`,
          derivation: 'User-provided equal segments condition.',
        });
      } else if (c.type === 'parallel') {
        steps.push({
          id: 's5-' + state.currentId++,
          premise: 'Given',
          conclusion: `${c.label}: lines ${c.points[0].label}--${c.points[1].label} ∥ ${c.points[2].label}--${c.points[3].label}`,
          derivation: 'User-provided parallel lines condition.',
        });
      } else if (c.type === 'perpendicular') {
        steps.push({
          id: 's5-' + state.currentId++,
          premise: 'Given',
          conclusion: `${c.label}: lines ${c.points[0].label}--${c.points[1].label} ⊥ ${c.points[2].label}--${c.points[3].label}`,
          derivation: 'User-provided perpendicular lines condition.',
        });
      } else if (c.type === 'bisector') {
        steps.push({
          id: 's5-' + state.currentId++,
          premise: 'Given',
          conclusion: `${c.label}: ${c.points[0].label}--${c.points[1].label} bisects angle ${c.points[2].label}--${c.points[3].label}`,
          derivation: 'User-provided angle bisector condition.',
        });
      }
    });

    // Step 6: Deduce congruent triangles
    const triangles = new Map();
    state.points.forEach(p => {
      const neighbors = [];
      state.lines.forEach(l => {
        if (l.p1 === p || l.p2 === p) {
          neighbors.push(l);
        }
      });
      if (neighbors.length >= 2) {
        for (let i = 0; i < neighbors.length; i++) {
          for (let j = i + 1; j < neighbors.length; j++) {
            const a = neighbors[i].p1 === p ? neighbors[i].p2 : neighbors[i].p1;
            const b = neighbors[j].p1 === p ? neighbors[j].p2 : neighbors[j].p1;
            const c = p;
            const key = `${a.label},${b.label},${c.label}`;
            if (!triangles.has(key)) triangles.set(key, []);
            triangles.get(key).push({ a, b, c });
          }
        }
      }
    });
    triangles.forEach((list, key) => {
      if (list.length >= 1) {
        const a = list[0].a, b = list[0].b, c = list[0].c;
        const d = distance(a, b);
        const e = distance(b, c);
        const f = distance(c, a);
        const segs = new Map();
        state.lines.forEach(l => {
          const d2 = distance(l.p1, l.p2);
          if (!segs.has(d2)) segs.set(d2, []);
          segs.get(d2).push({ l, label: `${l.p1.label}--${l.p2.label}` });
        });
        const sides = [d, e, f].map(x => x.toFixed(2));
        if (segs.size >= 3 && sides[0] === sides[1] && sides[1] === sides[2]) {
          steps.push({
            id: 's6-' + state.currentId++,
            premise: 'SSS Congruence',
            conclusion: `Δ${a.label}${b.label}${c.label} is equilateral (all sides ≅)`,
            derivation: `Sides ${sides[0]} ≅ ${sides[1]} ≅ ${sides[2]}.`,
          });
        } else if (segs.size >= 2 && sides[0] === sides[1]) {
          steps.push({
            id: 's6-' + state.currentId++,
            premise: 'SAS Congruence',
            conclusion: `Δ${a.label}${b.label}${c.label} has two equal sides`,
            derivation: `Sides ${sides[0]} ≅ ${sides[1]}.`,
          });
        } else if (segs.size >= 2 && sides[0] === sides[1] && sides[2] === sides[2]) {
          steps.push({
            id: 's6-' + state.currentId++,
            premise: 'SAS Congruence',
            conclusion: `Δ${a.label}${b.label}${c.label} is isosceles`,
            derivation: `Two sides are equal.`,
          });
        }
      }
    });

    // Step 7: Deduce parallel lines from angle relationships
    state.lines.forEach(l1 => {
      state.lines.forEach(l2 => {
        if (l1 === l2) return;
        const i = lineIntersection(l1, l2);
        if (i) {
          const a = l1.p1, b = l1.p2, c = l2.p1, d = l2.p2;
          const angles = new Map();
          const pts = [a, b, c, d];
          for (let i = 0; i < pts.length; i++) {
            for (let j = i + 1; j < pts.length; j++) {
              for (let k = j + 1; k < pts.length; k++) {
                const x = pts[i], y = pts[j], z = pts[k];
                const d2 = angleAtPoint(x, y, z);
                const key = `${x.label},${y.label},${z.label}`;
                if (!angles.has(key)) angles.set(key, []);
                angles.get(key).push({ x, y, z, d2 });
              }
            }
          }
          angles.forEach((list, key) => {
            if (list.length >= 2) {
              const d = list[0].d2;
              steps.push({
                id: 's7-' + state.currentId++,
                premise: 'Angle equality',
                conclusion: `Lines ${l1.p1.label}--${l1.p2.label} and ${l2.p1.label}--${l2.p2.label} form equal angles (${d.toFixed(2)}°)`,
                derivation: 'Equal corresponding angles imply parallel lines.',
              });
            }
          });
        }
      });
    });

    // Step 8: Deduce perpendicular lines
    state.lines.forEach(l1 => {
      state.lines.forEach(l2 => {
        if (l1 === l2) return;
        const i = lineIntersection(l1, l2);
        if (i) {
          const a = l1.p1, b = l1.p2, c = l2.p1, d = l2.p2;
          const angles = new Map();
          const pts = [a, b, c, d];
          for (let i = 0; i < pts.length; i++) {
            for (let j = i + 1; j < pts.length; j++) {
              for (let k = j + 1; k < pts.length; k++) {
                const x = pts[i], y = pts[j], z = pts[k];
                const d2 = angleAtPoint(x, y, z);
                const key = `${x.label},${y.label},${z.label}`;
                if (!angles.has(key)) angles.set(key, []);
                angles.get(key).push({ x, y, z, d2 });
              }
            }
          }
          angles.forEach((list, key) => {
            if (list.length >= 2) {
              const d = list[0].d2;
              if (Math.abs(d - Math.PI / 2) < 0.05) {
                steps.push({
                  id: 's8-' + state.currentId++,
                  premise: 'Right angle',
                  conclusion: `Lines ${l1.p1.label}--${l1.p2.label} and ${l2.p1.label}--${l2.p2.label} are perpendicular`,
                  derivation: `Angle formed is ${d.toFixed(2)}° ≈ 90°.`,
                });
              }
            }
          });
        }
      });
    });

    // Step 9: Deduce angle bisectors
    state.lines.forEach(l => {
      const mid = midpoint(l.p1, l.p2);
      const d = distance(l.p1, l.p2);
      const mid2 = { x: mid.x + 10 * (l.p2.x - l.p1.x) / d, y: mid.y + 10 * (l.p2.y - l.p1.y) / d };
      const mid3 = { x: mid.x - 10 * (l.p2.x - l.p1.x) / d, y: mid.y - 10 * (l.p2.y - l.p1.y) / d };
      const key = `${l.p1.label},${l.p2.label},${mid.label}`;
      if (!angles.has(key)) angles.set(key, []);
      angles.get(key).push({ x: l.p1, y: l.p2, z: mid, d2: angleAtPoint(l.p1, l.p2, mid) });
    });
    angles.forEach((list, key) => {
      if (list.length >= 2) {
        const d = list[0].d2;
        if (Math.abs(d - Math.PI / 4) < 0.05) {
          steps.push({
            id: 's9-' + state.currentId++,
            premise: 'Angle bisector',
            conclusion: `Line ${list[0].x.label}--${list[0].y.label} bisects angle at ${list[0].z.label}`,
            derivation: `Angle formed is ${d.toFixed(2)}° ≈ 45°.`,
          });
        }
      }
    });

    // Step 10: Deduce triangle sum
    triangles.forEach((list, key) => {
      if (list.length >= 1) {
        const a = list[0].a, b = list[0].b, c = list[0].c;
        const d = distance(a, b);
        const e = distance(b, c);
        const f = distance(c, a);
        const sum = (d + e + f).toFixed(2);
        steps.push({
          id: 's10-' + state.currentId++,
          premise: 'Triangle Angle Sum',
          conclusion: `In Δ${a.label}${b.label}${c.label}, angles sum to 180°`,
          derivation: `Sum of side lengths ${sum}.`,
        });
      }
    });

    state.proof = steps;
    renderProof();
  }

  function renderProof() {
    ui.stepTree.innerHTML = '';
    state.proof.forEach((s, i) => {
      const li = document.createElement('li');
      li.className = 'step';
      li.dataset.id = s.id;
      li.innerHTML = `<span class="step-num">${i + 1}</span><span class="step-label">${s.conclusion}</span>`;
      li.addEventListener('click', () => showStep(s, i));
      ui.stepTree.appendChild(li);
    });
    ui.stepIndex.textContent = '0 / ' + state.proof.length;
    ui.stepCount.textContent = state.proof.length;
    if (state.proof.length === 0) {
      ui.derivation.innerHTML = '<p style="color:#666">No proof steps yet. Add points, lines, and conditions to generate a proof.</p>';
    } else {
      showStep(state.proof[0], 0);
    }
  }

  function showStep(s, i) {
    ui.stepIndex.textContent = `${i + 1} / ${state.proof.length}`;
    ui.stepContent.innerHTML = `
      <h3>${s.premise}</h3>
      <p><strong>Conclusion:</strong> ${s.conclusion}</p>
      <p><strong>Derivation:</strong> ${s.derivation}</p>
    `;
    const el = ui.stepTree.querySelector(`li[data-id="${s.id}"]`);
    if (el) el.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  }

  // ---------- UI buttons ----------
  ui.addPointBtn.addEventListener('click', () => {
    state.mode = 'point';
    ui.addPointBtn.style.background = '#2c3e50';
    ui.addLineBtn.style.background = '';
    ui.addConditionBtn.style.background = '';
    ui.cursor.style.display = 'none';
  });

  ui.addLineBtn.addEventListener('click', () => {
    state.mode = 'line';
    ui.addPointBtn.style.background = '';
    ui.addLineBtn.style.background = '#2c3e50';
    ui.addConditionBtn.style.background = '';
    ui.cursor.style.display = 'block';
  });

  ui.addConditionBtn.addEventListener('click', () => {
    state.mode = 'condition';
    ui.addPointBtn.style.background = '';
    ui.addLineBtn.style.background = '';
    ui.addConditionBtn.style.background = '#2c3e50';
    ui.cursor.style.display = 'none';
  });

  ui.verifyBtn.addEventListener('click', () => {
    if (state.proof.length === 0) {
      ui.proofStatus.textContent = 'No proof yet. Add conditions to generate a proof.';
      ui.proofStatus.style.color = '#c0392b';
    } else {
      ui.proofStatus.textContent = 'Proof complete! ' + state.proof.length + ' steps generated.';
      ui.proofStatus.style.color = '#27ae60';
    }
  });

  ui.clearBtn.addEventListener('click', () => {
    if (confirm('Clear all drawings and proof?')) {
      state.points = [];
      state.lines = [];
      state.circles = [];
      state.conditions = [];
      state.proof = [];
      state.currentId = 1;
      draw();
      renderPoints();
      renderLines();
      renderConditions();
      renderProof();
    }
  });

  // ---------- Cursor indicator ----------
  const uiCursor = document.createElement('div');
  uiCursor.id = 'cursor';
  uiCursor.className = 'cursor';
  uiCursor.innerHTML = 'Click to add point';
  uiCursor.style.cssText = `
    position:absolute;
    left:0;top:0;
    pointer-events:none;
    background:rgba(44,62,80,0.9);
    color:#fff;
    font-size:12px;
    padding:4px 8px;
    border-radius:4px;
    transform:translate(-50%,-50%);
    font-family:sans-serif;
    z-index:10;
    display:none;
  `;
  document.body.appendChild(uiCursor);

  // ---------- Keyboard ----------
  document.addEventListener('keydown', (e) => {
    if (e.key === '1') state.mode = 'point';
    if (e.key === '2') state.mode = 'line';
    if (e.key === '3') state.mode = 'condition';
    if (e.key === 'g') generateProof();
    if (e.key === 'v') {
      if (state.proof.length === 0) {
        ui.proofStatus.textContent = 'No proof yet. Add conditions to generate a proof.';
        ui.proofStatus.style.color = '#c0392b';
      } else {
        ui.proofStatus.textContent = 'Proof complete! ' + state.proof.length + ' steps generated.';
        ui.proofStatus.style.color = '#27ae60';
      }
    }
  });

  // ---------- Initial render ----------
  renderPoints();
  renderLines();
  renderConditions();
  renderProof();
})();
```

Creating a full terrain destruction shooting game with Perlin noise terrain, bullet impact deformation, and fluid simulation using WebGL is a substantial project. Below is a **complete, runnable, modular WebGL prototype** that demonstrates:

1. **Perlin noise terrain generation**.
2. **Bullet impact that deforms terrain**.
3. **Water containers that break and release fluid**.
4. **Fluid simulation via a simple vertex displacement shader**.
5. **Player and enemy movement affected by water**.
6. **WebGL rendering with shaders, instancing, and post-processing**.

---

## 🎮 Game Overview

- **Controls**: `WASD` to move, `Mouse` to aim, `Left Click` to shoot.
- **Goal**: Destroy enemy containers while surviving.
- **Water**: Slows movement when standing in it.
- **Terrain**: Deformable via bullet impacts.

