### 1. `db.js` — SQLite Database

```javascript
// db.js
const sqlite3 = require('sqlite3').verbose();
const path = require('path');

const DB_PATH = path.resolve(__dirname, '../data/rooms.db');

const db = new sqlite3.Database(DB_PATH);

// Create tables
db.serialize(() => {
  db.run(`
    CREATE TABLE IF NOT EXISTS rooms (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL UNIQUE,
      capacity INTEGER NOT NULL,
      description TEXT
    )
  `);

  db.run(`
    CREATE TABLE IF NOT EXISTS reservations (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      room_id INTEGER NOT NULL,
      user_id TEXT NOT NULL,
      date TEXT NOT NULL,
      start_time TEXT NOT NULL,
      end_time TEXT NOT NULL,
      status TEXT DEFAULT 'pending',
      created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
      updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )
  `);

  db.run(`
    CREATE TABLE IF NOT EXISTS users (
      id TEXT PRIMARY KEY,
      username TEXT NOT NULL,
      role TEXT NOT NULL CHECK(role IN ('user', 'admin')),
      email TEXT NOT NULL,
      password TEXT NOT NULL
    )
  `);

  db.run(`
    CREATE TABLE IF NOT EXISTS sessions (
      session_id TEXT PRIMARY KEY,
      user_id TEXT NOT NULL,
      expires_at TIMESTAMP NOT NULL
    )
  `);
});

const Room = {
  get: (id) => new Promise((resolve, reject) => {
    db.get('SELECT * FROM rooms WHERE id = ?', [id], (err, row) => {
      if (err) return reject(err);
      resolve(row);
    });
  }),
  list: () => new Promise((resolve) => {
    db.all('SELECT * FROM rooms', [], resolve);
  }),
  listAvailable: (date, start, end) => new Promise((resolve) => {
    db.all(`
      SELECT r.* FROM rooms r
      LEFT JOIN reservations res
        ON r.id = res.room_id
        AND res.date = ? AND res.start_time = ? AND res.end_time = ?
        AND res.status IN ('pending', 'confirmed')
      WHERE res.id IS NULL
    `, [date, start, end], resolve);
  }),
  reserve: (room_id, user_id, date, start, end) => new Promise((resolve, reject) => {
    db.run(
      'INSERT INTO reservations (room_id, user_id, date, start_time, end_time, status) VALUES (?, ?, ?, ?, ?, ?)',
      [room_id, user_id, date, start, end, 'pending'],
      function(err) {
        if (err) return reject(err);
        resolve(this.lastID);
      }
    );
  }),
  cancel: (id) => new Promise((resolve) => {
    db.run('UPDATE reservations SET status = "cancelled", updated_at = CURRENT_TIMESTAMP WHERE id = ?', [id], resolve);
  }),
  approve: (id) => new Promise((resolve) => {
    db.run('UPDATE reservations SET status = "confirmed", updated_at = CURRENT_TIMESTAMP WHERE id = ?', [id], resolve);
  }),
  reject: (id) => new Promise((resolve) => {
    db.run('UPDATE reservations SET status = "rejected", updated_at = CURRENT_TIMESTAMP WHERE id = ?', [id], resolve);
  }),
  update: (id, data) => new Promise((resolve) => {
    const stmt = db.prepare('UPDATE reservations SET ? WHERE id = ?');
    stmt.run(data, id, resolve);
    stmt.finalize();
  }),
  listByUser: (user_id) => new Promise((resolve) => {
    db.all('SELECT * FROM reservations WHERE user_id = ? ORDER BY date, start_time', [user_id], resolve);
  }),
  listAll: () => new Promise((resolve) => {
    db.all(`
      SELECT r.*, res.id as reservation_id, res.status, res.date, res.start_time, res.end_time, res.created_at, res.updated_at
      FROM rooms r
      LEFT JOIN reservations res ON r.id = res.room_id
      ORDER BY r.name, res.date, res.start_time
    `, resolve);
  }),
  listPending: () => new Promise((resolve) => {
    db.all('SELECT * FROM reservations WHERE status = "pending"', resolve);
  }),
  countByRoom: (date, start, end) => new Promise((resolve) => {
    db.get(`
      SELECT COUNT(*) as count FROM reservations
      WHERE date = ? AND start_time = ? AND end_time = ? AND status IN ('pending', 'confirmed')
    `, [date, start, end], resolve);
  }),
};

const User = {
  create: (username, role, email, password) => new Promise((resolve, reject) => {
    db.run('INSERT INTO users (id, username, role, email, password) VALUES (?, ?, ?, ?, ?)',
      [username, username, role, email, password], (err) => {
        if (err) return reject(err);
        resolve();
      });
  }),
  get: (id) => new Promise((resolve, reject) => {
    db.get('SELECT * FROM users WHERE id = ?', [id], (err, row) => {
      if (err) return reject(err);
      resolve(row);
    });
  }),
  list: () => new Promise((resolve) => {
    db.all('SELECT * FROM users', resolve);
  }),
};

const Session = {
  create: (session_id, user_id, expires_at) => new Promise((resolve) => {
    db.run('INSERT INTO sessions (session_id, user_id, expires_at) VALUES (?, ?, ?)',
      [session_id, user_id, expires_at], resolve);
  }),
  destroy: (session_id) => new Promise((resolve) => {
    db.run('DELETE FROM sessions WHERE session_id = ?', [session_id], resolve);
  }),
  exists: (session_id) => new Promise((resolve) => {
    db.get('SELECT * FROM sessions WHERE session_id = ?', [session_id], (err, row) => {
      resolve(!err && row);
    });
  }),
};

module.exports = { Room, User, Session };
