});

// Login
app.post('/login', async (req, res) => {
  const { username, password } = req.body;
  try {
    const user = await db.User.get(username);
    if (!user) return res.status(401).json({ error: 'User not found' });
    if (user.password !== password) return res.status(401).json({ error: 'Invalid password' });
    const session_id = 'sess_' + Math.random().toString(36).slice(2, 10);
    await db.Session.create(session_id, username, new Date(Date.now() + 1000 * 60 * 60 * 24));
    req.session.user = username;
    req.session.session_id = session_id;
    res.json({ success: true, user: { id: username, role: user.role, email: user.email } });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Logout
app.post('/logout', (req, res) => {
  if (req.session.session_id) db.Session.destroy(req.session.session_id);
  req.session.destroy(() => res.json({ success: true }));
});

// SSE endpoint for real-time updates
