// routes/api.js
const express = require('express');
const router = express.Router();
const { Room, User, Session } = require('../db');

// Auth middleware
const requireAuth = (req, res, next) => {
  if (!req.session.user) return res.status(401).json({ error: 'Unauthorized' });
  next();
};

const requireAdmin = (req, res, next) => {
  if (!req.session.user || req.session.user.role !== 'admin') return res.status(403).json({ error: 'Forbidden' });
  next();
};

// Get available rooms for a date/time
router.get('/rooms/available', requireAuth, async (req, res) => {
  const { date, start, end } = req.query;
  if (!date || !start || !end) return res.status(400).json({ error: 'Missing date, start, end' });
  try {
    const rooms = await Room.listAvailable(date, start, end);
    res.json(rooms);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Reserve a room
router.post('/reserve', requireAuth, async (req, res) => {
  const { room_id, date, start, end } = req.body;
  if (!room_id || !date || !start || !end) return res.status(400).json({ error: 'Missing fields' });
  try {
    const count = await Room.countByRoom(date, start, end);
    if (count.rows && count.rows.count > 0) {
      return res.status(409).json({ error: 'Room is already reserved for this time' });
    }
    const id = await Room.reserve(room_id, req.session.user, date, start, end);
    res.json({ success: true, reservation_id: id });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Get user reservations
router.get('/reservations/me', requireAuth, async (req, res) => {
  try {
    const list = await Room.listByUser(req.session.user);
    res.json(list);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Admin: list all reservations
router.get('/reservations', requireAdmin, async (req, res) => {
  try {
    const list = await Room.listAll();
    res.json(list);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Admin: approve a reservation
router.post('/reservations/:id/approve', requireAdmin, async (req, res) => {
  const { id } = req.params;
  try {
    await Room.approve(id);
    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Admin: reject a reservation
router.post('/reservations/:id/reject', requireAdmin, async (req, res) => {
  const { id } = req.params;
  try {
    await Room.reject(id);
    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Admin: cancel a reservation
router.post('/reservations/:id/cancel', requireAdmin, async (req, res) => {
  const { id } = req.params;
  try {
    await Room.cancel(id);
    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Admin: update reservation
router.post('/reservations/:id', requireAdmin, async (req, res) => {
  const { id } = req.params;
  const { date, start, end, status } = req.body;
  try {
    await Room.update(id, { date, start, end, status });
