### 8. `public/script.js` — Shared Front-end Logic

```javascript
// script.js
(function () {
  'use strict';

  const API_BASE = '/api';
  const SESSION_KEY = 'meeting-room-system-session';

  // ---------- Utilities ----------
  function $$(sel, root = document) { return Array.from(root.querySelectorAll(sel)); }
  function $$1(sel, root = document) { return root.querySelector(sel); }

  function formatDate(d) {
    const pad = (n) => String(n).padStart(2, '0');
    return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
  }

  function formatTime(h, m) {
    const h24 = h % 24;
    const h12 = h24 >= 12 ? h24 - 12 : h24;
    const ampm = h24 >= 12 ? 'PM' : 'AM';
    return `${h12}:${pad(m)} ${ampm}`;
  }

  function pad(n) { return String(n).padStart(2, '0'); }

  function timeToMinutes(t) {
    const [h, m] = t.split(':').map(Number);
    return h * 60 + m;
  }

  // ---------- Session ----------
  async function getSession() {
    try {
      const raw = localStorage.getItem(SESSION_KEY);
      if (!raw) return null;
      const { session_id, user_id, expires_at } = JSON.parse(raw);
      const exists = await db.Session.exists(session_id);
      if (!exists) return null;
      if (new Date() > new Date(expires_at)) return null;
