        const start = btn.dataset.start;
        const end = btn.dataset.end;
        await handleReserve(roomId, date, start, end);
      });
    });

    // User: cancel
    $$1('#my-reservations').addEventListener('click', async (e) => {
      const btn = e.target.closest('[data-action="cancel"]');
      if (!btn) return;
      const id = btn.dataset.id;
      await handleCancel(id);
    });

    // Admin: cancel
    $$1('#tab-content').addEventListener('click', async (e) => {
      const btn = e.target.closest('[data-action="cancel"]');
      if (!btn) return;
      const id = btn.dataset.id;
      await handleCancel(id);
    });

    // Admin: approve / reject
    $$1('#tab-content').addEventListener('click', async (e) => {
      const btn = e.target.closest('[data-action="approve"]');
      if (btn) { await handleApprove(btn.dataset.id); return; }
      const btn2 = e.target.closest('[data-action="reject"]');
      if (btn2) { await handleReject(btn2.dataset.id); return; }
    });

    // Admin: tab switch
    $$('.tab').forEach((t) => {
      t.addEventListener('click', () => {
        const tab = t.dataset.tab;
        renderTab(tab, tab === 'all' ? db.Room.listAll() : db.Room.listPending());
      });
    });
  }

  // ---------- Init ----------
  async function init() {
    await initSession();
    bindEvents();
    if (window.location.pathname === '/user') {
      await renderUserDashboard();
    } else if (window.location.pathname === '/admin') {
      await renderAdminDashboard();
    }
