### 4. `server/utils/pdf.ts`

```ts
import * as pdf from 'pdf-lib';

export async function analyzePdf(buffer: Buffer): Promise<{
  pages: number | null;
  font: string | null;
  margins: string | null;
  size: number;
}> {
  try {
    const pdfDoc = await pdf.PDFDocument.load(buffer);
    const pages = pdfDoc.getPageCount();
    const fonts = new Set<string>();
    pdfDoc.getPages().forEach((page) => {
      page.getObjects().forEach((obj) => {
        if (obj instanceof pdf.PDFName) fonts.add(obj.name);
      });
    });
    const font = fonts.size > 0 ? fonts.values().next().value : null;

    // Simulate margin detection (real: use pdf-lib to read /Resources)
    const margins = pages > 0
      ? 'left: 1.25in, right: 1.25in, top: 1.0in, bottom: 1.0in'
      : null;

    return { pages, font, margins, size: buffer.length };
  } catch (err) {
    return { pages: null, font: null, margins: null, size: buffer.length };
  }
}
