### 5. `server/controllers/submission.ts`

```ts
import { Request, Response } from 'express';
import Submission from '../models/Submission';
import Paper from '../models/Paper';
import { uploadPdf } from '../utils/pdf';
import { isAuthenticated } from '../middleware/auth';

export const createSubmission = async (req: Request, res: Response) => {
  const { title, authors, abstract, keywords, blind } = req.body;
  const user = req.user;

  const paper = await Paper.create({
    title,
    authors,
    abstract,
    keywords,
    pdfBuffer: req.file.buffer,
    pdfMeta: await analyzePdf(req.file.buffer)
  });

  const submission = await Submission.create({
    title,
    authors,
    abstract,
    keywords,
    pdf: paper._id,
    status: 'submitted',
    blind: blind ?? true,
    reviewer: null
  });

  user.submissions.push(submission._id);
  await user.save();

  res.status(201).json(submission);
};

export const getSubmissions = async (req: Request, res: Response) => {
  const user = req.user;
  const submissions = await Submission.find({ _id: { $in: user.submissions } })
    .populate('pdf')
    .sort({ createdAt: -1 });
  res.json(submissions);
};

export const getSubmission = async (req: Request, res: Response) => {
  const submission = await Submission.findById(req.params.id)
    .populate('pdf')
    .populate('reviewer');
  if (!submission) return res.status(404).json({ error: 'Submission not found' });
  res.json(submission);
};

export const updateSubmission = async (req: Request, res: Response) => {
  const submission = await Submission.findByIdAndUpdate(
    req.params.id,
    { $set: req.body },
    { new: true }
  );
  if (!submission) return res.status(404).json({ error: 'Submission not found' });
  res.json(submission);
};
```

