import { Request, Response } from 'express';
import axios from 'axios';

export const detectPlagiarism = async (req: Request, res: Response) => {
  const { text } = req.body;
  const apiKey = process.env.TURNITIN_API_KEY;
  if (!apiKey) return res.status(500).json({ error: 'Turnitin key missing' });

  try {
    const response = await axios.post(
      'https://www.turnitin.com/api/v1/plagiarism',
      { text },
      { headers: { 'Authorization': `Bearer ${apiKey}` } }
    );
    const match = response.data?.match ?? 0;
    res.json({ plagiarism: match });
  } catch (err) {
    res.status(500).json({ error: 'Plagiarism check failed', message: err.message });
  }
};
```

