import { Submission } from '../../types/submission';

interface ProgressTrackerProps {
  submission: Submission;
}

export const ProgressTracker = ({ submission }: ProgressTrackerProps) => {
  const stages = [
    { label: 'Draft', done: submission.status === 'draft' },
    { label: 'Submitted', done: submission.status === 'submitted' },
    { label: 'Under Review', done: submission.status === 'reviewed' },
    { label: 'Accepted', done: submission.status === 'accepted' },
    { label: 'Rejected', done: submission.status === 'rejected' }
  ];

  return (
    <div className="progress-tracker">
      <h3>Submission Progress</h3>
      <div className="progress-bar">
        {stages.map((s, i) => (
          <div key={i} className="stage">
            <span className="stage-dot" style={{ backgroundColor: s.done ? '#22c55e' : '#cbd5e1' }}></span>
            <span className="stage-label">{s.label}</span>
            {i < stages.length - 1 && <span className="stage-line"></span>}
          </div>
        ))}
      </div>
    </div>
  );
};
