## ✅ Option 2: Self-Hosted Server + Puppeteer (Full Remote URL Capture)

This is the **real solution** for arbitrary remote URLs. You need a server (Node.js) with Puppeteer to render pages and serve screenshots.

### Step 1: Install Node.js + Puppeteer

```bash
npm init -y
npm install puppeteer
npm install express cors
```

### Step 2: Create `server.js`

```javascript
const express = require('express');
const cors = require('cors');
const puppeteer = require('puppeteer');
const path = require('path');
const fs = require('fs').promises;

const app = express();
app.use(cors());
app.use(express.json());
app.use(express.static('public'));

const PORT = process.env.PORT || 3001;

const browser = await puppeteer.launch({
  headless: 'new',
  args: [
    '--no-sandbox',
    '--disable-setuid-sandbox',
    '--disable-dev-shm-usage',
    '--single-process',
    '--no-first-run',
    '--no-zygote'
  ]
});

app.get('/api/screenshot', async (req, res) => {
  const { url, width = 1280, height = 800, filename = 'screenshot' } = req.query;
  if (!url) return res.status(400).json({ error: 'URL required' });

  try {
    const page = await browser.newPage();
    await page.setViewport({ width, height });
    await page.goto(url, { waitUntil: 'networkidle2', timeout: 60000 });

    const buffer = await page.screenshot({ encoding: 'buffer' });
    const ext = path.extname(filename) ? path.extname(filename) : '.png';
    const outputPath = path.join(__dirname, 'screenshots', `${filename}${ext}`);
    await fs.writeFile(outputPath, buffer);

    res.set('Content-Type', 'image/png');
    res.set('Content-Disposition', `attachment; filename="${filename}${ext}"`);
    res.send(buffer);
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: err.message });
  }
});

app.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

### Step 3: Create a simple client UI (same HTML as above, but with a different endpoint)

```html
<script>
