  const thumbCanvas = document.getElementById('thumbCanvas');
  const thumbCanvas2 = document.getElementById('thumbCanvas2');
  const statusEl = document.getElementById('status');
  const preview = document.getElementById('preview');

  let pageUrl = '';

  openBtn.addEventListener('click', () => {
    const url = urlInput.value.trim();
    if (!url) {
      statusEl.textContent = 'Please enter a URL first.';
      statusEl.className = 'status-error';
      statusEl.classList.add('visible');
      setTimeout(() => statusEl.classList.remove('visible'), 4000);
      return;
    }
    if (url.startsWith('http://') || url.startsWith('https://')) {
      window.location.href = url;
    } else {
      window.location.href = 'https://' + url;
    }
  });

  captureBtn.addEventListener('click', () => {
    if (!pageUrl) {
      statusEl.textContent = 'Open a page first, then click Capture.';
      statusEl.className = 'status-error';
      statusEl.classList.add('visible');
      setTimeout(() => statusEl.classList.remove('visible'), 4000);
      return;
    }
    statusEl.textContent = 'Capturing...';
