        const img = new Image();
        img.onload = () => ctx.drawImage(img, 0, 0, width, height);
        img.src = url;

        // Same for thumb2
        thumbCanvas2.width = width;
        thumbCanvas2.height = height;
        const ctx2 = thumbCanvas2.getContext('2d');
        const img2 = new Image();
        img2.onload = () => ctx2.drawImage(img2, 0, 0, width, height);
        img2.src = url;

        thumb.classList.remove('hidden');
        thumb2.classList.remove('hidden');
        statusEl.textContent = 'Screenshot captured! Click the thumbnail to download.';
        statusEl.classList.add('visible');
