    // Drag progress bar
    timelineInner.addEventListener('mousedown', (e) => {
      if(e.target.closest('.marker') || e.target.closest('.timeline-buffer') || e.target.closest('.timeline-playhead')) return;
      const rect = timeline.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const pct = Math.max(0, Math.min(1, x / rect.width));
      video.currentTime = pct * video.duration;
      updateProgress();
    });

    document.addEventListener('mousemove', onDragMove);
    document.addEventListener('mouseup', onDragEnd);

    // Keyboard
    document.addEventListener('keydown', (e) => {
      if(e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA') return;
      if(e.key === 'Enter' && state.editingId){
        e.preventDefault();
        saveBookmark();
      }else if(e.key === 'Escape'){
        if(state.editingId){
          cancelEdit();
        }else if(modal.classList.contains('show')){
          modal.classList.remove('show');
        }
      }else if(e.key === 'Delete' || e.key === 'Backspace'){
        if(state.activeId){
          deleteBookmark(state.activeId);
        }
      }
    });

    // Buttons
    btnAdd.addEventListener('click', openAddModal);
    btnPlay.addEventListener('click', () => video.paused ? video.play() : video.pause());
    btnExport.addEventListener('click', exportProject);
    btnImport.addEventListener('click', () => fileImport.click());
    fileImport.addEventListener('change', (e) => {
      const f = e.target.files[0];
      if(f){
        importProject(f);
      }
    });
    btnClear.addEventListener('click', () => {
      if(state.bookmarks.length === 0) return;
      if(confirm('Clear all bookmarks?')){
        state.bookmarks = [];
        saveState();
        render();
        showToast('All bookmarks cleared', 'success');
      }
    });
    search.addEventListener('input', (e) => {
      state.search = e.target.value.toLowerCase();
      render();
    });

    modalClose.addEventListener('click', () => modal.classList.remove('show'));
    modalCancel.addEventListener('click', () => modal.classList.remove('show'));
    modalSave.addEventListener('click', saveBookmark);
    modal.addEventListener('click', (e) => {
      if(e.target === modal) modal.classList.remove('show');
    });
  }

  function onDragMove(e){
    if(!state.draggingId) return;
    const rect = timeline.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const pct = Math.max(0, Math.min(1, x / rect.width));
    const m = document.querySelector(`.marker[data-id="${state.draggingId}"]`);
    if(m){
      m.style.left = (pct * 100) + '%';
      const idx = state.bookmarks.findIndex(b => b.id === state.draggingId);
      if(idx >= 0){
        state.bookmarks[idx].time = pct * video.duration;
        renderMarkers();
      }
    }
  }

  function onDragEnd(){
    if(state.draggingId){
      state.draggingId = null;
      $$('.marker').forEach(m => m.classList.remove('dragging'));
      document.removeEventListener('mousemove', onDragMove);
      document.removeEventListener('mouseup', onDragEnd);
    }
  }

  // ---------- Bookmarks ----------
  function addBookmark(time){
    const id = 'b_' + Date.now() + '_' + Math.random().toString(36).slice(2,7);
    state.bookmarks.push({
      id,
      title: 'Bookmark',
      note: '',
      thumb: null,
      time,
    });
    state.activeId = id;
    saveState();
    render();
    showToast('Bookmark added at ' + formatTime(time), 'success');
  }

  function deleteBookmark(id){
    if(!confirm('Delete this bookmark?')){
      return;
    }
    state.bookmarks = state.bookmarks.filter(b => b.id !== id);
    if(state.activeId === id) state.activeId = null;
    if(state.editingId === id) state.editingId = null;
    saveState();
    render();
    showToast('Bookmark deleted', 'success');
  }

  function editBookmark(id){
    const b = state.bookmarks.find(x => x.id === id);
    if(!b) return;
    state.editingId = id;
    state.editingTitle = b.title;
    state.editingNote = b.note;
    state.editingThumb = b.thumb;
    state.editingTime = b.time;
    openAddModal();
  }

  function saveBookmark(){
    if(!state.editingId) return;
    const b = state.bookmarks.find(x => x.id === state.editingId);
    if(b){
      b.title = state.editingTitle.trim() || 'Bookmark';
      b.note = state.editingNote.trim();
      b.thumb = state.editingThumb;
      b.time = state.editingTime;
    }
    state.editingId = null;
    modal.classList.remove('show');
    render();
    showToast('Bookmark saved', 'success');
  }

  function cancelEdit(){
    state.editingId = null;
    modal.classList.remove('show');
  }

  function openAddModal(){
    modalTitle.textContent = state.editingId ? 'Edit Bookmark' : 'Add Bookmark';
    modalBody.innerHTML = `
      <div class="dropzone" id="thumbDrop">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${iconUpload}</svg>
        <span>Click or drop an image to upload a thumbnail</span>
      </div>
      <label class="form-label">Title <input type="text" id="fTitle" value="${state.editingId ? state.editingTitle : ''}" placeholder="e.g. Scene 1" /></label>
      <label class="form-label">Note <textarea id="fNote" placeholder="Optional note...">${state.editingId ? state.editingNote : ''}</textarea></label>
    `;
    const drop = $('#thumbDrop');
    drop.addEventListener('click', () => document.getElementById('fThumb').click());
    drop.addEventListener('dragover', (e) => { e.preventDefault(); drop.classList.add('drag'); });
    drop.addEventListener('dragleave', () => drop.classList.remove('drag'));
    drop.addEventListener('drop', (e) => {
      e.preventDefault();
      drop.classList.remove('drag');
      const file = e.dataTransfer.files[0];
      if(file && file.type.startsWith('image/')){
        state.editingThumb = file;
        showToast('Thumbnail selected', 'success');
      }
    });
    $('#fThumb').addEventListener('change', (e) => {
      const f = e.target.files[0];
      if(f && f.type.startsWith('image/')){
        state.editingThumb = f;
        showToast('Thumbnail selected', 'success');
      }
    });
    $('#fTitle').addEventListener('input', (e) => state.editingTitle = e.target.value);
    $('#fNote').addEventListener('input', (e) => state.editingNote = e.target.value);
    modal.classList.add('show');
  }

  function jumpTo(id){
    const b = state.bookmarks.find(x => x.id === id);
    if(b) video.currentTime = b.time;
    state.activeId = id;
    render();
  }

  // ---------- Rendering ----------
  function render(){
    renderMarkers();
    renderList();
    updateActiveMarker();
  }

  function renderMarkers(){
    timelineMarkers.innerHTML = '';
    state.bookmarks.forEach(b => {
      const m = document.createElement('div');
      m.className = 'marker';
      m.dataset.id = b.id;
      m.style.left = ((b.time / video.duration) * 100) + '%';
      m.innerHTML = `
        <div class="m-text">${escapeHtml(b.title)}</div>
        <div class="m-thumb" style="background:#e2e8f0">
          ${b.thumb ? `<img src="${URL.createObjectURL(b.thumb)}" alt="" />` : ''}
        </div>
        <div class="m-note">${escapeHtml(b.note)}</div>
        <button class="m-delete" title="Delete" aria-label="Delete">
          ${iconTrash}
        </button>
      `;
      m.addEventListener('click', (e) => {
        if(e.target.closest('.m-delete')) return;
        jumpTo(b.id);
      });
      m.querySelector('.m-delete').addEventListener('click', (e) => {
        e.stopPropagation();
        deleteBookmark(b.id);
      });
      timelineMarkers.appendChild(m);
    });
  }

  function renderList(){
    const filtered = state.bookmarks.filter(b =>
      !state.search || b.title.toLowerCase().includes(state.search) || b.note.toLowerCase().includes(state.search)
    );
    bookmarksList.innerHTML = '';
    if(filtered.length === 0){
      emptyState.style.display = 'block';
      return;
    }
    emptyState.style.display = 'none';
    filtered.forEach(b => {
      const li = document.createElement('div');
      li.className = 'bookmark' + (b.id === state.activeId ? ' active' : '');
      li.innerHTML = `
        <div class="b-thumb">
          ${b.thumb ? `<img src="${URL.createObjectURL(b.thumb)}" alt="" />` : ''}
        </div>
        <div class="b-info">
          <div class="b-title">${escapeHtml(b.title)}</div>
          <div class="b-note">${escapeHtml(b.note)}</div>
        </div>
        <div class="b-time">${formatTime(b.time)}</div>
        <div class="b-actions">
          <button class="icon-btn" title="Edit" aria-label="Edit">${iconEdit}</button>
          <button class="icon-btn danger" title="Delete" aria-label="Delete">${iconTrash}</button>
        </div>
      `;
      li.addEventListener('click', (e) => {
        if(e.target.closest('.icon-btn')) return;
        jumpTo(b.id);
      });
      li.querySelector('.icon-btn').addEventListener('click', (e) => {
        e.stopPropagation();
        editBookmark(b.id);
      });
      li.querySelector('.icon-btn.danger').addEventListener('click', (e) => {
        e.stopPropagation();
        deleteBookmark(b.id);
      });
      bookmarksList.appendChild(li);
    });
  }

  function updateActiveMarker(){
    const active = state.activeId ? state.bookmarks.find(b => b.id === state.activeId) : null;
    $$('.bookmark').forEach(el => {
      el.classList.toggle('active', el.dataset.id === state.activeId);
    });
    if(active){
      timelineMarkers.querySelector(`.marker[data-id="${active.id}"]`)?.scrollIntoView({block:'center'});
    }
  }

  function updateVideoInfo(){
    const dur = video.duration || 0;
    const pct = dur ? (video.currentTime / dur) * 100 : 0;
    timelineProgress.style.width = pct + '%';
    timelinePlayhead.style.left = (pct) + '%';
    videoInfo.textContent = formatTime(video.currentTime) + ' / ' + formatTime(dur) + ' · ' + Math.round(pct) + '%';
  }

  function updateProgress(){
    if(!video.duration) return;
    const dur = video.duration;
    const pct = (video.currentTime / dur) * 100;
    timelineProgress.style.width = pct + '%';
    timelinePlayhead.style.left = pct + '%';
    // Move markers to match current time
    state.bookmarks.forEach(b => {
      const m = document.querySelector(`.marker[data-id="${b.id}"]`);
      if(m) m.style.left = ((b.time / dur) * 100) + '%';
    });
  }

  function formatTime(sec){
    if(!isFinite(sec) || sec < 0) sec = 0;
    const m = Math.floor(sec / 60);
    const s = Math.floor(sec % 60);
    return m + ':' + (s < 10 ? '0' : '') + s;
  }

  function escapeHtml(str){
    return String(str).replace(/[&<>"']/g, c => ({
      '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'
    }[c]));
  }

  // ---------- Export / Import ----------
  function exportProject(){
    const data = {
      version: 1,
      title: videoTitle.textContent,
      url: video.src,
      bookmarks: state.bookmarks.map(b => ({
        id: b.id,
        title: b.title,
        note: b.note,
        thumb: b.thumb ? b.thumb.name : null,
        time: b.time,
      })),
    };
    const blob = new Blob([JSON.stringify(data, null, 2)], {type:'application/json'});
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'video-bookmarks-' + Date.now() + '.json';
    a.click();
    URL.revokeObjectURL(url);
    showToast('Project exported', 'success');
  }

  function importProject(file){
    const reader = new FileReader();
    reader.onload = (e) => {
      try{
        const data = JSON.parse(e.target.result);
        if(data.version !== 1){
          showToast('Unsupported file version', 'error');
          return;
        }
        state.bookmarks = data.bookmarks.map(b => ({
          id: 'b_' + Date.now() + '_' + Math.random().toString(36).slice(2,7),
          title: b.title,
          note: b.note,
          thumb: b.thumb ? {name:b.thumb, type:'image/png'} : null,
          time: b.time,
        }));
        saveState();
        render();
        showToast('Project imported', 'success');
      }catch(err){
        showToast('Failed to import: ' + err.message, 'error');
      }
    };
    reader.readAsText(file);
  }

  // ---------- Toast ----------
  let toastTimer;
  function showToast(msg, type='info'){
    toast.textContent = msg;
    toast.className = 'toast show ' + (type || '');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => toast.classList.remove('show'), 2200);
  }

  // ---------- Boot ----------
  init();
})();
</script>
</body>
</html>
```

