```javascript
const express = require('express');
const cors = require('cors');
const bcrypt = require('bcryptjs');
const jwt = require('jsonwebtoken');
const dotenv = require('dotenv');

dotenv.config();

const app = express();
const PORT = process.env.PORT || 5001;

app.use(cors());
app.use(express.json());

// Mock database
const drones = [
  { id: 1, name: 'SkyDrone X1', model: 'X1', status: 'in-flight', battery: 65, altitude: 120, speed: 32, latitude: 37.7749, longitude: -122.4194, lastSeen: Date.now() - 30000 },
  { id: 2, name: 'SkyDrone X2', model: 'X2', status: 'landing', battery: 40, altitude: 20, speed: 15, latitude: 37.7750, longitude: -122.4195, lastSeen: Date.now() - 120000 },
  { id: 3, name: 'SkyDrone X3', model: 'X3', status: 'malfunction', battery: 10, altitude: 0, speed: 0, latitude: 37.7751, longitude: -122.4196, lastSeen: Date.now() - 180000 }
];

let nextId = 4;

const ADMIN_USER = { username: 'uavadmin', password: '321321' };

// Middleware
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'Access token required' });

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) return res.status(403).json({ error: 'Invalid or expired token' });
    req.user = user;
    next();
  });
};

const isAdmin = (req, res, next) => {
  if (req.user.role !== 'admin') return res.status(403).json({ error: 'Admin access required' });
  next();
};

// Auth routes
app.post('/api/auth/login', async (req, res) => {
  const { username, password } = req.body;
  if (username === ADMIN_USER.username && await bcrypt.compare(password, ADMIN_USER.password)) {
    const token = jwt.sign({ username, role: 'admin' }, process.env.JWT_SECRET, { expiresIn: '1h' });
    res.json({ token });
  } else {
    res.status(401).json({ error: 'Invalid credentials' });
  }
});

// Drone routes (admin only)
app.get('/api/drones', authenticateToken, isAdmin, (req, res) => {
  res.json(drones);
});

app.post('/api/drones', authenticateToken, isAdmin, async (req, res) => {
  const { name, model } = req.body;
  if (!name || !model) return res.status(400).json({ error: 'Name and model are required' });

  const newDrone = {
    id: nextId++,
    name,
    model,
    status: 'in-flight',
    battery: 100,
    altitude: 0,
    speed: 0,
    latitude: 37.7749,
    longitude: -122.4194,
    lastSeen: Date.now()
  };
  drones.push(newDrone);
  res.status(201).json(newDrone);
});

app.put('/api/drones/:id', authenticateToken, isAdmin, (req, res) => {
  const id = parseInt(req.params.id);
  const drone = drones.find(d => d.id === id);
  if (!drone) return res.status(404).json({ error: 'Drone not found' });

  const update = req.body;
  if (update.status) drone.status = update.status;
  if (update.battery !== undefined) drone.battery = update.battery;
  if (update.altitude !== undefined) drone.altitude = update.altitude;
  if (update.speed !== undefined) drone.speed = update.speed;
  if (update.latitude !== undefined) drone.latitude = update.latitude;
  if (update.longitude !== undefined) drone.longitude = update.longitude;
  if (update.lastSeen !== undefined) drone.lastSeen = update.lastSeen;

  res.json(drone);
});

app.delete('/api/drones/:id', authenticateToken, isAdmin, (req, res) => {
  const id = parseInt(req.params.id);
  drones.splice(drones.findIndex(d => d.id === id), 1);
  res.status(204).send();
});

// Simulated status update endpoint (employee can call this)
app.post('/api/drones/:id/simulate', (req, res) => {
  const id = parseInt(req.params.id);
  const drone = drones.find(d => d.id === id);
  if (!drone) return res.status(404).json({ error: 'Drone not found' });

  const action = req.body.action;
  if (action === 'takeoff') {
    drone.status = 'in-flight';
    drone.battery = 95;
    drone.altitude = 100;
    drone.speed = 25;
    drone.lastSeen = Date.now();
  } else if (action === 'land') {
    drone.status = 'landing';
    drone.battery = 45;
    drone.altitude = 50;
    drone.speed = 10;
    drone.lastSeen = Date.now();
  } else if (action === 'malfunction') {
    drone.status = 'malfunction';
    drone.battery = 5;
    drone.altitude = 0;
    drone.speed = 0;
    drone.lastSeen = Date.now();
  } else {
    return res.status(400).json({ error: 'Action must be takeoff, land, or malfunction' });
  }

  res.json(drone);
});

// Health check
app.get('/api/health', (req, res) => res.json({ status: 'ok' }));

app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
