import { defineStore } from 'pinia';

export const useDroneStore = defineStore('drone', {
  state: () => ({
    drones: []
  }),
  actions: {
    async fetchDrones() {
      try {
        const res = await fetch('/api/drones');
        this.drones = await res.json();
      } catch (e) {
        console.error(e);
      }
    },
    addDrone(drone) {
      this.drones.push(drone);
    },
    updateDrone(drone) {
      const idx = this.drones.findIndex(d => d.id === drone.id);
      if (idx >= 0) this.drones[idx] = drone;
    }
  }
});
