    login(token) {
      const payload = JSON.parse(atob(token.split('.')[1]));
      this.user = { username: payload.username, role: payload.role };
      localStorage.setItem('token', token);
    },
    logout() {
      this.user = null;
      localStorage.removeItem('token');
    }
  }
});
