<script>
/* =========================================================
   Subtitle Generator
   ========================================================= */

const $ = (id) => document.getElementById(id);
const video = $('video');
const timeDisplay = $('timeDisplay');
const playBtn = $('playBtn');
const emptyState = $('emptyState');
const subtitleList = $('subtitleList');
const lineCount = $('lineCount');
const subtitleEditor = $('subtitleEditor');
const addLineBtn = $('addLineBtn');
const togglePlayBtn = $('togglePlayBtn');
const exportBtn = $('exportBtn');
const mergeBtn = $('mergeBtn');

const state = {
  subtitles: [],
  nextId: 1,
  playing: false,
  playingInterval: null,
  style: {
    fontFamily: "'Arial', sans-serif",
    fontSize: 24,
    fontColor: '#ffffff',
    bgColor: '#000000',
    lineHeight: 1.4,
  },
};

// ---------- Utilities ----------
function fmtTime(sec) {
  if (!isFinite(sec) || sec < 0) sec = 0;
  const h = Math.floor(sec / 3600);
  const m = Math.floor((sec % 3600) / 60);
  const s = Math.floor(sec % 60);
  const ms = Math.floor((sec - Math.floor(sec)) * 1000);
  return `${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')},${String(ms).padStart(3,'0')}`;
}

function parseTime(str) {
  const m = str.trim().match(/:(\d{1,2}):(\d{1,2}):(\d{1,2}),(\d{3})/);
  if (!m) return NaN;
  const h = parseInt(m[1],10) || 0;
  const mm = parseInt(m[2],10);
  const ss = parseInt(m[3],10);
  const ms = parseInt(m[4],10);
  return h * 3600 + mm * 60 + ss + ms / 1000;
}

function parseTextLine(line) {
  const match = line.match(/^(.+?)(?:\s*-->.*|$)/);
  return match ? match[1].trim() : '';
}

function formatLine(line) {
  const text = parseTextLine(line);
  if (!text) return line;
  return `${fmtTime(line.start)} --> ${fmtTime(line.end)}\n${text}\n`;
}

function escapeVTT(str) {
  return str.replace(/"/g, '&quot;').replace(/(\r\n|\n|\r)/gm, ' ');
}

function showToast(msg) {
  let t = document.querySelector('.toast');
  if (!t) {
    t = document.createElement('div');
    t.className = 'toast';
    document.body.appendChild(t);
  }
  t.textContent = msg;
  t.classList.add('show');
  clearTimeout(showToast._t);
  showToast._t = setTimeout(() => t.classList.remove('show'), 2200);
}

// ---------- Video sync ----------
function updatePlayState() {
  state.playing = video.paused;
  playBtn.textContent = state.playing ? '▶ Play' : '❚❚ Pause';
  playBtn.setAttribute('aria-label', state.playing ? 'Play' : 'Pause');
}
video.addEventListener('play', updatePlayState);
video.addEventListener('pause', updatePlayState);

playBtn.addEventListener('click', () => {
  if (video.paused) video.play();
  else video.pause();
});

video.addEventListener('timeupdate', () => {
  timeDisplay.textContent = `${fmtTime(video.currentTime)} / ${fmtTime(video.duration)}`;
});

// ---------- Subtitles ----------
function addSubtitle() {
  const text = subtitleEditor.value.trim();
  if (!text) return;
  const parts = text.split(/\n\n+/);
  const newLines = [];
  parts.forEach(p => {
    const trimmed = p.trim();
    if (!trimmed) return;
    // Try to parse existing timecode
    const m = trimmed.match(/^(\d{1,2}:\d{1,2}:\d{1,2},\d{3})\s*-->\s*(\d{1,2}:\d{1,2}:\d{1,2},\d{3})\s*$/);
    if (m) {
      const start = parseTime(m[1]);
      const end = parseTime(m[2]);
      if (!isNaN(start) && !isNaN(end)) {
        newLines.push({ id: state.nextId++, start, end, text: trimmed.replace(/^.*-->\s*/, '').trim() });
        return;
      }
    }
    // Auto-generate timecodes
    const start = (state.subtitles.length > 0 ? state.subtitles[state.subtitles.length - 1].end : 0) + 1;
    const end = start + 3;
    newLines.push({ id: state.nextId++, start, end, text: trimmed });
  });
  state.subtitles.push(...newLines);
  renderSubtitles();
  subtitleEditor.value = '';
  showToast(`Added ${newLines.length} ${newLines.length === 1 ? 'line' : 'lines'}`);
}

addLineBtn.addEventListener('click', addSubtitle);

togglePlayBtn.addEventListener('click', () => {
  if (video.paused) video.play();
  else video.pause();
});

// ---------- Render ----------
function renderSubtitles() {
  const lines = state.subtitles.map(l => ({
    ...l,
    text: parseTextLine(l.text),
  }));
  emptyState.style.display = lines.length === 0 ? 'block' : 'none';
  lineCount.textContent = `${lines.length} line${lines.length === 1 ? '' : 's'}`;
  subtitleList.innerHTML = lines.map((l, i) => `
    <div class="subtitle-line" data-id="${l.id}">
      <span class="time">${fmtTime(l.start)} → ${fmtTime(l.end)}</span>
      <span class="text">${escapeVTT(l.text)}</span>
      <span class="del" title="Delete">✕</span>
      <span class="edit" title="Edit">✎</span>
    </div>
  `).join('');

  subtitleList.querySelectorAll('.del').forEach(el => {
    el.addEventListener('click', () => {
      const id = parseInt(el.parentElement.dataset.id);
      state.subtitles = state.subtitles.filter(s => s.id !== id);
      renderSubtitles();
      showToast('Line deleted');
    });
  });

  subtitleList.querySelectorAll('.edit').forEach(el => {
    el.addEventListener('click', () => {
      const id = parseInt(el.parentElement.dataset.id);
      const line = state.subtitles.find(s => s.id === id);
      if (!line) return;
      const newText = prompt('Edit subtitle:', line.text);
      if (newText !== null) {
        line.text = newText;
        renderSubtitles();
        showToast('Line updated');
      }
    });
  });
}

// ---------- Style ----------
['fontFamily', 'fontSize', 'fontColor', 'bgColor', 'lineHeight'].forEach(id => {
  $('id').addEventListener('input', e => {
    state.style[id] = e.target.value;
    renderSubtitles();
  });
});

// ---------- Export ----------
function exportVTT() {
  if (state.subtitles.length === 0) {
    showToast('No subtitles to export');
    return;
  }
  const header = `WEBVTT\n\n`;
  const body = state.subtitles.map(l => {
    const text = parseTextLine(l.text);
    return `${fmtTime(l.start)} --> ${fmtTime(l.end)}\n${escapeVTT(text)}\n`;
  }).join('\n');
  const blob = new Blob([header + body], { type: 'text/vtt;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `subtitles.vtt`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 1000);
  showToast('VTT exported');
}

exportBtn.addEventListener('click', exportVTT);

// ---------- Merge Video ----------
async function mergeVideo() {
  if (state.subtitles.length === 0) {
    showToast('Add subtitles first');
    return;
  }
  if (!video.src) {
    showToast('Upload a video first');
    return;
  }
  if (video.duration === Infinity || video.duration === 0) {
    showToast('Video duration unavailable');
    return;
  }

  // Build WebVTT track
  const header = `WEBVTT\n\n`;
  const body = state.subtitles.map(l => {
    const text = parseTextLine(l.text);
    return `${fmtTime(l.start)} --> ${fmtTime(l.end)}\n${escapeVTT(text)}\n`;
  }).join('\n');
  const vttBlob = new Blob([header + body], { type: 'text/vtt;charset=utf-8' });
  const vttUrl = URL.createObjectURL(vttBlob);

  // Create merged WebM using MediaRecorder (simulated)
  try {
    const stream = video.captureStream && video.captureStream ? video.captureStream() : video.mozCaptureStream();
    if (!stream) throw new Error('Media stream not available');

    const mime = navigator.mediaDevices && navigator.mediaDevices.getSupportedConstraints && navigator.mediaDevices.getSupportedConstraints().encoderConfig
      ? 'video/webm;codecs=vp9,opus'
      : 'video/webm';

    const options = { mimeType: mime, bitsPerSecond: 2000000 };
    const recorder = new MediaRecorder(stream, options);

    const chunks = [];
    recorder.ondataavailable = e => { if (e.data && e.data.size) chunks.push(e.data); };

    const tracks = stream.getVideoTracks();
    const track = tracks[0] || tracks[1] || null;
    const trackLabel = track ? track.label : 'unknown';

    recorder.onstop = async () => {
      const blob = new Blob(chunks, { type: mime });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `video-${trackLabel}.webm`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      setTimeout(() => URL.revokeObjectURL(url), 1000);
      showToast('Merged video exported');
    };

    // Start recording
    recorder.start();
    await new Promise(r => setTimeout(r, 500));

    // Simulate adding subtitles as a WebVTT track via cue API
    video.textTracks && video.textTracks.forEach(t => t.mode = 'showing');

    // Stop after a short clip
    setTimeout(() => {
      recorder.stop();
    }, 10000);
  } catch (err) {
    showToast('Merge failed: ' + err.message);
  }
}

mergeBtn.addEventListener('click', mergeVideo);

// ---------- Keyboard shortcuts ----------
document.addEventListener('keydown', (e) => {
  if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') {
    e.preventDefault();
    addSubtitle();
  }
  if ((e.ctrlKey || e.metaKey) && e.shiftKey && e.key === 'Enter') {
    e.preventDefault();
    togglePlayBtn.click();
  }
});

// ---------- Upload ----------
const dropZone = document.querySelector('.editor-panel');
['dragenter', 'dragover'].forEach(ev => {
  dropZone.addEventListener(ev, e => {
    e.preventDefault(); e.stopPropagation();
    dropZone.style.borderColor = 'var(--accent)';
  });
});
['dragleave', 'drop'].forEach(ev => {
  dropZone.addEventListener(ev, e => {
    e.preventDefault(); e.stopPropagation();
    dropZone.style.borderColor = '';
  });
});
dropZone.addEventListener('drop', e => {
  const files = e.dataTransfer.files;
  if (files.length) handleFile(files[0]);
});
['change'].forEach(ev => {
  const input = document.createElement('input');
  input.type = 'file';
  input.accept = 'video/*';
  input.multiple = false;
  input.addEventListener('change', e => {
    if (e.target.files.length) handleFile(e.target.files[0]);
  });
  dropZone.appendChild(input);
  input.click();
});

function handleFile(file) {
  if (!file.type.startsWith('video/')) {
    showToast('Please upload a video file');
    return;
  }
  const url = URL.createObjectURL(file);
  video.src = url;
  video.load();
  showToast(`Loaded ${file.name}`);
}
</script>
</body>
</html>
