## 🛒 Cart Hook

```javascript
// hooks/useCart.jsx
import { useState, useEffect } from 'react';

export const useCart = () => {
  const [items, setItems] = useState(() => {
    try { return JSON.parse(localStorage.getItem('rl_cart') || '[]'); }
    catch { return []; }
  });

  const add = (product) => {
    const existing = items.find(i => i.id === product.id);
    if (existing) {
      existing.quantity = (existing.quantity || 1) + 1;
    } else {
      items.push({ ...product, quantity: 1 });
    }
    localStorage.setItem('rl_cart', JSON.stringify(items));
    setItems([...items]);
  };

  const remove = (id) => {
    setItems(items.filter(i => i.id !== id));
    localStorage.setItem('rl_cart', JSON.stringify(items));
  };

  const updateQuantity = (id, delta) => {
    const item = items.find(i => i.id === id);
    if (!item) return;
    item.quantity = Math.max(1, item.quantity + delta);
    localStorage.setItem('rl_cart', JSON.stringify(items));
    setItems([...items]);
  };

  const negotiate = (id, offer) => {
    const item = items.find(i => i.id === id);
    if (!item) return;
    item.negotiation.buyerOffer = offer;
    item.negotiation.status = 'pending';
    localStorage.setItem('rl_cart', JSON.stringify(items));
    setItems([...items]);
    showToast(`Negotiation started: ${offer} for ${item.name}`);
  };

  const completeNegotiation = (id) => {
    const item = items.find(i => i.id === id);
    if (!item || !item.negotiation.buyerOffer) return;
    item.negotiation.status = 'completed';
    localStorage.setItem('rl_cart', JSON.stringify(items));
    setItems([...items]);
    showToast('Deal completed! Redirecting to payment...');
    setTimeout(() => navigateToPayment(), 1200);
  };

  const navigateToPayment = () => {
    window.location.hash = '#/payment';
  };

  const subtotal = items.reduce((sum, i) => sum + i.price * i.quantity, 0);
  const total = subtotal;

  return { items, add, remove, updateQuantity, negotiate, completeNegotiation, subtotal, total };
};
