### PaymentPage.jsx

```javascript
// pages/PaymentPage.jsx
import React, { useState } from 'react';
import { useCart } from '../hooks/useCart';
import { useAuth } from '../hooks/useAuth';
import { Link } from 'react-router-dom';

const PaymentPage = () => {
  const { user } = useAuth();
  const { items, remove, completeNegotiation } = useCart();
  const [cardNumber, setCardNumber] = useState('');
  const [expiry, setExpiry] = useState('');
  const [cvv, setCvv] = useState('');
  const [success, setSuccess] = useState(false);

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!user) return;
    const total = items.reduce((s, i) => s + i.price * i.quantity, 0);
    // Mark negotiations as completed
    items.forEach(item => {
      if (item.negotiation && item.negotiation.status === 'pending') {
        completeNegotiation(item.id);
      }
    });
    setSuccess(true);
  };

  if (success) {
    return (
      <div className="container mx-auto px-4 py-20 text-center">
        <div className="text-6xl mb-4">✓</div>
        <h1 className="text-2xl font-bold mb-4">Payment Successful!</h1>
        <p className="text-muted mb-4">Thank you for your purchase. A confirmation email has been sent.</p>
        <Link to="#/" className="bg-primary text-white px-4 py-2 rounded">Continue Shopping</Link>
      </div>
    );
  }

  return (
    <div className="container mx-auto px-4 py-6">
      <div className="max-w-lg mx-auto bg-surface-2 rounded-lg p-6">
        <h1 className="text-2xl font-bold mb-4">Payment</h1>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="flex gap-4">
            <input type="text" placeholder="Name on card" className="flex-1 bg-surface border border-border rounded px-3 py-2" />
            <input type="text" placeholder="Last 4 digits" className="flex-1 bg-surface border border-border rounded px-3 py-2" />
          </div>
          <input type="text" placeholder="Card number" value={cardNumber} onChange={e => setCardNumber(e.target.value)} className="w-full bg-surface border border-border rounded px-3 py-2" />
          <input type="text" placeholder="Expiry (MM/YY)" value={expiry} onChange={e => setExpiry(e.target.value)} className="w-full bg-surface border border-border rounded px-3 py-2" />
          <input type="text" placeholder="CVV" value={cvv} onChange={e => setCvv(e.target.value)} className="w-full bg-surface border border-border rounded px-3 py-2" />
          <button type="submit" className="w-full bg-primary text-white py-2 rounded font-medium">
            Pay ${items.reduce((s, i) => s + i.price * i.quantity, 0)}
          </button>
        </form>
      </div>
    </div>
  );
};
