// App.jsx
import React, { useEffect } from 'react';
import { BrowserRouter as Router, Route, Routes, HashRouter } from 'react-router-dom';
import { useAuth } from './hooks/useAuth';
import { useToggle } from './hooks/useToggle';
import { Header } from './components/Layout/Header';
import { Footer } from './components/Layout/Footer';
import { Home } from './pages/Home';
import { CartPage } from './pages/CartPage';
import { PaymentPage } from './pages/PaymentPage';
import { ProductPage } from './pages/ProductPage';
import { Login } from './pages/Login';
import { Register } from './pages/Register';
import { Protected } from './components/Auth/Protected';
import { Toast } from './components/Toast';

const App = () => {
  const { user } = useAuth();
  const { open, toggle } = useToggle();
  const [dark, setDark] = React.useState(true);

  useEffect(() => {
    document.documentElement.setAttribute('data-theme', dark ? 'dark' : 'light');
  }, [dark]);

  return (
    <HashRouter>
      <div className="App">
        <Header />
        <div className="min-h-screen">
          <Routes>
            <Route path="/" element={<Home />} />
            <Route path="/product/:id" element={<ProductPage />} />
            <Route path="/cart" element={<Protected><CartPage /></Protected>} />
            <Route path="/payment" element={<Protected><PaymentPage /></Protected>} />
            <Route path="/login" element={<Login />} />
            <Route path="/register" element={<Register />} />
          </Routes>
        </div>
        <Footer />
        {open && <Protected><div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-surface-2 p-8 rounded-lg shadow-lg">
            <h2 className="text-xl font-bold mb-4">Welcome, {user?.name}!</h2>
            <p className="text-muted mb-4">You need to sign in to negotiate or checkout.</p>
            <button onClick={toggle} className="bg-primary text-white px-4 py-2 rounded font-medium">Close</button>
          </div>
        </div></Protected>}
        <Toast />
      </div>
    </HashRouter>
  );
};

export default App;
```

