  border-radius: 10px;
  font-size: 15px;
  font-weight: 600;
  cursor: pointer;
  transition: transform 0.2s, background 0.2s, opacity 0.2s;
}

.btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.btn-primary {
  background: linear-gradient(135deg, #667eea, #764ba2);
  color: #fff;
}

.btn-primary:hover:not(:disabled) { transform: translateY(-1px); }

.btn-danger {
  background: linear-gradient(135deg, #ff6b6b, #c0392b);
  color: #fff;
}

.btn-danger:hover:not(:disabled) { transform: translateY(-1px); }

.btn-success {
  background: linear-gradient(135deg, #28c840, #108a38);
  color: #fff;
}

.btn-success:hover:not(:disabled) { transform: translateY(-1px); }

.btn-ghost {
  background: transparent;
  color: #fff;
  border: 1px solid rgba(255,255,255,0.2);
}

.btn-ghost:hover:not(:disabled) {
  background: rgba(255,255,255,0.1);
  border-color: rgba(255,255,255,0.35);
}

.progress {
  margin-top: 16px;
}

.progress-bar {
  height: 8px;
  background: rgba(255,255,255,0.15);
  border-radius: 999px;
  overflow: hidden;
  cursor: pointer;
}

.progress-bar::after {
  content: '';
  display: block;
  width: 0%;
  height: 100%;
  background: linear-gradient(90deg, #667eea, #764ba2);
  transition: width 0.1s linear;
}

.progress-time {
  text-align: center;
  font-size: 13px;
  color: rgba(255,255,255,0.7);
  margin-top: 4px;
}

.trim-controls {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin-top: 12px;
}

.trim-controls label {
  display: block;
  font-size: 13px;
  color: rgba(255,255,255,0.7);
  margin-bottom: 4px;
}

.trim-controls input {
  width: 100%;
  padding: 8px 12px;
  border-radius: 8px;
  border: 1px solid rgba(255,255,255,0.2);
  background: rgba(255,255,255,0.08);
  color: #fff;
  font-size: 14px;
}

.trim-controls input:focus {
  outline: none;
  border-color: #667eea;
  background: rgba(255,255,255,0.15);
}

.effects {
  display: grid;
  gap: 10px;
}

.effect-toggle {
  display: flex;
  align-items: center;
  gap: 10px;
  cursor: pointer;
  user-select: none;
}

.effect-toggle input {
  appearance: none;
  -webkit-appearance: none;
  width: 36px;
  height: 20px;
  background: rgba(255,255,255,0.15);
  border-radius: 999px;
  position: relative;
  transition: background 0.2s;
}

.effect-toggle input::after {
  content: '';
  position: absolute;
  top: 2px;
  left: 2px;
  width: 16px;
  height: 16px;
  background: #fff;
  border-radius: 50%;
  transition: transform 0.2s;
}

.effect-toggle input:checked {
  background: linear-gradient(135deg, #667eea, #764ba2);
}

.effect-toggle input:checked::after {
  transform: translateX(16px);
}

.effect-toggle span {
  font-size: 14px;
  color: rgba(255,255,255,0.85);
}

.effect-slider {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.effect-slider span {
  font-size: 13px;
  color: rgba(255,255,255,0.7);
}

.effect-slider input[type="range"] {
  width: 100%;
  accent-color: #667eea;
}

.waveform {
  height: 80px;
  background: rgba(255,255,255,0.05);
  border-radius: 10px;
  overflow: hidden;
  margin-top: 16px;
  position: relative;
}

.waveform canvas {
  display: block;
  width: 100%;
  height: 100%;
}

.export {
  display: flex;
  gap: 12px;
  margin-top: 16px;
}

#previewAudio {
  width: 100%;
  margin-top: 12px;
}

@media (max-width: 768px) {
  .panel {
    grid-template-columns: 1fr;
  }
}
