### 🧭 4. Factory + Plugin Registry

```dart
// payment_factory.dart
import 'package:fluttertoast/fluttertoast.dart';

class PaymentFactory {
  static final Map<String, PaymentService> _services = {
    'meituan': MeituanPayment(),
    'jd': JDPayment(),
    'pinduoduo': PDDPayment(),
    'didi': DidiPayment(),
    'ctrip': CtripPayment(),
  };

  static PaymentService? getService(String platform) {
    return _services[platform];
  }

  static Future<bool> pay({
    required String amount,
    required String orderId,
    required String platform,
    String? description,
  }) async {
    final service = getService(platform);
    if (service == null) {
      Fluttertoast.showToast(msg: 'Platform $platform not supported');
      return false;
    }
    return await service.pay(
      amount: amount,
      orderId: orderId,
      platform: platform,
      description: description,
    );
  }

  static Future<bool> cancelOrder(String orderId) async {
    final service = getService(orderId.split('_')[0]);
    if (service == null) return false;
    return await service.cancelOrder(orderId);
  }

  static Future<bool> deliverOrder(String orderId) async {
    final service = getService(orderId.split('_')[0]);
    if (service == null) return false;
    return await service.deliverOrder(orderId);
  }

  static Future<bool> expireOrder(String orderId) async {
    final service = getService(orderId.split('_')[0]);
    if (service == null) return false;
    return await service.expireOrder(orderId);
  }

  static Future<bool> successOrder(String orderId) async {
    final service = getService(orderId.split('_')[0]);
    if (service == null) return false;
    return await service.successOrder(orderId);
  }
}
```

