// payment_ui.dart
import 'package:flutter/material.dart';
import 'package:payment_factory/payment_factory.dart';

class PaymentScreen extends StatefulWidget {
  final String platform;
  final String amount;
  final String orderId;
  final String description;

  const PaymentScreen({
    Key? key,
    required this.platform,
    required this.amount,
    required this.orderId,
    required this.description,
  }) : super(key: key);

  @override
  State<PaymentScreen> createState() => _PaymentScreenState();
}

class _PaymentScreenState extends State<PaymentScreen> {
  String _status = 'Preparing...';
  bool _isLoading = false;

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text('Payment for ${widget.platform.toUpperCase()}'),
      ),
      body: Center(
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            Text(
              'Order: ${widget.orderId}',
              style: TextStyle(fontSize: 20),
            ),
            SizedBox(height: 20),
            Text(
              'Amount: ¥${widget.amount}',
              style: TextStyle(fontSize: 20),
            ),
            SizedBox(height: 20),
            Text(
              'Status: $_status',
              style: TextStyle(fontSize: 20, color: Colors.blue),
            ),
            SizedBox(height: 40),
            ElevatedButton(
              onPressed: _isLoading ? null : _handlePay,
              child: _isLoading
                  ? CircularProgressIndicator()
                  : Text('Pay with ${widget.platform.toUpperCase()}'),
            ),
            SizedBox(height: 20),
            TextButton(
              onPressed: () async {
                await PaymentFactory.cancelOrder(widget.orderId);
                _updateStatus('Order cancelled');
              },
              child: Text('Cancel Order'),
            ),
            TextButton(
              onPressed: () async {
                await PaymentFactory.deliverOrder(widget.orderId);
                _updateStatus('Order delivered');
              },
              child: Text('Deliver Order'),
            ),
            TextButton(
              onPressed: () async {
                await PaymentFactory.expireOrder(widget.orderId);
                _updateStatus('Order expired');
              },
              child: Text('Expire Order'),
            ),
            TextButton(
              onPressed: () async {
                await PaymentFactory.successOrder(widget.orderId);
                _updateStatus('Payment successful');
              },
              child: Text('Mark as Success'),
            ),
          ],
        ),
      ),
    );
  }

  void _handlePay() async {
    setState(() {
      _isLoading = true;
      _status = 'Processing...';
    });
    final result = await PaymentFactory.pay(
      amount: widget.amount,
      orderId: widget.orderId,
      platform: widget.platform,
      description: widget.description,
    );
    setState(() {
      _isLoading = false;
      if (result) {
        _status = 'Payment successful';
      } else {
        _status = 'Payment failed';
      }
    });
  }

  void _updateStatus(String status) {
    setState(() {
      _status = status;
    });
  }
}
