// server.js
const express = require('express');
const multer = require('multer');
const path = require('path');
const fs = require('fs').promises;
const { v4: uuidv4 } = require('uuid');

const app = express();
const PORT = process.env.PORT || 3000;

// Middleware
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// Chunk storage: save chunks to ./files/<filename>-<chunkId>
const CHUNK_DIR = path.join(__dirname, 'files');
if (!fs.existsSync(CHUNK_DIR)) {
  fs.mkdir(CHUNK_DIR, { recursive: true });
}

// Storage for chunks (each chunk saved separately)
const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    const filename = req.body.filename || 'unknown';
    const chunkId = req.body.chunkId;
    const chunkPath = path.join(CHUNK_DIR, `${filename}-${chunkId}`);
    fs.mkdir(path.dirname(chunkPath), { recursive: true }, (err) => {
      if (err) return cb(err);
      cb(null, path.dirname(chunkPath));
    });
  },
  filename: (req, file, cb) => {
    const filename = req.body.filename || 'unknown';
    const chunkId = req.body.chunkId;
    cb(null, `${filename}-${chunkId}`);
  },
});

const upload = multer({ storage });

app.post('/api/chunk', upload.single('file'), async (req, res) => {
  try {
    const { filename, chunkId, totalChunks } = req.body;

    // If this is the last chunk, reconstruct the file
    if (chunkId === totalChunks - 1) {
      await reconstructFile(filename, totalChunks);
      return res.json({ success: true, message: 'File uploaded successfully' });
    }

    // Otherwise, just save the chunk
    res.json({ success: true, message: `Chunk ${chunkId} saved` });
  } catch (err) {
    console.error(err);
    res.status(500).json({ success: false, message: err.message });
  }
});

// Reconstruct chunks into final file
async function reconstructFile(filename, totalChunks) {
  const chunks = [];
  for (let i = 0; i < totalChunks; i++) {
    const chunkPath = path.join(CHUNK_DIR, `${filename}-${i}`);
    const chunkData = await fs.readFile(chunkPath);
    chunks.push(chunkData);
  }

  const finalPath = path.join(CHUNK_DIR, filename);
  await fs.writeFile(finalPath, Buffer.concat(chunks));
  // Clean up chunk files
  for (let i = 0; i < totalChunks; i++) {
    try {
      await fs.unlink(path.join(CHUNK_DIR, `${filename}-${i}`));
    } catch (e) {
      // ignore
    }
  }
  console.log(`Reconstructed: ${finalPath}`);
}

app.get('/api/files', async (req, res) => {
  try {
    const files = await fs.readdir(CHUNK_DIR);
    res.json(files);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get('/api/files/:filename', async (req, res) => {
  const { filename } = req.params;
  const fullPath = path.join(CHUNK_DIR, filename);
  try {
    const stat = await fs.stat(fullPath);
    res.set('Content-Type', 'application/octet-stream');
    res.set('Content-Disposition', `attachment; filename="${filename}"`);
    res.send(await fs.readFile(fullPath));
  } catch (err) {
    res.status(404).json({ error: 'File not found' });
  }
});

app.get('/', (req, res) => {
  res.redirect('/index.html');
});

app.use(express.static('public'));

app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

